function walk(dir, rel = "") {
  const out = [];
  if (!fs.existsSync(path.join(dir, rel))) return out;
  for (const e of fs.readdirSync(path.join(dir, rel)).sort()) {
    const r = rel ? `${rel}/${e}` : e;
    if (fs.statSync(path.join(dir, r)).isDirectory()) out.push(...walk(dir, r));
    else out.push({ rel: r, abs: path.join(dir, r) });
  }
  return out;
}

/** The subset of server.js validate() that applies to hand-written sources (no YAML library on the build host checkout). */
function validateYml(text, javaFiles) {
  const problems = [];
  const top = (k) => { const m = text.match(new RegExp(`^${k}:\\s*['"]?([^'"\\n]*)['"]?\\s*$`, "m")); return m ? m[1].trim() : null; };
  if (!/^[A-Za-z0-9_]{1,40}$/.test(top("name") || "")) problems.push("plugin.yml name must be 1-40 letters, digits or underscores.");
  if (!top("version")) problems.push("plugin.yml needs a version.");
  if (top("api-version") !== "@API@") problems.push("golden plugin.yml must use api-version: '@API@' (the harness pins it per version, like the build service).");
  if (/^libraries:/m.test(text)) problems.push(librariesProblem({ libraries: [] }));
  const main = top("main") || "";
  if (!javaFiles.some((f) => f.rel === main.replace(/\./g, "/") + ".java")) problems.push(`plugin.yml main ${main} has no source file.`);
  const cmds = new Set();
  const sec = text.match(/^commands:\n((?:[ \t].*\n?|\n)*)/m);
  if (sec) for (const m of sec[1].matchAll(/^  ([A-Za-z0-9_-]+):/gm)) cmds.add(m[1].toLowerCase());
  for (const f of javaFiles) {
    const src = fs.readFileSync(f.abs, "utf8");
    for (const m of src.matchAll(/getCommand\(\s*"([^"]+)"\s*\)/g)) if (!cmds.has(m[1].toLowerCase())) problems.push(`${f.rel} calls getCommand("${m[1]}") but plugin.yml has no command "${m[1]}".`);
    if (/^\s*public\s+final\s+class\s+\w+\s+extends\s+JavaPlugin/m.test(src)) problems.push(`${f.rel}: the main class must not be final.`);
  }
  return { problems, commands: [...cmds].sort(), name: top("name") };
}

/**
 * Sources for one version: src/ plus per-version overlays `src@<v>` (exactly that version) or `src@<v>+` (that version
 * and newer); the most specific overlay wins per file. Used for the few APIs that differ (e.g. a Compat.java).
 */
function sourcesFor(dir, v) {
  const files = new Map(walk(path.join(dir, "src")).map((f) => [f.rel, f]));
  const overlays = fs.readdirSync(dir).filter((d) => d.startsWith("src@")).map((d) => ({ d, spec: d.slice(4) }))
    .filter(({ spec }) => (spec.endsWith("+") ? ge(v, spec.slice(0, -1)) : spec === v))
    .sort((a, b) => (a.spec.endsWith("+") === b.spec.endsWith("+") ? (ge(a.spec.replace("+", ""), b.spec.replace("+", "")) ? 1 : -1) : a.spec.endsWith("+") ? -1 : 1));
  for (const { d } of overlays) for (const f of walk(path.join(dir, d))) files.set(f.rel, f);
  return [...files.values()].sort((a, b) => (a.rel < b.rel ? -1 : 1));
