};

/** The full pre-build plan for the plan screen (and the server-side plan of a build that came without one). */
export async function buildModPlan(input: { text: string; game: string; mcVersion: string; tier: TokenTier | null; change?: boolean; toggles?: Partial<Record<Lane, boolean>>; cfg?: TokenConfig | null; needs?: LaneNeed[] | null; source?: Needs["source"]; /** planner cost/time/error when `needs` came from analyzeNeeds already */ meta?: Pick<Needs, "costUsd" | "ms" | "error"> },
  deps: PlannerDeps & { flags?: Record<string, boolean> } = {}): Promise<PlanResponse> {
  const needs: Needs = input.needs ? { source: input.source ?? "rules", lanes: input.needs, ...(input.meta ?? {}) } : await analyzeNeeds({ text: input.text, game: input.game, mcVersion: input.mcVersion }, deps);
  const { ctx, catalogue } = capabilityContext(input.game, input.mcVersion, deps.flags ?? hostFlags());
  const plan = decidePlan({ needs: needs.lanes, source: needs.source, catalogue, ctx, plan: input.tier, change: input.change, toggles: input.toggles });
  const lanes = builtLanes(plan);
  const allowed = input.tier ? modelsFor(input.tier) : (["katara", "saka", "yakko"] as CyrusModelId[]);
  const cfg = input.cfg ?? null;
  const models: ModelOption[] = planEstimates(input.text, lanes, { change: input.change }).map((e) => {
    const tokens: [number, number] | null = cfg ? [tokensForCost(e.usd[0], e.model, cfg), tokensForCost(e.usd[1], e.model, cfg)] : null;
    return { model: e.model, usd: e.usd, upTo: e.upTo, minutes: e.minutes, tokens, hold: cfg ? holdRange(e.model, e.complexity, cfg, e.usd)[1] : null, allowed: allowed.includes(e.model) };
  });
  return {
    plan, assets: toAssetsRequest(plan), models, auto: autoModel(input.text, lanes, allowed),
    planner: { source: needs.source, costUsd: needs.costUsd ?? 0, ms: needs.ms ?? null, error: needs.error ?? null },
  };
}
// Cyrus mod planner: cost and time per model for a PLANNED build (pure, client-safe). The base is lib/cyrus/estimate.ts
// (measured builds); every lane the plan BUILDS adds its share (asset specs, designs and data packs are extra files the
// model writes and checks). Blocked lanes are never counted: the estimate is for what will really be built.
import { CHANGE_COST_FACTOR, estimate, type Complexity } from "../estimate";
import { CYRUS_MODEL_IDS, cyrusModel, type CyrusModelId } from "../models";
import type { Lane } from "./lanes";

/** Extra share of a plain build's cost per built lane (time grows at 60% of that). Rough, from the R1-R5 flights. */
export const LANE_WEIGHT: Readonly<Partial<Record<Lane, number>>> = {
  texture: 0.25, itemStates: 0.1, sound: 0.2, model3d: 0.15, creature: 0.45, designItem: 0.15, designMenu: 0.15,
  designQuest: 0.2, designBoss: 0.25, designHud: 0.1, motion: 0.15, config: 0.05, datapack: 0.15, worldgen: 0.35, library: 0,
};

/**
 * MEASURED whole-build cost at Saka (costFactor 1) INCLUDING repairs, per lane group: eval first1 (2026-10-13, 59 real builds
 * through the service, journal /root/cyrus-eval/first1). p50 / p80 / p90 over every build of that group, retries and all.
 * The usual range is 0.7 x p50 .. p80 (never below the lane-weighted estimate); "up to" is p90 or 1.25 x the high end.
 * Re-measure after the first-pass reliability changes land (fewer repairs should pull p80/p90 down): scripts/cyrus/eval-journal-stats.ts.
 */
export const MEASURED_SAKA = {
  texture: { n: 16, p50: 0.42, p80: 0.66, p90: 0.76 },
  sound: { n: 7, p50: 0.57, p80: 0.61, p90: 0.62 },
  designer: { n: 20, p50: 0.36, p80: 0.58, p90: 0.65 },
} as const;
type MeasuredGroup = keyof typeof MEASURED_SAKA;
const GROUP_OF: Readonly<Partial<Record<Lane, MeasuredGroup>>> = {
  texture: "texture", itemStates: "texture", model3d: "texture", sound: "sound",
  designItem: "designer", designMenu: "designer", designQuest: "designer", designBoss: "designer", designHud: "designer", motion: "designer",
};

export type ModelEstimate = { model: CyrusModelId; complexity: Complexity; usd: [number, number]; /** "up to $x if it needs fixes" (a retried build costs about twice a clean one) */ upTo: number; minutes: [number, number] };

const r2 = (n: number) => Math.max(0.01, Math.round(n * 100) / 100);

export function planEstimate(text: string, model: CyrusModelId, lanes: readonly Lane[], opts: { change?: boolean } = {}): ModelEstimate {
  const e = estimate(text, model, opts);
  const w = lanes.reduce((a, l) => a + (LANE_WEIGHT[l] ?? 0), 0);
  const k = 1 + w;
  const t = 1 + w * 0.6;
  const minutes: [number, number] = [Math.max(1, Math.round(e.minutes[0] * t)), Math.max(2, Math.round(e.minutes[1] * t))];
  if (minutes[1] <= minutes[0]) minutes[1] = minutes[0] + 1;
  let lo = e.usd[0] * k, hi = e.usd[1] * k, p90 = 0;
  // the heaviest measured lane group present sets a floor (measured at Saka; scaled by the model's cost factor, changes by theirs)
  // measured at Saka only: Katara scales down by its cost factor; Yakko keeps its factor-based figure (already above these floors)
  const cf = Math.min(1, cyrusModel(model).costFactor) * (opts.change ? CHANGE_COST_FACTOR : 1);
  for (const l of lanes) {
    const g = GROUP_OF[l];
    if (!g) continue;
    const m = MEASURED_SAKA[g];
    lo = Math.max(lo, 0.7 * m.p50 * cf); hi = Math.max(hi, m.p80 * cf); p90 = Math.max(p90, m.p90 * cf);
  }
  if (hi <= lo) hi = lo * 1.3;
  const upTo = Math.max(hi * 1.25, p90);
  return { model, complexity: e.complexity, usd: [r2(lo), r2(hi)], upTo: r2(upTo), minutes };
}

export const planEstimates = (text: string, lanes: readonly Lane[], opts: { change?: boolean } = {}): ModelEstimate[] =>
  CYRUS_MODEL_IDS.map((m) => planEstimate(text, m, lanes, opts));

/**
 * The DEFAULT ("Auto") model: the cheapest model that is capable of the request. Katara only for trivial plain code
 * (the 2026-10-07 eval: the small model took 2x the turns on anything with structure), Saka for most mods (any asset or
 * designer lane), Yakko only for complex requests. Capped to what the plan unlocks (best allowed below the pick).
 */
export function autoModel(text: string, lanes: readonly Lane[], allowed: readonly CyrusModelId[] = CYRUS_MODEL_IDS): CyrusModelId {
  const e = estimate(text, "saka");
  const structured = lanes.some((l) => l !== "config");
  const pick: CyrusModelId = e.complexity === "complex" ? "yakko" : e.complexity === "simple" && !structured && e.score < 1.5 ? "katara" : "saka";
  const order: CyrusModelId[] = ["katara", "saka", "yakko"];
  if (allowed.includes(pick)) return pick;
  const below = order.slice(0, order.indexOf(pick) + 1).reverse().find((m) => allowed.includes(m));
  return below ?? allowed[0] ?? "katara";
}

import { NextResponse } from "next/server";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { NOT_FOUND } from "@/app/api/mod-builder/_lib";
import { checkRateLimit } from "@/lib/rate-limit";
import { promptProblem } from "@/lib/cyrus/prompt-check";
import { MB_VERSIONS } from "@/lib/modbuilder/types";
import { getVersion } from "@/lib/cyrus/versions/registry";
import { analyzeNeeds, buildModPlan, type PlannerDeps } from "@/lib/cyrus/planner/run";
import { isLane, type Lane } from "@/lib/cyrus/planner/lanes";
import { svcHealthCached, svcPlan } from "@/lib/cyrus/builder/client";
import { tierOf, tokensActiveFor } from "@/lib/cyrus/tokens/access";
import { loadTokenConfig } from "@/lib/cyrus/tokens/config";
import { coachOn } from "@/lib/cyrus/coach/flags";
import { analyzePrompt } from "@/lib/cyrus/coach/analyze";
import { techniquesOn } from "@/lib/cyrus/designer/spec";
import { changeLaneDefaults, parseChangeContext } from "@/lib/cyrus/coach/plan-hook";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * Cyrus mod planner (live-test fix F): the pre-build PLAN for the plan screen. POST { prompt, mcVersion, change?, toggles? }
 * -> lanes (build / skip / blocked with plain warnings), what will be created, cost / time / tokens per model and the
 * Auto model. Nothing is held or charged here; the planner model call (~$0.001) is Nxeon's cost, rate-limited, and the
 * deterministic rules answer whenever it is unavailable. Same private-preview gate as the rest of Cyrus.
 * Prompt coach (CYRUS_PROMPT_COACH=1 only; off = this response is unchanged): adds `coach` (lib/cyrus/coach/analyze.ts,
 * deterministic, zero cost) and, on a change request, leaves out new generative lanes the change text does not ask for
 * (`coachHeld`; an explicit toggle always wins). Optional body field `base` = { name, version, summary, paths } of the
 * mod the change lands on (bounded; only feeds the "what will be kept" lines).
 */
export async function POST(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  let body: { prompt?: unknown; mcVersion?: unknown; change?: unknown; toggles?: unknown; game?: unknown; base?: unknown };
  try { body = (await req.json()) as typeof body; } catch { return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 }); }
  const prompt = typeof body.prompt === "string" ? body.prompt.trim().slice(0, 4000) : "";
  if (prompt.length < 4) return NextResponse.json({ error: "Describe the mod first." }, { status: 400 });
  const unclear = promptProblem(prompt);
  if (unclear) return NextResponse.json({ error: unclear, code: "prompt_unclear" }, { status: 400 });
  const mcVersion = typeof body.mcVersion === "string" && getVersion(body.mcVersion) ? body.mcVersion : MB_VERSIONS[0];
  const rl = checkRateLimit(`cy:plan:${user.id}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Planning fast! Try again in ${rl.retryAfterSec}s.` }, { status: 429 });
  const toggles: Partial<Record<Lane, boolean>> = {};
  if (body.toggles && typeof body.toggles === "object" && !Array.isArray(body.toggles)) for (const [k, v] of Object.entries(body.toggles as Record<string, unknown>)) if (isLane(k) && typeof v === "boolean") toggles[k] = v;
  const cfg = await loadTokenConfig().catch(() => null);
  const metered = cfg ? await tokensActiveFor(user, cfg).catch(() => false) : false;
  const tier = await tierOf(user.id, cfg ?? undefined).catch(() => null);
  const deps: PlannerDeps = { ask: (b) => svcPlan(b), supports: async () => ((await svcHealthCached())?.features as { planner?: unknown } | undefined)?.planner === true };
  const change = body.change === true;
  const coach = coachOn();
  // Coach hook (change requests): never pre-select a new generative lane the change text does not ask for.
  let held: Lane[] = [];
  let pre: Awaited<ReturnType<typeof analyzeNeeds>> | null = null;
  if (coach && change) {
    pre = await analyzeNeeds({ text: prompt, game: "minecraft", mcVersion }, deps);
    held = changeLaneDefaults(prompt, pre.lanes, toggles);
    for (const l of held) toggles[l] = false;
  }
  const out = await buildModPlan(
    { text: prompt, game: "minecraft", mcVersion, tier, change, toggles, cfg: metered ? cfg : null, ...(pre ? { needs: pre.lanes, source: pre.source, meta: { costUsd: pre.costUsd, ms: pre.ms, error: pre.error } } : {}) },
    deps,
  );
  const buildable = !!getVersion(mcVersion)?.buildable;
  if (!coach) return NextResponse.json({ ...out, buildable }, { headers: { "Cache-Control": "no-store" } });
  const base = change ? (parseChangeContext(body.base) ?? { name: "this mod" }) : null;
  const report = analyzePrompt({ text: prompt, version: mcVersion, change: base, lanes: out.plan.lanes, held, techniques: techniquesOn() });
  return NextResponse.json({ ...out, buildable, coach: report, coachHeld: held }, { headers: { "Cache-Control": "no-store" } });
}
