// Cyrus builds and tokens: gate + reserve when a build starts, settle when it ends.
// Server only; plain module (store.ts calls settleBuildTokens from the worker sweep too).
import type { ModBuild, User } from "@prisma/client";
import { cyrusDb as db } from "../db";
import { cyrusModel, isCyrusModel, type CyrusModelId } from "../models";
import { readCyrusMeta } from "../meta";
import { loadTokenConfig } from "./config";
import { canUseModel, complexityOf, dailyCapFor, defaultModelFor, holdRange, modelsFor, reserveAmount, settleCharge, TIER_LABEL, tierForModel, fmt } from "./economy";
import { autoModel, planEstimate } from "../planner/estimate";
import type { Lane } from "../planner/lanes";
import { reserveTokens, settleReservation } from "./ledger";
import { tierOf, tokensActiveFor } from "./access";
import { ensureStarterTokens } from "./starter";

const DAY = 86_400_000;

export type BuildGate =
  | { ok: true; model: CyrusModelId | undefined; reserved: number | null; tracked: boolean }
  | { ok: false; status: number; code: "model_locked" | "insufficient_tokens" | "daily_cap" | "launch_pair"; error: string; need?: number; available?: number; model?: CyrusModelId; tier?: string };

/**
 * Decide the model and hold tokens for a build that is about to start. Call AFTER the
 * request is validated and rate-limited, BEFORE the ModBuild row is created, with the id
 * the row will get. Accounts outside the token economy (not live, not preview) pass
 * through unchanged (`tracked: false`), keeping the pre-token behaviour.
 */
export async function gateBuild(i: { user: User; buildId: string; requested: CyrusModelId | undefined; baseModel: CyrusModelId | undefined; text: string; now?: Date;
  /** Live-test fix (C2): "Auto" = the cheapest capable model for the request and its planned lanes (lib/cyrus/planner/estimate.ts autoModel). */
  auto?: boolean;
  /** Live-test fix (C1): the lanes this build really builds; the hold follows their estimate (holdRange). */
  lanes?: readonly Lane[];
  change?: boolean }): Promise<BuildGate> {
  const cfg = await loadTokenConfig();
  // Defence in depth for the launch pair (lib/cyrus/launch-state.ts): a build that reaches here with the token economy
  // not active for this account must not run unmetered. Private-preview accounts are always "active", so this only
  // ever refuses a public account while cyrus_studio_public_enabled is on and cyrus_tok_live is off.
  if (!(await tokensActiveFor(i.user, cfg))) return { ok: false, status: 403, code: "launch_pair", model: i.requested ?? i.baseModel, error: "Cyrus building isn't open yet." };
  const now = i.now ?? new Date();
  await ensureStarterTokens(i.user, cfg);
  const tier = await tierOf(i.user.id, cfg, now);
  let model: CyrusModelId = i.requested ?? (i.auto ? autoModel(i.text, i.lanes ?? [], modelsFor(tier)) : i.baseModel ?? defaultModelFor(tier));
  // A change to a version built on a locked model falls back to the best allowed one
  // unless the customer explicitly asked for the locked model.
  if (!i.requested && !canUseModel(tier, model)) model = defaultModelFor(tier);
  if (cfg.enforce && !canUseModel(tier, model)) {
    const need = tierForModel(model);
    return { ok: false, status: 403, code: "model_locked", model, tier, error: `${cyrusModel(model).name} unlocks with the ${TIER_LABEL[need]} plan. Get tokens to unlock it, or pick ${tier === "free" || tier === "katara" ? "Katara" : "Saka"}.` };
  }
  const range = holdRange(model, complexityOf(i.text), cfg, i.lanes ? planEstimate(i.text, model, i.lanes, { change: i.change }).usd : undefined);
  const r = await reserveTokens({
    userId: i.user.id, buildId: i.buildId, model, need: range[0], now,
    pick: (available) => reserveAmount(available, range),
    dailyCap: () => dailyCapFor(i.user.createdAt, now, cfg),
    allowShort: !cfg.enforce,
  });
  if (!r.ok) {
    if (r.code === "daily_cap") return { ok: false, status: 429, code: "daily_cap", error: `You've used today's Cyrus limit (${fmt(r.cap ?? 0)} tokens a day). It frees up over the next 24 hours.` };
    return { ok: false, status: 402, code: "insufficient_tokens", need: range[0], available: r.available, model, error: `This build needs about ${fmt(range[0])} tokens and you have ${fmt(r.available)}. Get tokens to keep building.` };
  }
  return { ok: true, model, reserved: r.amount, tracked: true };
}

/** A build that never reached the builder (create failed): give the whole hold back. */
export async function releaseBuildTokens(buildId: string): Promise<void> {
  await settleReservation({ buildId, charge: 0, reason: "not_started" }).catch((e) => console.error("[cyrus-tokens] release failed", buildId, (e as Error).message));
}

/**
 * Settle a FINISHED build against its hold. Idempotent (no-op for unheld or non-terminal
 * builds), so the routes, the page loader and the worker can all call it.
 */
export async function settleBuildTokens(row: Pick<ModBuild, "id" | "userId" | "status" | "errorCode" | "costUsd" | "cyrus">, now = new Date()): Promise<void> {
  if (row.status !== "succeeded" && row.status !== "failed") return;
  const res = await db.cyrusTokenReservation.findUnique({ where: { buildId: row.id } });
  if (!res || res.status !== "held") return;
  const cfg = await loadTokenConfig();
  const model: CyrusModelId = isCyrusModel(res.model) ? res.model : (readCyrusMeta(row.cyrus).model ?? "saka");
  const freeFailuresUsed = await db.cyrusTokenLedger.count({ where: { userId: row.userId, note: "failed_free", createdAt: { gt: new Date(now.getTime() - cfg.freeFailuresDays * DAY) } } });
  const d = settleCharge({ status: row.status, errorCode: row.errorCode, costUsd: row.costUsd || 0, model, freeFailuresUsed }, cfg);
  await settleReservation({ buildId: row.id, charge: d.charge, reason: d.reason, costUsd: row.costUsd || 0, now });
}

export async function safeSettle(row: Parameters<typeof settleBuildTokens>[0]): Promise<void> {
  try { await settleBuildTokens(row); } catch (e) { console.error("[cyrus-tokens] settle failed", row.id, (e as Error).message); }
}
