// Cyrus LEARNING LOOP step 3: the MINING JOB's pure core. Clusters failed / reworked / regressed builds into CANDIDATE items for a
// human to review. It never writes to a rule file, a sheet, a prompt or a router: output is data (candidates.jsonl + a review page),
// every item has status "candidate" and carries the build ids it came from.
//
// Kinds: failure-rule (a compile / Test Flight failure pattern), sheet-fact (an API fact the sheet seems to lack),
// golden-case (a request that must keep working), routing-rule (which tier may take which change), prompt-coach-gap (the
// planner / guard / coach should have asked or warned).
import { createHash } from "node:crypto";
import type { BuildSignals, Regression } from "./types";

export const CANDIDATE_KINDS = ["failure-rule", "sheet-fact", "golden-case", "routing-rule", "prompt-coach-gap"] as const;
export type CandidateKind = (typeof CANDIDATE_KINDS)[number];

export type Candidate = {
  id: string;
  kind: CandidateKind;
  title: string;
  /** Build ids (ModBuild.id) the item was derived from. Never user text. */
  evidence: string[];
  proposedText: string;
  /** 0..1: more independent builds, a rework or a regression that confirms it, and an owner-visible loss raise it. */
  confidence: number;
  rationale: string;
  status: "candidate";
  /** Which signal produced it (so a reviewer can re-derive it). */
  signal: string;
};

/** Optional text the job may attach when asked (--include-prompts). The default run passes none and no user text is read. */
export type MiningText = { changeRequest?: string | null };
export type MiningOptions = {
  /** Build id -> text, only when the operator opted in. */
  text?: Record<string, MiningText>;
  /** A pattern is a candidate from this many independent builds (default 1: a single owner-visible loss is enough to review). */
  minEvidence?: number;
  /** Put class / command names into proposed text (staff-local review). Default off: counts only, so a candidates file carries no mod names. */
  includeNames?: boolean;
};

const CORRECTION = /\b(doesn'?t|does not|didn'?t|still|again|not working|isn'?t|broken|wrong|instead|should(?:n'?t)?|only|no longer|stopped|missing|but)\b/i;

export const candidateId = (kind: string, title: string) => createHash("sha256").update(`${kind}\n${title}`).digest("hex").slice(0, 12);
const clamp = (n: number) => Math.max(0.05, Math.min(0.95, Math.round(n * 100) / 100));
const ids = (l: BuildSignals[]) => l.map((s) => s.id);
const list = (a: string[], n = 6) => (a.length > n ? a.slice(0, n).join(", ") + `, +${a.length - n} more` : a.join(", ")) || "(none)";

function make(kind: CandidateKind, title: string, evidence: string[], proposedText: string, confidence: number, rationale: string, signal: string): Candidate {
  return { id: candidateId(kind, title), kind, title, evidence: [...new Set(evidence)], proposedText, confidence: clamp(confidence), rationale, status: "candidate", signal };
}


export function mineCandidates(sigs: BuildSignals[], opts: MiningOptions = {}): Candidate[] {
  const out: Candidate[] = [];
  const min = opts.minEvidence ?? 1;
  const byId = new Map(sigs.map((s) => [s.id, s]));
  const text = (id: string) => opts.text?.[id]?.changeRequest ?? null;
  const names = (a: string[], n = 12) => (opts.includeNames ? list(a, n) : `${a.length} name(s) withheld`);

  // 1. Regressions: a change build removed commands / classes that its base (or the last good build) had. One item per compared base
  // (builds that drifted from the same good build are one problem, not three).
  const regByBase = new Map<string, { base: string; builds: BuildSignals[]; r: Regression }>();
  for (const s of sigs) {
    const r = s.regression?.severity === "major" ? s.regression : s.regressionVsGood?.severity === "major" ? s.regressionVsGood : null;
    if (!r) continue;
    const g = regByBase.get(r.baseId) ?? { base: r.baseId, builds: [], r };
    g.builds.push(s);
    if (r.removedCommands.length > g.r.removedCommands.length) g.r = r;
    regByBase.set(r.baseId, g);
  }
  for (const { base, builds, r } of regByBase.values()) {
    const confirmed = builds.some((s) => s.rework.reworked || s.regression?.severity === "major");
    const lanes = [...new Set(builds.flatMap((s) => s.lanes))];
    const evidence = [base, ...ids(builds)];
    out.push(make("golden-case", `Change keeps the base's commands and classes (base ${base.slice(0, 10)})`, evidence,
      JSON.stringify({ case: "change-keeps-surface", baseBuild: base, changeBuilds: ids(builds), ...(opts.includeNames ? { mustKeepCommands: r.removedCommands, mustKeepClasses: r.removedClasses.slice(0, 12) } : { mustKeepCommands: r.removedCommands.length, mustKeepClasses: r.removedClasses.length }), note: "a change request that does not ask for removal must not drop these" }),
      0.45 + 0.1 * Math.min(3, builds.length) + (confirmed ? 0.15 : 0) + (r.removedCommands.length ? 0.1 : 0),
      `${builds.length} change build(s) (${list(ids(builds), 4)}) dropped ${r.removedCommands.length} command(s) and ${r.removedClasses.length}/${r.baseCounts.classes} class(es) of ${base}${builds.some((s) => s.rework.reworked) ? "; one was followed by another change within the rework window" : ""}.`, "regression"));
    out.push(make("prompt-coach-gap", `Plan must say what a change removes (base ${base.slice(0, 10)})`, evidence,
      `Before a change build starts, show the plan's "keeps / replaces / removes" list built from the base build's commands (${names(r.removedCommands)}) and classes; ask when a planned lane would replace the main class${lanes.length ? ` (planned lanes: ${lanes.join(", ")})` : ""}.`,
      0.4 + 0.1 * Math.min(3, builds.length) + (confirmed ? 0.15 : 0), `The change replaced the plugin instead of extending it; the customer finds out after installing.`, "regression"));
  }

  // 2. Routing: Haiku (katara) change builds that regressed / were reworked on large plugins or planned lanes.
  const haikuBad = sigs.filter((s) => s.kind === "change" && s.family === "haiku" && (s.regressionVsGood?.severity === "major" || s.regression?.severity === "major" || s.rework.reworked)
    && ((s.regression?.baseCounts.classes ?? s.regressionVsGood?.baseCounts.classes ?? 0) >= 10 || s.lanes.length > 0 || s.turns >= 18));
  if (haikuBad.length >= min) out.push(make("routing-rule", "Change builds on large or lane-planned plugins skip the smallest model", ids(haikuBad),
    `route.js: for a change request whose base build has >= 10 classes, or whose plan has a lane, set the route floor to saka (Sonnet).`,
    0.35 + 0.1 * Math.min(4, haikuBad.length), `${haikuBad.length} Haiku change build(s) were reworked or regressed on such plugins (turns: ${haikuBad.map((s) => s.turns).join(", ")}).`, "tier-vs-outcome"));

  // 3. Guard refusals followed by a successful build: the guard refused something the customer was allowed to ask.
  for (const s of sigs.filter((x) => x.guardRefusal)) {
    const after = sigs.find((x) => x.rootId === s.rootId && x.createdAtMs > s.createdAtMs && x.outcome === "success");
    if (!after && s.kind === "fresh") continue;
    out.push(make("golden-case", `Guard accepts this ${s.kind} request (${s.id.slice(0, 10)})`, [s.id, ...(after ? [after.id] : [])],
      JSON.stringify({ case: "guard-accepts", refusedBuild: s.id, reason: s.guardReason, kind: s.kind, requestText: text(s.id) ?? "(withheld; run with --include-prompts or open the build)" }),
      0.55 + (after ? 0.15 : 0), `Build ${s.id} was refused by the intake guard (${s.guardReason ?? "no reason recorded"})${after ? ` and ${after.id} on the same lineage then succeeded` : ""}.`, "guard-refusal"));
    out.push(make("prompt-coach-gap", "Guard prompt needs change-request examples", [s.id],
      `GUARD_PROMPT: add a short list of accepted change-request phrasings ("keep everything as is, only change ...") so detailed edit instructions are not read as injection.`, 0.4 + (s.kind === "change" ? 0.15 : 0), `Refused as ${s.guardReason ?? "unknown"} on a ${s.kind} request.`, "guard-refusal"));
  }

  // 4. Test Flight failures by failed check id.
  const tf = new Map<string, BuildSignals[]>();
  for (const s of sigs) for (const c of s.testFlight.failedChecks) (tf.get(c) ?? tf.set(c, []).get(c)!).push(s);
  for (const [check, l] of tf) if (l.length >= min) out.push(make("failure-rule", `Test Flight check "${check}" fails`, ids(l),
    `Add a failure rule keyed on the Test Flight check "${check}" (lanes: ${[...new Set(l.flatMap((s) => s.lanes))].join(", ") || "plain"}; versions: ${[...new Set(l.map((s) => s.mcVersion))].join(", ")}). Read the flight log of the evidence builds for the exact message before writing it.`,
    0.4 + 0.1 * Math.min(4, l.length), `${l.length} build(s) failed the "${check}" check.`, "testflight"));

  // 5. Repair-heavy builds: clusters by lane + number of repair attempts (the error text itself is not stored; see report: data gaps).
  const repairHeavy = sigs.filter((s) => s.repairs >= 2 || s.attempts >= 3 || (s.callsByKind["repair-asset"]?.turns ?? 0) >= 3);
  const byLane = new Map<string, BuildSignals[]>();
  for (const s of repairHeavy) (byLane.get(s.laneKey) ?? byLane.set(s.laneKey, []).get(s.laneKey)!).push(s);
  for (const [lane, l] of byLane) if (l.length >= min) out.push(make("failure-rule", `Repair-heavy builds in lane "${lane}"`, ids(l),
    `Investigate the repair loops of ${list(ids(l))}: read each build's repair events for the compiler / asset error shape, then write one failure rule per shape in the rules file. (Error text is not stored in ModBuild; read the repair log on the build service.)`,
    0.25 + 0.1 * Math.min(4, l.length), `${l.length} build(s) needed >= 2 repairs / >= 3 attempts in lane ${lane}; total repair spend $${l.reduce((a, s) => a + (s.callsByKind.repair?.costUsd ?? 0) + (s.callsByKind["repair-asset"]?.costUsd ?? 0), 0).toFixed(3)}.`, "repairs"));

  // 6. Sheet facts: builds that needed several API lookups point at facts the version sheet lacks.
  const lookups = sigs.filter((s) => s.events.apiLookups >= 2);
  if (lookups.length >= min) out.push(make("sheet-fact", "API facts the sheet lacks (builds with repeated API lookups)", ids(lookups),
    `Read the API lookups of ${list(ids(lookups))} in the build service logs; add the classes / methods looked up more than once to the version sheet.`, 0.2 + 0.08 * Math.min(5, lookups.length),
    `${lookups.length} build(s) did >= 2 API lookups while repairing (versions: ${[...new Set(lookups.map((s) => s.mcVersion))].join(", ")}).`, "api-lookups"));

  // 7. Rework with correction language in the follow-up (only when the operator supplied the text).
  for (const s of sigs.filter((x) => x.rework.reworked && x.rework.byId)) {
    const t = text(s.rework.byId!);
    if (t && CORRECTION.test(t)) out.push(make("prompt-coach-gap", `Request was corrected right after delivery (${s.id.slice(0, 10)})`, [s.id, s.rework.byId!],
      `The follow-up reads as a correction ("${t.slice(0, 120)}"): add the missing detail to the coach checklist for the original request's category.`, 0.4 + (byId.get(s.rework.byId!)?.outcome === "success" ? 0.1 : 0),
      `${s.rework.gapMin} min after ${s.id} the next change arrived with correction wording.`, "rework"));
  }

  // merge duplicates by id (same kind + title), keep the highest confidence and union the evidence
  const merged = new Map<string, Candidate>();
  for (const c of out) { const e = merged.get(c.id); merged.set(c.id, e ? { ...e, evidence: [...new Set([...e.evidence, ...c.evidence])], confidence: Math.max(e.confidence, c.confidence) } : c); }
  return [...merged.values()].sort((a, b) => b.confidence - a.confidence || a.id.localeCompare(b.id));
}

export function toJsonl(cands: Candidate[]): string {
  return cands.map((c) => JSON.stringify(c)).join("\n") + (cands.length ? "\n" : "");
}

export function parseJsonl(text: string): Candidate[] {
  const out: Candidate[] = [];
  for (const line of text.split("\n")) {
    if (!line.trim()) continue;
    try {
      const c = JSON.parse(line) as Candidate;
      if ((CANDIDATE_KINDS as readonly string[]).includes(c.kind) && typeof c.id === "string" && Array.isArray(c.evidence)) out.push(c);
    } catch { /* skip a damaged line */ }
  }
  return out;
}

export function reviewMarkdown(cands: Candidate[], meta: { generatedAt: string; builds: number }): string {
  const L = [`# Learning loop: candidates for review`, "", `Generated ${meta.generatedAt} from ${meta.builds} build(s). Every item is a CANDIDATE: nothing here is applied. Accept = a human writes the rule / sheet / golden case / routing change in a normal branch with tests; reject = delete the line.`, ""];
  for (const kind of CANDIDATE_KINDS) {
    const l = cands.filter((c) => c.kind === kind);
    L.push(`## ${kind} (${l.length})`, "");
    if (!l.length) { L.push("_none_", ""); continue; }
    for (const c of l) L.push(`### ${c.title}`, `- id \`${c.id}\`, confidence ${c.confidence}, signal ${c.signal}`, `- evidence: ${c.evidence.join(", ")}`, `- why: ${c.rationale}`, `- proposed: ${c.proposedText}`, "");
  }
  return L.join("\n");
}
// Cyrus LEARNING LOOP step 3b: the ENGINE RELEASE MANIFEST (idea from GAPS-AND-IDEAS.md: "treat prompt + sheets + rules + scanner +
// image as one engine release, canary, auto-rollback on eval regression"). One record names every part of the engine that ships
// together, the eval baseline it was measured against, the learning candidates it contains and the release to roll back to.
//
// This is a PURE module: it builds, validates and compares manifests. It is NOT wired to a deploy, a router or a flag. Per-build
// records (lib/cyrus/engine-core/release.ts EngineRelease) say which engine made ONE build; this manifest says what a release IS,
// so a build's `engineRelease.id` can later be looked up in the list of manifests.
import { createHash } from "node:crypto";

export const MANIFEST_SCHEMA = 1 as const;
const SHA = /^[0-9a-f]{64}$/;

export type ManifestComponents = {
  /** Base prompt version and the section prompt versions (e.g. design). */
  prompts: { base: string; sections: Record<string, string> };
  /** Version sheets by file name with their sha256. */
  sheets: { name: string; sha256: string }[];
  rules: { version: string; sha256: string };
  scanner: { profile: string; sha256: string };
  /** Build-service image: tag always, digest when known. */
  image: { name: string; tag: string; digest?: string };
  jdk?: string;
  toolchain?: string;
};

export type EvalBaselineRef = {
  /** Where the accepted baseline lives (e.g. services/modbuilder/eval/baseline.json) and its hash at acceptance. */
  file: string;
  sha256: string;
  finalPassPct: number | null;
  builds: number;
  acceptedAt: string;
};

export type ReleaseStatus = "draft" | "canary" | "live" | "rolled-back" | "superseded";

export type ReleaseManifest = {
  schema: typeof MANIFEST_SCHEMA;
  /** er-<16 hex>: a hash of `components` only, so two manifests with the same parts have the same id. */
  id: string;
  createdAt: string;
  status: ReleaseStatus;
  components: ManifestComponents;
  evalBaseline: EvalBaselineRef | null;
  /** Learning candidates (lib/cyrus/learning/mining.ts ids) accepted into this release, for the audit trail. */
  candidates: string[];
  rollback: { toReleaseId: string | null; how: string } | null;
  notes: string;
};

export type ManifestInput = {
  components: ManifestComponents;
  evalBaseline?: EvalBaselineRef | null;
  candidates?: string[];
  rollbackTo?: string | null;
  rollbackHow?: string;
  status?: ReleaseStatus;
  notes?: string;
  now?: Date;
};

const sortObject = <T>(o: Record<string, T>): Record<string, T> => Object.fromEntries(Object.entries(o).sort(([a], [b]) => a.localeCompare(b)));

/** Canonical form: sheets sorted by name, section prompts sorted by key. The id and every comparison use it. */
export function canonicalComponents(c: ManifestComponents): ManifestComponents {
  return { ...c, prompts: { base: c.prompts.base, sections: sortObject(c.prompts.sections) }, sheets: [...c.sheets].sort((a, b) => a.name.localeCompare(b.name)) };
}

export function releaseId(c: ManifestComponents): string {
  return "er-" + createHash("sha256").update(JSON.stringify(canonicalComponents(c))).digest("hex").slice(0, 16);
}

export function createManifest(input: ManifestInput): ReleaseManifest {
  const components = canonicalComponents(input.components);
  const m: ReleaseManifest = {
    schema: MANIFEST_SCHEMA,
    id: releaseId(components),
    createdAt: (input.now ?? new Date()).toISOString(),
    status: input.status ?? "draft",
    components,
    evalBaseline: input.evalBaseline ?? null,
    candidates: [...new Set(input.candidates ?? [])].sort(),
    rollback: input.rollbackTo !== undefined || input.rollbackHow ? { toReleaseId: input.rollbackTo ?? null, how: input.rollbackHow ?? "" } : null,
    notes: input.notes ?? "",
  };
  return m;
}

/** Problems that make a manifest unfit to ship; empty = valid. A `live` / `canary` manifest needs an eval baseline and a rollback pointer. */
export function validateManifest(m: ReleaseManifest): string[] {
  const p: string[] = [];
  if (m.schema !== MANIFEST_SCHEMA) p.push(`schema must be ${MANIFEST_SCHEMA}`);
  if (m.id !== releaseId(m.components)) p.push("id does not match the components (edited by hand?)");
  const c = m.components;
  if (!c.prompts?.base) p.push("prompts.base is missing");
  if (!c.sheets?.length) p.push("no version sheets");
  for (const s of c.sheets ?? []) if (!SHA.test(s.sha256)) p.push(`sheet ${s.name}: sha256 is not 64 hex`);
  if (!c.rules?.version || !SHA.test(c.rules.sha256 ?? "")) p.push("rules need a version and a 64-hex sha256");
  if (!c.scanner?.profile || !SHA.test(c.scanner.sha256 ?? "")) p.push("scanner needs a profile and a 64-hex sha256");
  if (!c.image?.name || !c.image?.tag) p.push("image needs a name and a tag");
  if (c.image?.digest && !/^sha256:[0-9a-f]{64}$/.test(c.image.digest)) p.push("image.digest must be sha256:<64 hex>");
  if (m.evalBaseline && !SHA.test(m.evalBaseline.sha256)) p.push("evalBaseline.sha256 is not 64 hex");
  if (m.status === "live" || m.status === "canary") {
    if (!m.evalBaseline) p.push(`a ${m.status} release needs an eval baseline reference`);
    if (!m.rollback || !m.rollback.how) p.push(`a ${m.status} release needs a rollback pointer`);
    if (m.rollback && m.rollback.toReleaseId === m.id) p.push("rollback points at itself");
  }
  return p;
}

export type ManifestDiff = { changed: string[]; sheets: { added: string[]; removed: string[]; changed: string[] }; same: boolean };

/** Which parts differ between two releases (for the review page and the canary note). */
export function diffManifests(a: ReleaseManifest, b: ReleaseManifest): ManifestDiff {
  const ca = canonicalComponents(a.components), cb = canonicalComponents(b.components);
  const changed: string[] = [];
  if (ca.prompts.base !== cb.prompts.base) changed.push("prompts.base");
  for (const k of new Set([...Object.keys(ca.prompts.sections), ...Object.keys(cb.prompts.sections)])) if (ca.prompts.sections[k] !== cb.prompts.sections[k]) changed.push(`prompts.sections.${k}`);
  if (ca.rules.version !== cb.rules.version || ca.rules.sha256 !== cb.rules.sha256) changed.push("rules");
  if (ca.scanner.sha256 !== cb.scanner.sha256 || ca.scanner.profile !== cb.scanner.profile) changed.push("scanner");
  if (ca.image.tag !== cb.image.tag || ca.image.digest !== cb.image.digest || ca.image.name !== cb.image.name) changed.push("image");
  if (ca.jdk !== cb.jdk) changed.push("jdk");
  if (ca.toolchain !== cb.toolchain) changed.push("toolchain");
  const am = new Map(ca.sheets.map((s) => [s.name, s.sha256])), bm = new Map(cb.sheets.map((s) => [s.name, s.sha256]));
  const sheets = {
    added: [...bm.keys()].filter((k) => !am.has(k)),
    removed: [...am.keys()].filter((k) => !bm.has(k)),
    changed: [...bm.keys()].filter((k) => am.has(k) && am.get(k) !== bm.get(k)),
  };
  if (sheets.added.length || sheets.removed.length || sheets.changed.length) changed.push("sheets");
  return { changed, sheets, same: changed.length === 0 };
}

/** Eval gate: a release may only be promoted when its pass rate does not fall more than `tolerancePct` below the baseline it replaces. */
export function evalGate(previous: EvalBaselineRef | null, next: EvalBaselineRef | null, tolerancePct = 1): { ok: boolean; reason: string } {
  if (!next || next.finalPassPct == null) return { ok: false, reason: "the new release has no eval result" };
  if (!previous || previous.finalPassPct == null) return { ok: true, reason: "no previous baseline to compare with" };
  const drop = previous.finalPassPct - next.finalPassPct;
  return drop > tolerancePct ? { ok: false, reason: `pass rate fell ${drop.toFixed(1)} points (${previous.finalPassPct} to ${next.finalPassPct}), more than the ${tolerancePct} allowed` } : { ok: true, reason: `pass rate ${previous.finalPassPct} to ${next.finalPassPct}` };
}

/** Rollback target of a release, or null when it has none / points at an unknown release. */
export function rollbackTarget(m: ReleaseManifest, all: ReleaseManifest[]): ReleaseManifest | null {
  const id = m.rollback?.toReleaseId;
  return id ? all.find((x) => x.id === id) ?? null : null;
}

