function buildOne(id, dir, meta, v) {
  const cp = fs.readFileSync(path.join(CP_DIR, `${v}.txt`), "utf8").trim();
  const java = sourcesFor(dir, v).filter((f) => f.rel.endsWith(".java"));
  const ymlText = fs.readFileSync(path.join(dir, "plugin.yml"), "utf8");
  const res = { compile: "fail", scan: "not_run", errors: "", warnings: [], precheck: [], warningRules: [], findings: [], yml: [] };
  const val = validateYml(ymlText, java);
  res.yml = val.problems;
  res.commands = val.commands;
  res.pluginName = val.name;
  res.precheck = precheck(java, v);
  const work = fs.mkdtempSync(path.join(os.tmpdir(), `golden-${id}-`));
  try {
    const classes = path.join(work, "classes");
    fs.mkdirSync(classes, { recursive: true });
    const t0 = Date.now();
    const r = spawnSync(path.join(JDK, "bin/javac"), ["-J-Xmx768m", "--release", "21", "-encoding", "UTF-8", "-proc:none", "-Xmaxerrs", "40", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...java.map((f) => f.abs)], { encoding: "utf8", timeout: 180000 });
    res.javacMs = Date.now() - t0;
    const output = ((r.stderr || "") + (r.stdout || "")).split(dir + "/").join("");
    res.warnings = (output.match(/warning: \[(deprecation|removal)\][^\n]*/g) || []).slice(0, 20);
    res.warningRules = warningCheck(res.warnings, v);
    if (r.status !== 0) { res.errors = output.slice(0, 6000); return res; }
    res.compile = res.warnings.length || res.precheck.length || res.yml.length ? "warn" : "pass";
    res.findings = [...scanBytecode(classes), ...scanSource(java)];
    res.scan = res.findings.some((f) => f.severity === "block") ? "fail" : res.findings.length ? "warn" : "pass";
    // Resources: plugin.yml (api-version pinned to the exact version, as server.js does) + config.yml etc.
    fs.writeFileSync(path.join(classes, "plugin.yml"), ymlText.replace("@API@", v));
    for (const f of walk(path.join(dir, "resources"))) { fs.mkdirSync(path.dirname(path.join(classes, f.rel)), { recursive: true }); fs.copyFileSync(f.abs, path.join(classes, f.rel)); }
    const entries = walk(classes).map((f) => f.rel).sort();
    const jarOut = path.join(OUT, v, `${id}.jar`);
    fs.mkdirSync(path.dirname(jarOut), { recursive: true });
    const args = ["--create", "--file", jarOut, "--date", "2026-01-01T00:00:00Z"];
    for (const e of entries) args.push("-C", classes, e);
    execFileSync(path.join(JDK, "bin/jar"), args, { timeout: 60000 });
    res.jar = jarOut;
    res.jarSha256 = sha256(fs.readFileSync(jarOut));
  } finally {
    fs.rmSync(work, { recursive: true, force: true });
  }
  return res;
}

/**
 * --antipatterns: golden/antipatterns/<id>/ holds a mistake real plugins (and models) make, with expect.json
 * {expect: {layer: precheck|warning|compile|scan, rule}}. For every version the harness records which layer caught it
 * first (precheck rule ids, warning rule ids, javac error, scan rule ids). A mistake no layer catches is a finding.
 */
function antipatterns() {
  const base = path.join(__dirname, "antipatterns");
  const out = { schema: 1, versions: VERSIONS, rulesVersion: require(path.join(ROOT, "rules/failure-rules.json")).version, cases: {} };
  for (const id of fs.readdirSync(base).filter((d) => fs.existsSync(path.join(base, d, "expect.json"))).sort()) {
    if (ONLY && !ONLY.has(id)) continue;
    const dir = path.join(base, id);
    const exp = JSON.parse(fs.readFileSync(path.join(dir, "expect.json"), "utf8"));
    out.cases[id] = { expect: exp.expect, why: exp.why, versions: {} };
    for (const v of VERSIONS) {
      if (exp.versions && !exp.versions.includes(v)) continue;
      const r = buildOne(id, dir, exp, v);
      const caughtBy = [];
      if (r.precheck.length) caughtBy.push({ layer: "precheck", rules: [...new Set(r.precheck.map((x) => x.rule))] });
      if (r.compile === "fail") caughtBy.push({ layer: "compile", errors: (r.errors.match(/error: [^\n]*/g) || []).slice(0, 4) });
      if (r.warningRules.length) caughtBy.push({ layer: "warning", rules: r.warningRules.map((x) => x.rule) });
      if (r.findings.some((f) => f.severity === "block")) caughtBy.push({ layer: "scan", rules: [...new Set(r.findings.filter((f) => f.severity === "block").map((f) => f.rule))] });
      const hit = exp.expect.layer === "none" ? (caughtBy.length === 0 ? { layer: "none" } : null) : caughtBy.find((c) => c.layer === exp.expect.layer && (!c.rules || c.rules.includes(exp.expect.rule)));
      out.cases[id].versions[v] = { caught: caughtBy.length > 0, asExpected: !!hit, caughtBy, warnings: r.warnings };
      if (r.jar) fs.rmSync(r.jar, { force: true });
      process.stderr.write(`anti ${id} ${v}: ${caughtBy.map((c) => c.layer + (c.rules ? ":" + c.rules.join("+") : "")).join(", ") || "NOT CAUGHT"}${hit ? "" : "  <- expected " + exp.expect.layer + ":" + exp.expect.rule}\n`);
    }
  }
  fs.mkdirSync(OUT, { recursive: true });
  fs.writeFileSync(path.join(OUT, "antipatterns.json"), JSON.stringify(out, null, 1));
  process.stdout.write(JSON.stringify({ ok: true, out: path.join(OUT, "antipatterns.json") }) + "\n");
}

function main() {
  if (argv.includes("--antipatterns")) return antipatterns();
  const base = path.join(__dirname, "plugins");
  const ids = fs.readdirSync(base).filter((d) => fs.existsSync(path.join(base, d, "golden.json")) && (!ONLY || ONLY.has(d))).sort();
  const prev = ONLY && fs.existsSync(path.join(OUT, "compile.json")) ? JSON.parse(fs.readFileSync(path.join(OUT, "compile.json"), "utf8")) : null;
  const results = { schema: 1, versions: VERSIONS, jdk: JDK, cpDir: CP_DIR, rulesVersion: require(path.join(ROOT, "rules/failure-rules.json")).version, plugins: prev ? prev.plugins : {} };
  for (const id of ids) {
    const dir = path.join(base, id);
    const meta = JSON.parse(fs.readFileSync(path.join(dir, "golden.json"), "utf8"));
    results.plugins[id] = { archetype: meta.archetype, versions: {} };
    for (const v of VERSIONS) {
      if (meta.minVersion && !ge(v, meta.minVersion)) { results.plugins[id].versions[v] = { compile: "n/a", scan: "n/a", reason: `needs ${meta.minVersion}+` }; continue; }
      const r = buildOne(id, dir, meta, v);
      results.plugins[id].versions[v] = r;
      const bad = [r.errors && "COMPILE", r.warnings.length && `${r.warnings.length} warn`, r.precheck.length && `${r.precheck.length} precheck`, r.yml.length && "yml", r.findings.length && `scan ${r.scan}`].filter(Boolean);
      process.stderr.write(`${id} ${v}: ${r.compile}/${r.scan}${bad.length ? " " + bad.join(", ") : ""}\n`);
    }
  }
  fs.mkdirSync(OUT, { recursive: true });
  fs.writeFileSync(path.join(OUT, "compile.json"), JSON.stringify(results, null, 1));
  // One Test Flight spec per version: every golden jar that compiled cleanly, with its RCON checks.
  const all = Object.keys(results.plugins).filter((d) => fs.existsSync(path.join(base, d, "golden.json"))).sort();
  for (const v of VERSIONS) {
    const plugins = [], rcon = [];
    for (const id of all) {
      const r = results.plugins[id].versions[v];
      if (!r || !r.jar || r.scan === "fail") continue;
      plugins.push({ remotePath: r.jar, sha256: r.jarSha256 });
      const meta = JSON.parse(fs.readFileSync(path.join(base, id, "golden.json"), "utf8"));
      for (const [i, c] of (meta.rcon || []).entries()) rcon.push({ id: `${id}#${i}`, command: c.command, expect: c.expect || [], expectNot: [...(c.expectNot || []), "An internal error occurred", "Unknown or incomplete command", "Exception"] });
    }
    if (plugins.length) fs.writeFileSync(path.join(OUT, v, "flight-spec.json"), JSON.stringify({ version: v, plugins, rcon }, null, 1));
  }
  process.stdout.write(JSON.stringify({ ok: true, out: path.join(OUT, "compile.json"), plugins: ids.length }) + "\n");
}

