const opt = (n: string, d: string) => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] ? argv[i + 1] : d; };
const OUT = opt("out", path.join(ROOT, ".cyrus-local", "golden"));
const ssh = (cmd: string) => execFileSync("ssh", ["-o", "BatchMode=yes", "-o", "ConnectTimeout=15", NODE2, cmd], { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });

type PluginVerdict = { plugin: string; enabled: boolean | null; rcon: { id: string; ok: boolean; text: string }[]; logHits: string[] };

/** Split one shared flight into per-plugin verdicts from the runner's evidence lines. */
export function perPlugin(report: TestFlightReport, names: Record<string, string>): Record<string, PluginVerdict> {
  const out: Record<string, PluginVerdict> = {};
  for (const [id, name] of Object.entries(names)) out[id] = { plugin: name, enabled: null, rcon: [], logHits: [] };
  const ev = (cid: string) => report.checks.find((c) => c.id === cid)?.evidence ?? [];
  for (const line of ev("plugins_enabled")) {
    const m = line.match(/^([A-Za-z0-9_.-]+): (enabled|NOT enabled)/);
    if (!m) continue;
    for (const v of Object.values(out)) if (v.plugin === m[1]) v.enabled = m[2] === "enabled";
  }
  for (const line of ev("rcon_checks")) {
    const m = line.match(/^([a-z0-9-]+)#(\d+) '.*?'.*?: (ok|FAILED)(.*)$/);
    if (m && out[m[1]]) out[m[1]].rcon.push({ id: `${m[1]}#${m[2]}`, ok: m[3] === "ok", text: m[4].replace(/^.*?-> /, "").slice(0, 200) });
  }
  for (const line of ev("startup_log_clean")) for (const v of Object.values(out)) if (line.includes(v.plugin)) v.logHits.push(line.slice(0, 240));
  return out;
}

async function fly(version: string) {
  const spec = JSON.parse(ssh(`cat ${REMOTE_OUT}/${version}/flight-spec.json`)) as { version: string; plugins: { remotePath: string; sha256: string }[]; rcon: TestFlightSpec["rcon"] };
  const compile = JSON.parse(ssh(`cat ${REMOTE_OUT}/compile.json`));
  const names: Record<string, string> = {};
  for (const [id, p] of Object.entries(compile.plugins as Record<string, { versions: Record<string, { pluginName?: string; jar?: string }> }>)) {
    const r = p.versions[version];
    if (r?.jar && spec.plugins.some((x) => x.remotePath === r.jar)) names[id] = r.pluginName!;
  }
  const tf: TestFlightSpec = {
    version, plugins: spec.plugins.map((p) => ({ remotePath: p.remotePath, sha256: p.sha256 })), rcon: spec.rcon,
    timeouts: { bootSec: 300, rconSec: 30, stopSec: 90, totalSec: 900 }, memory: { xmxMb: 1024, rssCapMb: 2048 },
  };
  console.log(`flying ${version}: ${tf.plugins!.length} plugins, ${tf.rcon!.length} RCON checks`);
  const t0 = Date.now();
  const { report, summary } = await flyWhenFree(tf);
  const verdicts = perPlugin(report, names);
  mkdirSync(OUT, { recursive: true });
  writeFileSync(path.join(OUT, `flight-${version}.json`), JSON.stringify({ version, wallMs: Date.now() - t0, summary, verdicts, report }, null, 1));
  console.log(`${version}: ${summary.overall} (boot ${summary.bootMs} ms, peak ${Math.round((summary.peakRssKb ?? 0) / 1024)} MB) failed=${summary.failed.join(",") || "-"}`);
  for (const [id, v] of Object.entries(verdicts)) {
    const bad = v.enabled === false || v.rcon.some((r) => !r.ok) || v.logHits.length;
    if (bad) console.log(`  ${id}: enabled=${v.enabled} ${v.rcon.filter((r) => !r.ok).map((r) => `${r.id} ${r.text}`).join(" | ")} ${v.logHits.join(" | ")}`);
  }
}

