package dev.nxeon.golden.homes;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Location;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden homes: /sethome [name], /home [name], /delhome name, /homes; limit per permission; saved in homes.yml. */
public class Homes extends JavaPlugin implements TabCompleter {
    private File file;
    private YamlConfiguration data;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "homes.yml");
        data = YamlConfiguration.loadConfiguration(file);
        for (String c : List.of("sethome", "home", "delhome", "homes")) {
            getCommand(c).setExecutor(this);
            getCommand(c).setTabCompleter(this);
        }
    }

    @Override
    public void onDisable() {
        save();
    }

    private void save() {
        try {
            data.save(file);
        } catch (IOException e) {
            getLogger().warning("Could not save homes.yml: " + e.getMessage());
        }
    }

    private int limitFor(Player p) {
        int limit = getConfig().getInt("default-limit", 3);
        ConfigurationSection extra = getConfig().getConfigurationSection("limits");
        if (extra != null) for (String key : extra.getKeys(false)) if (p.hasPermission("goldenhomes.limit." + key)) limit = Math.max(limit, extra.getInt(key));
        return limit;
    }

    private ConfigurationSection homesOf(Player p, boolean create) {
        String path = p.getUniqueId().toString();
        ConfigurationSection s = data.getConfigurationSection(path);
        return s == null && create ? data.createSection(path) : s;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String cmd = command.getName().toLowerCase();
        if (cmd.equals("homes") && args.length == 1 && args[0].equalsIgnoreCase("reload")) {
            if (!sender.hasPermission("goldenhomes.admin")) { sender.sendMessage(Component.text("No permission.", NamedTextColor.RED)); return true; }
            reloadConfig();
            sender.sendMessage(Component.text("GoldenHomes reloaded (default limit " + getConfig().getInt("default-limit", 3) + ").", NamedTextColor.GREEN));
            return true;
        }
        if (!(sender instanceof Player player)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
        String name = args.length > 0 ? args[0].toLowerCase() : "home";
        if (!name.matches("[a-z0-9_]{1,16}")) { player.sendMessage(Component.text("Home names: 1-16 letters, digits or _.", NamedTextColor.RED)); return true; }
        ConfigurationSection homes = homesOf(player, cmd.equals("sethome"));
        switch (cmd) {
            case "sethome" -> {
                if (!homes.contains(name) && homes.getKeys(false).size() >= limitFor(player)) { player.sendMessage(Component.text("You reached your home limit (" + limitFor(player) + ").", NamedTextColor.RED)); return true; }
                homes.set(name, player.getLocation());
                save();
                player.sendMessage(Component.text("Home '" + name + "' set.", NamedTextColor.GREEN));
            }
            case "home" -> {
                Location loc = homes == null ? null : homes.getLocation(name);
                if (loc == null || loc.getWorld() == null) { player.sendMessage(Component.text("No home called '" + name + "'.", NamedTextColor.RED)); return true; }
                player.teleportAsync(loc).thenAccept(ok -> { if (ok) player.sendMessage(Component.text("Welcome home.", NamedTextColor.GREEN)); });
            }
            case "delhome" -> {
                if (homes == null || !homes.contains(name)) { player.sendMessage(Component.text("No home called '" + name + "'.", NamedTextColor.RED)); return true; }
                homes.set(name, null);
                save();
                player.sendMessage(Component.text("Home '" + name + "' deleted.", NamedTextColor.YELLOW));
            }
            default -> player.sendMessage(Component.text("Homes: " + (homes == null ? "none" : String.join(", ", homes.getKeys(false))), NamedTextColor.AQUA));
        }
        return true;
    }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command command, String alias, String[] args) {
        if (!(sender instanceof Player p) || args.length != 1) return List.of();
        ConfigurationSection homes = homesOf(p, false);
        return homes == null ? List.of() : new ArrayList<>(homes.getKeys(false));
    }
}
package dev.nxeon.golden.afk;

import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerMoveEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden AFK: marks players AFK after N minutes without changing block, optional kick; /afk toggles. */
public class Afk extends JavaPlugin implements Listener {
    private final Map<UUID, Long> lastActive = new ConcurrentHashMap<>();
    private final Map<UUID, Boolean> afk = new ConcurrentHashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("afk").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        getServer().getScheduler().runTaskTimer(this, this::tick, 200L, 200L);
    }

    private void tick() {
        long now = System.currentTimeMillis();
        long afterMs = getConfig().getLong("afk-after-minutes", 5) * 60000, kickMs = getConfig().getLong("kick-after-minutes", 0) * 60000;
        for (Player p : getServer().getOnlinePlayers()) {
            long idle = now - lastActive.computeIfAbsent(p.getUniqueId(), k -> now);
            if (idle >= afterMs && afk.putIfAbsent(p.getUniqueId(), true) == null) getServer().broadcast(Component.text(p.getName() + " is now AFK.", NamedTextColor.GRAY));
            if (kickMs > 0 && idle >= kickMs && !p.hasPermission("goldenafk.exempt")) p.kick(Component.text("Kicked for being AFK."));
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onMove(PlayerMoveEvent e) {
        if (!e.hasChangedBlock()) return; // head turns alone do not count as activity
        lastActive.put(e.getPlayer().getUniqueId(), System.currentTimeMillis());
        if (afk.remove(e.getPlayer().getUniqueId()) != null) getServer().broadcast(Component.text(e.getPlayer().getName() + " is back.", NamedTextColor.GRAY));
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) { lastActive.remove(e.getPlayer().getUniqueId()); afk.remove(e.getPlayer().getUniqueId()); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("GoldenAfk: " + afk.size() + " AFK, after " + getConfig().getLong("afk-after-minutes", 5) + " min.", NamedTextColor.GRAY)); return true; }
        if (afk.remove(p.getUniqueId()) == null) { afk.put(p.getUniqueId(), true); getServer().broadcast(Component.text(p.getName() + " is now AFK.", NamedTextColor.GRAY)); }
        else lastActive.put(p.getUniqueId(), System.currentTimeMillis());
        return true;
    }
}
package dev.nxeon.golden.utility;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.NamespacedKey;
import org.bukkit.Registry;
import org.bukkit.attribute.Attribute;
import org.bukkit.attribute.AttributeInstance;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden utility commands: /heal [player], /feed [player], /flytoggle [player]; console can target players. */
public class Utility extends JavaPlugin {
    @Override
    public void onEnable() {
        saveDefaultConfig();
        for (String c : new String[] {"heal", "feed", "flytoggle"}) getCommand(c).setExecutor(this);
    }

    static Attribute maxHealth() {
        Attribute a = Registry.ATTRIBUTE.get(NamespacedKey.minecraft("max_health"));
        return a != null ? a : Registry.ATTRIBUTE.get(NamespacedKey.minecraft("generic.max_health"));
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        Player target;
        if (args.length >= 1) {
            if (!sender.hasPermission("goldenutility.others")) { sender.sendMessage(Component.text("You may only use this on yourself.", NamedTextColor.RED)); return true; }
            target = Bukkit.getPlayerExact(args[0]);
            if (target == null) { sender.sendMessage(Component.text("Player " + args[0] + " is not online.", NamedTextColor.RED)); return true; }
        } else if (sender instanceof Player p) {
            target = p;
        } else {
            sender.sendMessage(Component.text("Usage from the console: /" + label + " <player>", NamedTextColor.RED));
            return true;
        }
        switch (command.getName().toLowerCase()) {
            case "heal" -> {
                AttributeInstance max = target.getAttribute(maxHealth());
                target.setHealth(max != null ? max.getValue() : 20.0);
                target.setFireTicks(0);
                if (getConfig().getBoolean("heal-clears-effects", true)) target.getActivePotionEffects().forEach(e -> target.removePotionEffect(e.getType()));
                target.sendMessage(Component.text("You were healed.", NamedTextColor.GREEN));
            }
            case "feed" -> {
                target.setFoodLevel(20);
                target.setSaturation((float) getConfig().getDouble("feed-saturation", 10.0));
                target.sendMessage(Component.text("You were fed.", NamedTextColor.GREEN));
            }
            default -> {
                boolean on = !target.getAllowFlight();
                target.setAllowFlight(on);
                if (!on) target.setFlying(false);
                target.sendMessage(Component.text("Flight " + (on ? "enabled" : "disabled") + ".", NamedTextColor.AQUA));
            }
        }
        if (target != sender) sender.sendMessage(Component.text("Done for " + target.getName() + ".", NamedTextColor.GRAY));
        return true;
    }
}
