// Cyrus LEARNING LOOP (2026-10-12): shared types. Pure + client-safe (no imports, no I/O).
//
// Cyrus cannot fine-tune Claude. "Learning" here means: mine real build OUTCOMES into reviewed rules, prompt / sheet changes,
// golden tests and routing, shipped as gated engine releases. Nothing in lib/cyrus/learning ever writes a rule, sheet or
// prompt: it only derives signals and proposes candidates for a human to review.
//
// Privacy (owner decision D-60): the EXPORTED outcome record (./export.ts) is ANONYMIZED - what kind of request, which lane, model,
// result and fixes - and never carries user ids, mod code, imported / third-party mods, file contents, request text or names. The
// in-memory BuildSignals additionally hold the removed class / command / config-key NAMES of a regression (the mining job needs
// them); they are staff-local and never leave through the export. A row's `prompt` / `changeRequest` are read only to compare for
// equality and length; only the length bucket is kept.

/** The fields of a ModBuild row the learning loop reads. Dates may be Date, ISO string or epoch ms. */
export type BuildRow = {
  id: string;
  userId?: string | null;
  status: string;
  prompt?: string | null;
  changeRequest?: string | null;
  baseBuildId?: string | null;
  rootBuildId?: string | null;
  mcVersion?: string | null;
  pluginName?: string | null;
  version?: string | null;
  /** ModBuild.result (shape: lib/modbuilder/types.ts ModBuildResult). */
  result?: unknown;
  error?: string | null;
  errorCode?: string | null;
  attempts?: number | null;
  costUsd?: number | null;
  durationMs?: number | null;
  lastInstall?: unknown;
  /** ModBuild.cyrus (shape: lib/cyrus/meta.ts CyrusMeta). */
  cyrus?: unknown;
  createdAt: Date | string | number;
  finishedAt?: Date | string | number | null;
};

export type ModelFamily = "haiku" | "sonnet" | "opus" | "other";
export type Outcome = "success" | "refused" | "interrupted" | "unavailable" | "failed";

/** What a build exposes to its players, derived from the stored result (or a jar listing when supplied). */
export type Surface = {
  /** Fully qualified class names (from src/main/java paths, or the jar). */
  classes: string[];
  /** "/label" for each command and "/label sub" for each sub-command word found in the usage text. */
  commands: string[];
  /** Dotted config keys. */
  configKeys: string[];
  /** Where it came from: the stored result summary (config keys are then only the keys the model listed) or a jar listing. */
  source: "result" | "jar";
};

export type Regression = {
  baseId: string;
  severity: "none" | "minor" | "major";
  removedClasses: string[];
  removedCommands: string[];
  removedConfigKeys: string[];
  baseCounts: { classes: number; commands: number; configKeys: number };
  /** Config keys read from the result summary can be incomplete: they alone never make a regression "major". */
  configKeysTrusted: boolean;
};

export type CallKind = "guard" | "generate" | "change" | "repair" | "repair-asset" | "other";

export type CallSummary = { n: number; turns: number; costUsd: number; durationMs: number };

export type BuildSignals = {
  id: string;
  rootId: string;
  baseId: string | null;
  createdAtMs: number;
  endedAtMs: number;
  kind: "fresh" | "change";
  status: string;
  outcome: Outcome;
  tier: string | null;
  family: ModelFamily | null;
  route: string | null;
  routeMethod: string | null;
  lanes: string[];
  laneKey: string;
  promptBucket: "short" | "medium" | "long" | "none";
  mcVersion: string | null;
  attempts: number;
  repairs: number;
  costUsd: number;
  durationMs: number;
  /** Sum of the CLI's num_turns over the non-guard calls. It tracks tool round trips (reads + writes + edits + ~2), not API requests. */
  turns: number;
  /** costUsd / 0.002 (D-03: one Cyrus token = $0.002 of real cost). An estimate; ModBuild stores no token counts today. */
  tokensEst: number;
  callsByKind: Partial<Record<CallKind, CallSummary>>;
  /** "<family>/<kind>" -> summary, by the model each CALL used (a guard call is Haiku whatever the build's tier). */
  callsByFamilyKind: Record<string, CallSummary>;
  /** Present only when the portal persisted usage (CYRUS_LEARNING on at sync time). */
  usage: { input: number; cacheWrite: number; cacheRead: number; output: number; toolCalls: number } | null;
  /** Counts and per-stage wall time from the stored event list (the portal keeps the last 150 events). */
  events: { reads: number; writes: number; edits: number; /** edit/write events that arrive >= 2 s after the previous event: a request of their own */ seqWrites: number; autofixes: number; apiLookups: number; stageMs: Record<string, number> };
  guardRefusal: boolean;
  guardReason: string | null;
  interrupted: boolean;
  unavailable: boolean;
  testFlight: { ran: boolean; failed: boolean; failedChecks: string[]; stress: string | null };
  install: { installed: boolean; failed: boolean; replaced: number };
  rework: { reworked: boolean; byId: string | null; gapMin: number | null; via: "base" | "sibling" | null; wastedUsd: number };
  retry: { retried: boolean; byId: string | null; gapMin: number | null };
  regression: Regression | null;
  /** Compared with the nearest earlier build of the lineage that was good (not reworked, not major-regressed). */
  goodBaseId: string | null;
  regressionVsGood: Regression | null;
  /** Succeeded, not reworked, not a major regression (vs base or vs the last good build). */
  kept: boolean;
};

export type LearningOptions = {
  /** Rework window (minutes). Default 30. */
  reworkMinutes?: number;
  /** Surfaces taken from jars (build id -> surface); overrides the surface derived from the result. */
  surfaces?: Record<string, Surface>;
};
