import type { BuildSignals, Regression } from "./types";

export type RegressionCounts = { baseId: string; severity: Regression["severity"]; removed: { classes: number; commands: number; configKeys: number }; baseCounts: Regression["baseCounts"]; configKeysTrusted: boolean };
export type ExportRecord = Omit<BuildSignals, "regression" | "regressionVsGood"> & { regression: RegressionCounts | null; regressionVsGood: RegressionCounts | null };

const counts = (r: Regression | null): RegressionCounts | null => r && {
  baseId: r.baseId, severity: r.severity, baseCounts: r.baseCounts, configKeysTrusted: r.configKeysTrusted,
  removed: { classes: r.removedClasses.length, commands: r.removedCommands.length, configKeys: r.removedConfigKeys.length },
};

export function toExportRecord(s: BuildSignals): ExportRecord {
  return { ...s, regression: counts(s.regression), regressionVsGood: counts(s.regressionVsGood) };
