package dev.nxeon.golden.weapon;


/**
 * Golden custom weapon "Storm Blade": identified by a PDC key (never by name); on hit it may strike lightning
 * (effect only, no fire, no self damage); pressing the swap-hands key (F) while holding it dashes forward with a
 * per-player cooldown. The swap is cancelled so the item stays in the main hand.
 */
public class Weapon extends JavaPlugin implements Listener {
    private NamespacedKey key;
    private final Map<UUID, Long> cooldown = new ConcurrentHashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        key = new NamespacedKey(this, "storm_blade");
        getCommand("stormblade").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    ItemStack create() {
        ItemStack it = new ItemStack(Material.DIAMOND_SWORD);
        it.editMeta(m -> {
            m.displayName(Component.text("Storm Blade", NamedTextColor.AQUA).decoration(TextDecoration.ITALIC, false));
            m.lore(List.of(Component.text("Press F to dash", NamedTextColor.GRAY).decoration(TextDecoration.ITALIC, false)));
            m.getPersistentDataContainer().set(key, PersistentDataType.BOOLEAN, true);
            m.setEnchantmentGlintOverride(true);
        });
        return it;
    }

    boolean isBlade(ItemStack it) { return it != null && it.hasItemMeta() && it.getItemMeta().getPersistentDataContainer().has(key, PersistentDataType.BOOLEAN); }

    @EventHandler(ignoreCancelled = true)
    public void onHit(EntityDamageByEntityEvent e) {
        if (!(e.getDamager() instanceof Player p) || !(e.getEntity() instanceof LivingEntity target) || !isBlade(p.getInventory().getItemInMainHand())) return;
        if (Math.random() < getConfig().getDouble("lightning-chance", 0.25)) {
            target.getWorld().strikeLightningEffect(target.getLocation());
            e.setDamage(e.getDamage() + getConfig().getDouble("lightning-bonus-damage", 4));
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onSwap(PlayerSwapHandItemsEvent e) {
        Player p = e.getPlayer();
        if (!isBlade(p.getInventory().getItemInMainHand())) return;
        e.setCancelled(true);
        long now = System.currentTimeMillis(), ready = cooldown.getOrDefault(p.getUniqueId(), 0L);
        if (now < ready) { p.sendActionBar(Component.text("Dash ready in " + ((ready - now) / 1000 + 1) + " s", NamedTextColor.RED)); return; }
        cooldown.put(p.getUniqueId(), now + getConfig().getLong("dash-cooldown-seconds", 5) * 1000);
        Vector v = p.getLocation().getDirection().setY(0).normalize().multiply(getConfig().getDouble("dash-strength", 1.4)).setY(0.3);
        p.setVelocity(v);
        p.getWorld().spawnParticle(Particle.CLOUD, p.getLocation(), 12, 0.3, 0.1, 0.3, 0.02);
        p.playSound(p.getLocation(), Sound.ENTITY_BREEZE_WIND_BURST, 1f, 1.2f);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        Player target = args.length == 1 ? Bukkit.getPlayerExact(args[0]) : sender instanceof Player p ? p : null;
        if (target == null) { sender.sendMessage(Component.text("Storm Blade ready: " + isBlade(create()) + ". Usage: /stormblade <player>", NamedTextColor.YELLOW)); return true; }
        target.getInventory().addItem(create());
        sender.sendMessage(Component.text("Gave a Storm Blade to " + target.getName() + ".", NamedTextColor.GREEN));
        return true;
    }
}
package dev.nxeon.golden.chatformat;


/** Golden chat format: MiniMessage format from config, per-permission prefix, @mention highlight + sound. Async-safe. */
public class ChatFormat extends JavaPlugin implements Listener {
    private volatile String format;
    private volatile String prefixVip;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        load();
        getServer().getPluginManager().registerEvents(this, this);
        getCommand("chatformat").setExecutor(this);
    }

    private void load() {
        format = getConfig().getString("format", "<gray><prefix><name></gray> <dark_gray>»</dark_gray> <message>");
        prefixVip = getConfig().getString("prefix.vip", "<gold>[VIP] </gold>");
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onChat(AsyncChatEvent event) {
        // Runs off the main thread: only read the volatile config strings and the event's own data here.
        final String fmt = format;
        final String prefix = event.getPlayer().hasPermission("goldenchat.vip") ? prefixVip : "";
        final String plain = PlainTextComponentSerializer.plainText().serialize(event.message());
        event.renderer(ChatRenderer.viewerUnaware((source, displayName, message) -> MiniMessage.miniMessage().deserialize(fmt,
            Placeholder.parsed("prefix", prefix), Placeholder.component("name", displayName), Placeholder.component("message", message))));
        for (Player p : getServer().getOnlinePlayers()) {
            if (p != event.getPlayer() && plain.toLowerCase().contains("@" + p.getName().toLowerCase())) {
                getServer().getScheduler().runTask(this, () -> p.playSound(p.getLocation(), org.bukkit.Sound.BLOCK_NOTE_BLOCK_PLING, 1f, 1.6f));
            }
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 1 && args[0].equalsIgnoreCase("reload")) {
            reloadConfig();
            load();
            sender.sendMessage(Component.text("GoldenChatFormat reloaded.", NamedTextColor.GREEN));
            return true;
        }
        sender.sendMessage(MiniMessage.miniMessage().deserialize(format, Placeholder.parsed("prefix", prefixVip), Placeholder.unparsed("name", "Steve"), Placeholder.unparsed("message", "preview")));
        return true;
    }
}
