/** Golden rules book: /rulesbook opens it (Adventure Book, no item needed); first join gets a written copy (BookMeta). */
public class Books extends JavaPlugin implements Listener {
    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("rulesbook").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    List<Component> pages() { return getConfig().getStringList("pages").stream().map(MiniMessage.miniMessage()::deserialize).toList(); }

