        ItemStack it = new ItemStack(Material.WRITTEN_BOOK);
        it.editMeta(BookMeta.class, m -> {
            m.title(Component.text(getConfig().getString("title", "Rules")));
            m.author(Component.text(getConfig().getString("author", "Staff")));
            m.pages(pages());
        });
        return it;
    }

