package dev.nxeon.starter.healfeed;

import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.NamespacedKey;
import org.bukkit.Registry;
import org.bukkit.attribute.Attribute;
import org.bukkit.attribute.AttributeInstance;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;

/** Cyrus starter bank: /heal and /feed with a per-player cooldown (action bar); operators target other players. */
public class HealFeed extends JavaPlugin {
    private final Map<String, Long> readyAt = new ConcurrentHashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("heal").setExecutor(this);
        getCommand("feed").setExecutor(this);
    }

    static Attribute maxHealth() {
        Attribute a = Registry.ATTRIBUTE.get(NamespacedKey.minecraft("max_health"));
        return a != null ? a : Registry.ATTRIBUTE.get(NamespacedKey.minecraft("generic.max_health"));
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        boolean heal = command.getName().equalsIgnoreCase("heal");
        Player target;
        if (args.length >= 1) {
            if (!sender.hasPermission("cyrushealfeed.others")) { sender.sendMessage(Component.text("You may only use this on yourself.", NamedTextColor.RED)); return true; }
            target = Bukkit.getPlayerExact(args[0]);
            if (target == null) { sender.sendMessage(Component.text(args[0] + " is not online.", NamedTextColor.RED)); return true; }
        } else if (sender instanceof Player p) {
            target = p;
        } else {
            sender.sendMessage(Component.text("Usage from the console: /" + label + " <player>", NamedTextColor.RED));
            return true;
        }
        boolean self = target == sender;
        long cooldownMs = Math.max(0, heal ? getConfig().getInt("heal-cooldown-seconds", 60) : getConfig().getInt("feed-cooldown-seconds", 60)) * 1000L;
        String key = (heal ? "heal:" : "feed:") + target.getUniqueId();
        long now = System.currentTimeMillis();
        if (self && cooldownMs > 0) {
            long ready = readyAt.getOrDefault(key, 0L);
            if (now < ready) {
                target.sendActionBar(Component.text((heal ? "Heal" : "Feed") + " ready in " + ((ready - now + 999) / 1000) + " s", NamedTextColor.RED));
                return true;
            }
            readyAt.put(key, now + cooldownMs);
        }
        if (heal) {
            AttributeInstance max = target.getAttribute(maxHealth());
            target.setHealth(max != null ? max.getValue() : 20.0);
            target.setFireTicks(0);
        } else {
            target.setFoodLevel(20);
            target.setSaturation(20f);
        }
        String done = heal ? "You were healed." : "You were fed.";
        target.sendActionBar(Component.text(self && cooldownMs > 0 ? done + " Next one in " + cooldownMs / 1000 + " s." : done, NamedTextColor.GREEN));
        if (!self) sender.sendMessage(Component.text((heal ? "Healed " : "Fed ") + target.getName() + ".", NamedTextColor.GRAY));
        return true;
    }

    /** Cooldowns of players who left are dropped so the map stays bounded by the online players. */
    @Override
    public void onDisable() { readyAt.clear(); }

    UUID unused() { return null; }
}
EOF
