import org.bukkit.plugin.java.JavaPlugin;

/** Cyrus starter bank: join / leave messages, a different message and a big title for first-time players. */
public class Welcome extends JavaPlugin implements Listener {
    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("joinmsg").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private Component render(String path, String def, Player p, int online) {
        String raw = getConfig().getString(path, def);
        // the name is escaped so a player name can never inject formatting
        return MiniMessage.miniMessage().deserialize(raw.replace("{player}", MiniMessage.miniMessage().escapeTags(p.getName())).replace("{online}", String.valueOf(online)));
    }

    @EventHandler
    public void onJoin(PlayerJoinEvent e) {
        Player p = e.getPlayer();
        int online = getServer().getOnlinePlayers().size();
        if (!p.hasPlayedBefore()) {
            e.joinMessage(render("messages.first-join", "<gold>Welcome {player}!", p, online));
            int secs = Math.max(1, getConfig().getInt("title.seconds", 4));
            p.showTitle(Title.title(render("title.text", "<gold>Welcome!", p, online), render("title.subtitle", "", p, online),
                Title.Times.times(Duration.ofMillis(500), Duration.ofSeconds(secs), Duration.ofMillis(800))));
        } else {
            e.joinMessage(render("messages.join", "<gray>{player} joined", p, online));
        }
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) {
        e.quitMessage(render("messages.leave", "<gray>{player} left", e.getPlayer(), Math.max(0, getServer().getOnlinePlayers().size() - 1)));
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 1 && args[0].equalsIgnoreCase("reload")) {
            reloadConfig();
            sender.sendMessage(Component.text("CyrusWelcome reloaded.", NamedTextColor.GREEN));
            return true;
        }
        sender.sendMessage(Component.text("Usage: /joinmsg reload", NamedTextColor.YELLOW));
        return true;
    }
}
EOF
echo ok

content.content:
// Cyrus Config Studio: the BUILD CHECK that declared tunables are real. Static and cheap (no compile needed):
//   unread      a declared key the generated code never reads (an error: a setting that does nothing)
//   undeclared  a key the code reads (getX("...")) that the schema does not declare (a warning; the editor infers it)
//   magic       a numeric literal passed straight to a stat-setting API (a warning with file:line: should be a setting)
// A key counts as READ when its exact string appears in a config getter, or (iterated sections such as
// `getConfigurationSection("mobs")` + `getDouble("health")`) its last segment is read and one of its ancestor sections
// is opened; the generated settings class (./exporters.ts) reads every key by construction. Pure.
import type { ConfigSpec } from "./spec";

export type JavaFile = { rel: string; content: string };
export type VerifyReport = { ok: boolean; unread: string[]; undeclared: string[]; magic: { where: string; evidence: string }[]; read: string[]; accessor: boolean };

const GETTER = /\b(?:get(?:Int|Double|Long|String|Boolean|List|StringList|IntegerList|DoubleList|LongList|BooleanList|MapList|ConfigurationSection|Object|Color|Location|ItemStack|Vector)?|is(?:Set|Int|Double|Long|String|Boolean|List|ConfigurationSection)|contains)\s*\(\s*"([A-Za-z0-9_.-]{1,160})"/g;
const SECTION = /\bgetConfigurationSection\s*\(\s*"([A-Za-z0-9_.-]{1,160})"/g;
const STAT_CALL = /\.(setBaseValue|setDamage|setMaxHealth|setHealth|setCooldown|setFireTicks|setPickupDelay|setMaximumNoDamageTicks|setNoDamageTicks|addPotionEffect|runTaskTimer|runTaskLater|setVelocity|multiply|setExp|setLevel|setAmount)\s*\(([^;]*)\)/;
const NUM = /(?<![\w.])(-?\d+(?:\.\d+)?)[dDfFlL]?(?![\w.])/g;
/** Numbers too generic to flag (identity, booleans-as-int, one second in ticks). */
const BORING = new Set(["0", "1", "-1", "0.0", "1.0", "2", "20"]);

export function verifyTunables(spec: Pick<ConfigSpec, "params">, files: readonly JavaFile[], opts: { accessorClass?: string } = {}): VerifyReport {
  const literal = new Set<string>();
  const sections = new Set<string>();
  const magic: VerifyReport["magic"] = [];
  let accessor = false;
  for (const f of files) {
    const src = f.content.replace(/\/\*[\s\S]*?\*\//g, (m) => m.replace(/[^\n]/g, " ")).replace(/\/\/[^\n]*/g, "");
    if (opts.accessorClass && new RegExp(`\\bclass\\s+${opts.accessorClass}\\b`).test(src) && /Generated by Cyrus from the ConfigSpec/.test(f.content)) { accessor = true; continue; }
    for (const m of src.matchAll(GETTER)) literal.add(m[1]);
    for (const m of src.matchAll(SECTION)) sections.add(m[1]);
    src.split("\n").forEach((line, i) => {
      const m = STAT_CALL.exec(line);
      if (!m) return;
      const nums = [...m[2].matchAll(NUM)].map((x) => x[1]).filter((n) => !BORING.has(n));
      if (nums.length && magic.length < 50) magic.push({ where: `${f.rel}:${i + 1}`, evidence: line.trim().slice(0, 160) });
    });
  }
  const keys = spec.params.map((p) => p.key);
  const isRead = (k: string) => {
    if (accessor || literal.has(k)) return true;
    const segs = k.split(".");
    for (let n = 1; n < segs.length; n++) {
      const tail = segs.slice(n).join(".");
      if (!literal.has(tail)) continue;
      // an ancestor section is opened (exactly, or a section whose children are iterated: "mobs" for "mobs.x.health")
      for (let a = 1; a <= n; a++) if (sections.has(segs.slice(0, a).join("."))) return true;
    }
    return false;
  };
  const read = keys.filter(isRead);
  const unread = keys.filter((k) => !read.includes(k));
  const declared = new Set(keys);
  const prefixes = new Set(keys.flatMap((k) => k.split(".").map((_, i, a) => a.slice(0, i + 1).join("."))));
  const tails = new Set(keys.flatMap((k) => k.split(".").map((_, i, a) => a.slice(i).join("."))));
  const undeclared = [...literal].filter((k) => !declared.has(k) && !prefixes.has(k) && !tails.has(k)).sort();
  return { ok: unread.length === 0, unread, undeclared, magic, read, accessor };
}

