 "howToUse": ["Kill zombies, skeletons and creepers as usual.", "Operators: /drops to see the list, /drops reload after editing config.yml."],
 "limitations": ["Add another mob by copying a block under drops: in config.yml (the key is the mob's id, e.g. spider)."],
 "commands": [ { "usage": "/drops [reload]", "description": "Show or reload the custom drops", "permission": "cyrusdrops.admin", "whoCanUse": "operators" } ],
