cat > src/dev/nxeon/starter/drops/Drops.java <<'EOF'
package dev.nxeon.starter.drops;

import java.util.Locale;
import java.util.concurrent.ThreadLocalRandom;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Material;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

/** Cyrus starter bank: configurable extra drops per mob type (item, chance %, amount). */
public class Drops extends JavaPlugin implements Listener {
    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("drops").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    @EventHandler(ignoreCancelled = true)
    public void onDeath(EntityDeathEvent e) {
        if (getConfig().getBoolean("player-kills-only", false) && e.getEntity().getKiller() == null) return;
        ConfigurationSection all = getConfig().getConfigurationSection("drops");
        if (all == null) return;
        ConfigurationSection d = all.getConfigurationSection(e.getEntityType().name().toLowerCase(Locale.ROOT));
        if (d == null) return;
        Material m = Material.matchMaterial(d.getString("item", ""));
        if (m == null || !m.isItem()) return;
        if (ThreadLocalRandom.current().nextDouble(100.0) >= d.getDouble("chance", 0)) return;
        e.getDrops().add(new ItemStack(m, Math.max(1, Math.min(64, d.getInt("amount", 1)))));
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 1 && args[0].equalsIgnoreCase("reload")) reloadConfig();
        ConfigurationSection all = getConfig().getConfigurationSection("drops");
        int mobs = 0, unknown = 0;
        StringBuilder list = new StringBuilder();
        if (all != null) for (String mob : all.getKeys(false)) {
            ConfigurationSection d = all.getConfigurationSection(mob);
            if (d == null) continue;
            mobs++;
            Material m = Material.matchMaterial(d.getString("item", ""));
            if (m == null) unknown++;
            list.append("\n").append(mob).append(": ").append(d.getDouble("chance", 0)).append("% ").append(m == null ? "unknown item" : m.name()).append(" x").append(d.getInt("amount", 1));
        }
        if (args.length == 1 && args[0].equalsIgnoreCase("reload")) sender.sendMessage(Component.text("CyrusDrops reloaded: " + mobs + " mobs, " + unknown + " unknown items.", NamedTextColor.GREEN));
        else sender.sendMessage(Component.text("Custom drops:" + list, NamedTextColor.AQUA));
        return true;
    }
}
EOF
echo ok

