package dev.nxeon.starter.tpa;

import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerMoveEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;

/** Cyrus starter bank: /tpa requests (expire), a countdown that cancels on movement, and a per-player cooldown. */
public class Tpa extends JavaPlugin implements Listener {
    /** target -> (requester -> expires at ms). Main thread only. */
    private final Map<UUID, Map<UUID, Long>> requests = new HashMap<>();
    private final Map<UUID, Long> cooldownUntil = new HashMap<>();
    /** requester -> the block they stood on when the countdown started. */
    private final Map<UUID, Location> counting = new HashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        for (String c : new String[] {"tpa", "tpaccept", "tpdeny", "tpcancel"}) getCommand(c).setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private long secs(String key, int def) { return Math.max(0, getConfig().getInt(key, def)); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
        long now = System.currentTimeMillis();
        switch (command.getName().toLowerCase()) {
            case "tpa" -> {
                if (args.length != 1) { p.sendMessage(Component.text("Usage: /tpa <player>", NamedTextColor.YELLOW)); return true; }
                Player target = Bukkit.getPlayerExact(args[0]);
                if (target == null || target == p) { p.sendMessage(Component.text("That player is not online.", NamedTextColor.RED)); return true; }
                long until = cooldownUntil.getOrDefault(p.getUniqueId(), 0L);
                if (now < until && !p.hasPermission("cyrustpa.bypass")) { p.sendMessage(Component.text("Wait " + ((until - now + 999) / 1000) + " s before the next request.", NamedTextColor.RED)); return true; }
                requests.computeIfAbsent(target.getUniqueId(), k -> new HashMap<>()).put(p.getUniqueId(), now + secs("request-expire-seconds", 60) * 1000);
                cooldownUntil.put(p.getUniqueId(), now + secs("cooldown-seconds", 30) * 1000);
                p.sendMessage(Component.text("Request sent to " + target.getName() + ".", NamedTextColor.GREEN));
                target.sendMessage(Component.text(p.getName() + " wants to teleport to you. /tpaccept or /tpdeny (expires in " + secs("request-expire-seconds", 60) + " s).", NamedTextColor.AQUA));
            }
            case "tpcancel" -> {
                boolean any = false;
                for (Map<UUID, Long> m : requests.values()) any |= m.remove(p.getUniqueId()) != null;
                p.sendMessage(Component.text(any ? "Request withdrawn." : "You have no open request.", any ? NamedTextColor.GREEN : NamedTextColor.RED));
            }
            default -> {
                boolean accept = command.getName().equalsIgnoreCase("tpaccept");
                Map<UUID, Long> mine = requests.getOrDefault(p.getUniqueId(), new HashMap<>());
                mine.values().removeIf(exp -> exp < now);
                UUID from = null;
                if (args.length == 1) { Player x = Bukkit.getPlayerExact(args[0]); if (x != null && mine.containsKey(x.getUniqueId())) from = x.getUniqueId(); }
                else { long best = -1; for (Map.Entry<UUID, Long> en : mine.entrySet()) if (en.getValue() > best) { best = en.getValue(); from = en.getKey(); } }
                Player req = from == null ? null : Bukkit.getPlayer(from);
                if (req == null) { p.sendMessage(Component.text("No open teleport request.", NamedTextColor.RED)); return true; }
                mine.remove(from);
                if (!accept) { p.sendMessage(Component.text("Request denied.", NamedTextColor.YELLOW)); req.sendMessage(Component.text(p.getName() + " denied your request.", NamedTextColor.RED)); return true; }
                p.sendMessage(Component.text("Request accepted.", NamedTextColor.GREEN));
                long count = req.hasPermission("cyrustpa.bypass") ? 0 : secs("countdown-seconds", 3);
                counting.put(req.getUniqueId(), req.getLocation().toBlockLocation());
                countdown(req.getUniqueId(), p.getUniqueId(), (int) count);
            }
        }
        return true;
    }

    /** One step per second (one-off delays); stops when the requester moved, left, or the target left. */
    private void countdown(UUID who, UUID to, int left) {
        Player p = Bukkit.getPlayer(who), t = Bukkit.getPlayer(to);
        if (p == null || !counting.containsKey(who)) return;
        if (t == null) { counting.remove(who); p.sendMessage(Component.text("Teleport cancelled: the player left.", NamedTextColor.RED)); return; }
        if (left <= 0) {
            counting.remove(who);
            p.teleportAsync(t.getLocation()).thenAccept(ok -> { if (ok) p.sendMessage(Component.text("Teleported to " + t.getName() + ".", NamedTextColor.GREEN)); });
            return;
        }
        p.sendActionBar(Component.text("Teleporting in " + left + " s, do not move", NamedTextColor.YELLOW));
        getServer().getScheduler().runTaskLater(this, () -> countdown(who, to, left - 1), 20L);
    }

    @EventHandler(ignoreCancelled = true)
    public void onMove(PlayerMoveEvent e) {
        if (!e.hasChangedBlock()) return;
        Location start = counting.get(e.getPlayer().getUniqueId());
        if (start == null) return;
        counting.remove(e.getPlayer().getUniqueId());
        e.getPlayer().sendActionBar(Component.text("Teleport cancelled: you moved.", NamedTextColor.RED));
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) {
        UUID id = e.getPlayer().getUniqueId();
        requests.remove(id);
        counting.remove(id);
        for (Iterator<Map<UUID, Long>> it = requests.values().iterator(); it.hasNext(); ) { Map<UUID, Long> m = it.next(); m.remove(id); if (m.isEmpty()) it.remove(); }
        if (cooldownUntil.getOrDefault(id, 0L) < System.currentTimeMillis()) cooldownUntil.remove(id);
    }
}
EOF
