package dev.nxeon.starter.rulesaccept;

import java.io.File;
import java.io.IOException;
import java.util.List;
import java.util.UUID;
import net.kyori.adventure.inventory.Book;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.minimessage.MiniMessage;
import org.bukkit.Material;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.event.player.PlayerMoveEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.BookMeta;
import org.bukkit.plugin.java.JavaPlugin;

/** Cyrus starter bank: a rules book on join, frozen (no walking) until /accept; acceptance saved in accepted.yml. */
public class RulesAccept extends JavaPlugin implements Listener {
    private File file;
    private YamlConfiguration accepted;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "accepted.yml");
        accepted = YamlConfiguration.loadConfiguration(file);
        getCommand("accept").setExecutor(this);
        getCommand("rules").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    @Override
    public void onDisable() { save(); }

    private void save() {
        try { accepted.save(file); } catch (IOException e) { getLogger().warning("Could not save accepted.yml: " + e.getMessage()); }
    }

    private boolean hasAccepted(UUID id) { return accepted.contains(id.toString()); }

    private List<Component> pages() { return getConfig().getStringList("book.pages").stream().map(MiniMessage.miniMessage()::deserialize).toList(); }

    private Component msg(String key, String def) { return MiniMessage.miniMessage().deserialize(getConfig().getString(key, def)); }

    private ItemStack book() {
        ItemStack it = new ItemStack(Material.WRITTEN_BOOK);
        it.editMeta(BookMeta.class, m -> {
            m.title(Component.text(getConfig().getString("book.title", "Server Rules")));
            m.author(Component.text("Staff"));
            m.pages(pages());
        });
        return it;
    }

    @EventHandler
    public void onJoin(PlayerJoinEvent e) {
        Player p = e.getPlayer();
        if (hasAccepted(p.getUniqueId())) return;
        if (!p.getInventory().containsAtLeast(book(), 1)) p.getInventory().addItem(book());
        p.sendMessage(msg("messages.frozen", "Type /accept to play."));
    }

    @EventHandler(ignoreCancelled = true)
    public void onMove(PlayerMoveEvent e) {
        if (!e.hasChangedBlock() || hasAccepted(e.getPlayer().getUniqueId())) return;
        e.setCancelled(true);
        e.getPlayer().sendActionBar(msg("messages.frozen", "Type /accept to play."));
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (command.getName().equalsIgnoreCase("accept")) {
            if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
            if (hasAccepted(p.getUniqueId())) { p.sendMessage(Component.text("You already accepted the rules.", NamedTextColor.GRAY)); return true; }
            accepted.set(p.getUniqueId().toString(), p.getName());
            save();
            p.sendMessage(msg("messages.accepted", "Thanks!"));
            return true;
        }
        if (args.length == 2 && args[0].equalsIgnoreCase("reset")) {
            if (!sender.hasPermission("cyrusrules.admin")) { sender.sendMessage(Component.text("No permission.", NamedTextColor.RED)); return true; }
            String found = null;
            for (String id : accepted.getKeys(false)) if (args[1].equalsIgnoreCase(accepted.getString(id, ""))) found = id;
            if (found == null) { sender.sendMessage(Component.text(args[1] + " has not accepted the rules.", NamedTextColor.RED)); return true; }
            accepted.set(found, null);
            save();
            sender.sendMessage(Component.text(args[1] + " must accept the rules again.", NamedTextColor.GREEN));
            return true;
        }
        if (sender instanceof Player p) { p.openBook(Book.book(Component.text(getConfig().getString("book.title", "Server Rules")), Component.text("Staff"), pages())); return true; }
        sender.sendMessage(Component.text("Rules book: " + pages().size() + " pages, " + accepted.getKeys(false).size() + " players accepted.", NamedTextColor.YELLOW));
        return true;
    }
}
EOF
