            save();
            sender.sendMessage(Component.text(args[1] + " must accept the rules again.", NamedTextColor.GREEN));
            return true;
        }
        if (sender instanceof Player p) { p.openBook(Book.book(Component.text(getConfig().getString("book.title", "Server Rules")), Component.text("Staff"), pages())); return true; }
        sender.sendMessage(Component.text("Rules book: " + pages().size() + " pages, " + accepted.getKeys(false).size() + " players accepted.", NamedTextColor.YELLOW));
