package dev.nxeon.starter.announcer;

import dev.nxeon.starter.announcer.nxperf.NxPerf;
import java.util.List;
import java.util.Set;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.minimessage.MiniMessage;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.plugin.java.JavaPlugin;

/** Cyrus starter bank: rotating broadcasts (NxPerf timer) and /restartin countdown marks, then the server stops. */
public class Announcer extends JavaPlugin {
    private static final Set<Long> MARKS = Set.of(600L, 300L, 60L, 5L, 4L, 3L, 2L, 1L);
    private int next = 0;
    private NxPerf.Timer countdown;
    private long secondsLeft;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("restartin").setExecutor(this);
        long period = Math.max(1, getConfig().getInt("interval-minutes", 5)) * 1200L;
        NxPerf.timer("announcements", period, period, this::announce);
    }

    private void announce() {
        List<String> msgs = getConfig().getStringList("messages");
        if (msgs.isEmpty()) return;
        if (next >= msgs.size()) next = 0;
        getServer().broadcast(MiniMessage.miniMessage().deserialize(msgs.get(next++)));
    }

    private static String human(long s) { return s >= 60 ? (s / 60) + (s / 60 == 1 ? " minute" : " minutes") : s + (s == 1 ? " second" : " seconds"); }

    private void tick() {
        if (secondsLeft <= 0) {
            if (countdown != null) countdown.cancel();
            countdown = null;
            getServer().shutdown();
            return;
        }
        if (MARKS.contains(secondsLeft)) getServer().broadcast(MiniMessage.miniMessage().deserialize(getConfig().getString("restart-message", "Server restart in {time}!").replace("{time}", human(secondsLeft))));
        secondsLeft--;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 1 && args[0].equalsIgnoreCase("cancel")) {
            if (countdown == null) { sender.sendMessage(Component.text("No restart countdown is running.", NamedTextColor.YELLOW)); return true; }
            countdown.cancel();
            countdown = null;
            getServer().broadcast(Component.text("The restart was cancelled.", NamedTextColor.GREEN));
            return true;
        }
        int minutes;
        try { minutes = args.length == 1 ? Integer.parseInt(args[0]) : -1; } catch (NumberFormatException e) { minutes = -1; }
        if (minutes < 1 || minutes > 1440) { sender.sendMessage(Component.text("Usage: /restartin <minutes> | cancel", NamedTextColor.YELLOW)); return true; }
        if (countdown != null) countdown.cancel();
        secondsLeft = minutes * 60L;
        getServer().broadcast(MiniMessage.miniMessage().deserialize(getConfig().getString("restart-message", "Server restart in {time}!").replace("{time}", human(secondsLeft))));
        countdown = NxPerf.timer("restart-countdown", 20L, 20L, this::tick);
        return true;
    }
}
EOF
