package dev.nxeon.starter.warps;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.TreeSet;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Location;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;

/** Cyrus starter bank: /setwarp + /delwarp (operators), /warp [name] (everyone); saved in warps.yml. */
public class Warps extends JavaPlugin implements TabCompleter {
    private File file;
    private YamlConfiguration warps;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "warps.yml");
        warps = YamlConfiguration.loadConfiguration(file);
        for (String c : new String[] {"warp", "setwarp", "delwarp"}) { getCommand(c).setExecutor(this); getCommand(c).setTabCompleter(this); }
    }

    @Override
    public void onDisable() { save(); }

    private void save() {
        try { warps.save(file); } catch (IOException e) { getLogger().warning("Could not save warps.yml: " + e.getMessage()); }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String cmd = command.getName().toLowerCase();
        String name = args.length > 0 ? args[0].toLowerCase() : "";
        if (cmd.equals("warp") && name.isEmpty()) {
            TreeSet<String> all = new TreeSet<>(warps.getKeys(false));
            sender.sendMessage(Component.text(all.isEmpty() ? "No warps yet." : "Warps: " + String.join(", ", all), NamedTextColor.AQUA));
            return true;
        }
        if (!name.matches("[a-z0-9_]{1,16}")) { sender.sendMessage(Component.text("Usage: /" + label + " <name> (1-16 letters, digits or _)", NamedTextColor.YELLOW)); return true; }
        if (cmd.equals("delwarp")) {
            if (!warps.contains(name)) { sender.sendMessage(Component.text("No warp called " + name + ".", NamedTextColor.RED)); return true; }
            warps.set(name, null);
            save();
            sender.sendMessage(Component.text("Warp " + name + " deleted.", NamedTextColor.YELLOW));
            return true;
        }
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
        if (cmd.equals("setwarp")) {
            if (!warps.contains(name) && warps.getKeys(false).size() >= Math.max(1, getConfig().getInt("max-warps", 100))) { p.sendMessage(Component.text("The server has reached its warp limit.", NamedTextColor.RED)); return true; }
            warps.set(name, p.getLocation());
            save();
            p.sendMessage(Component.text("Warp " + name + " set.", NamedTextColor.GREEN));
            return true;
        }
        Location loc = warps.getLocation(name);
        if (loc == null || loc.getWorld() == null) { p.sendMessage(Component.text("No warp called " + name + ".", NamedTextColor.RED)); return true; }
        long warmup = Math.max(0, getConfig().getInt("warmup-seconds", 0));
        if (warmup > 0) p.sendActionBar(Component.text("Warping in " + warmup + " s", NamedTextColor.YELLOW));
        getServer().getScheduler().runTaskLater(this, () -> {
            if (p.isOnline()) p.teleportAsync(loc).thenAccept(ok -> { if (ok) p.sendMessage(Component.text("Warped to " + name + ".", NamedTextColor.GREEN)); });
        }, Math.max(1L, warmup * 20L));
        return true;
    }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command command, String alias, String[] args) {
        if (args.length != 1 || command.getName().equalsIgnoreCase("setwarp")) return List.of();
        List<String> out = new ArrayList<>();
        for (String k : warps.getKeys(false)) if (k.startsWith(args[0].toLowerCase())) out.add(k);
        return out;
    }
}
