package dev.nxeon.starter.kits;

import dev.nxeon.starter.kits.nxperf.NxPerf;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

/** Cyrus starter bank: config-defined kits (ITEM:amount lists) with a per-player cooldown saved in claims.yml. */
public class Kits extends JavaPlugin {
    private File file;
    private YamlConfiguration claims;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "claims.yml");
        claims = YamlConfiguration.loadConfiguration(file);
        getCommand("kit").setExecutor(this);
        getCommand("kits").setExecutor(this);
    }

    @Override
    public void onDisable() { save(); }

    private void save() {
        try { claims.save(file); } catch (IOException e) { getLogger().warning("Could not save claims.yml: " + e.getMessage()); }
    }

    private List<ItemStack> items(ConfigurationSection kit) {
        List<ItemStack> out = new ArrayList<>();
        for (String line : kit.getStringList("items")) {
            String[] parts = line.split(":");
            Material m = Material.matchMaterial(parts[0].trim());
            if (m == null || !m.isItem()) { getLogger().warning("Unknown kit item " + parts[0]); continue; }
            int n = 1;
            try { if (parts.length > 1) n = Integer.parseInt(parts[1].trim()); } catch (NumberFormatException ignored) { n = 1; }
            out.add(new ItemStack(m, Math.max(1, Math.min(m.getMaxStackSize(), n))));
        }
        return out;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        ConfigurationSection kits = getConfig().getConfigurationSection("kits");
        if (command.getName().equalsIgnoreCase("kits") || args.length == 0) {
            List<String> names = new ArrayList<>();
            if (kits != null) for (String k : kits.getKeys(false)) { ConfigurationSection s = kits.getConfigurationSection(k); if (s != null) names.add(k + " (" + Math.round(s.getDouble("cooldown-hours", 24)) + " h)"); }
            sender.sendMessage(Component.text(names.isEmpty() ? "No kits." : "Kits: " + String.join(", ", names), NamedTextColor.AQUA));
            return true;
        }
        String name = args[0].toLowerCase(Locale.ROOT);
        ConfigurationSection kit = kits == null ? null : kits.getConfigurationSection(name);
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
        if (kit == null) { p.sendMessage(Component.text("No kit called " + name + ".", NamedTextColor.RED)); return true; }
        String key = p.getUniqueId() + "." + name;
        long now = System.currentTimeMillis(), ready = claims.getLong(key, 0L) + (long) (Math.max(0, kit.getDouble("cooldown-hours", 24)) * 3_600_000L);
        if (now < ready && !p.hasPermission("cyruskits.bypass")) {
            long mins = (ready - now) / 60000 + 1;
            p.sendMessage(Component.text("You can claim this kit again in " + (mins >= 60 ? mins / 60 + " h " + mins % 60 + " min" : mins + " min") + ".", NamedTextColor.RED));
            return true;
        }
        Location at = p.getLocation();
        for (ItemStack extra : p.getInventory().addItem(items(kit).toArray(new ItemStack[0])).values()) {
            if (NxPerf.spawnAllowed("kit-drop", at.getChunk())) p.getWorld().dropItemNaturally(at, extra);
        }
        claims.set(key, now);
        save();
        p.sendMessage(Component.text("You received the " + name + " kit.", NamedTextColor.GREEN));
        return true;
    }
}
