package dev.nxeon.starter.afk;

import dev.nxeon.starter.afk.nxperf.NxPerf;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerMoveEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;

/** Cyrus starter bank: AFK after N minutes without changing block (checked every 10 s), optional kick; /afk toggles. */
public class Afk extends JavaPlugin implements Listener {
    private final Map<UUID, Long> lastActive = new HashMap<>();
    private final Set<UUID> afk = new HashSet<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("afk").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        NxPerf.timer("afk-check", 200L, 200L, this::check);
    }

    private void announce(Player p, boolean now) {
        if (getConfig().getBoolean("announce", true)) getServer().broadcast(Component.text(p.getName() + (now ? " is now AFK." : " is no longer AFK."), NamedTextColor.GRAY));
    }

    private void check() {
        long now = System.currentTimeMillis();
        long afterMs = Math.max(1, getConfig().getInt("afk-after-minutes", 5)) * 60_000L, kickMs = Math.max(0, getConfig().getInt("kick-after-minutes", 0)) * 60_000L;
        for (Player p : getServer().getOnlinePlayers()) {
            long idle = now - lastActive.computeIfAbsent(p.getUniqueId(), k -> now);
            if (idle >= afterMs && afk.add(p.getUniqueId())) announce(p, true);
            if (kickMs > 0 && idle >= kickMs && !p.hasPermission("cyrusafk.exempt")) p.kick(Component.text("Kicked for being AFK."));
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onMove(PlayerMoveEvent e) {
        if (!e.hasChangedBlock()) return;
        lastActive.put(e.getPlayer().getUniqueId(), System.currentTimeMillis());
        if (afk.remove(e.getPlayer().getUniqueId())) announce(e.getPlayer(), false);
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) { lastActive.remove(e.getPlayer().getUniqueId()); afk.remove(e.getPlayer().getUniqueId()); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("CyrusAfk: " + afk.size() + " AFK, after " + getConfig().getInt("afk-after-minutes", 5) + " min.", NamedTextColor.GRAY)); return true; }
        if (afk.remove(p.getUniqueId())) { lastActive.put(p.getUniqueId(), System.currentTimeMillis()); announce(p, false); }
        else { afk.add(p.getUniqueId()); announce(p, true); }
        return true;
    }
}
EOF
