package dev.nxeon.starter.firstjoin;

import dev.nxeon.starter.firstjoin.nxperf.NxPerf;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.minimessage.MiniMessage;
import net.kyori.adventure.title.Title;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

/** Cyrus starter bank: a kit and a welcome title on the first join only (Minecraft's hasPlayedBefore). */
public class FirstJoin extends JavaPlugin implements Listener {
    private int unknown;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("firstjoin").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private List<ItemStack> kit() {
        List<ItemStack> out = new ArrayList<>();
        unknown = 0;
        for (String line : getConfig().getStringList("items")) {
            String[] parts = line.split(":");
            Material m = Material.matchMaterial(parts[0].trim());
            if (m == null || !m.isItem()) { unknown++; continue; }
            int n = 1;
            try { if (parts.length > 1) n = Integer.parseInt(parts[1].trim()); } catch (NumberFormatException ignored) { n = 1; }
            out.add(new ItemStack(m, Math.max(1, Math.min(m.getMaxStackSize(), n))));
        }
        return out;
    }

    private Component text(String key, String def, Player p) {
        return MiniMessage.miniMessage().deserialize(getConfig().getString(key, def).replace("{player}", MiniMessage.miniMessage().escapeTags(p.getName())));
    }

    @EventHandler
    public void onJoin(PlayerJoinEvent e) {
        Player p = e.getPlayer();
        if (p.hasPlayedBefore()) return;
        Location at = p.getLocation();
        for (ItemStack extra : p.getInventory().addItem(kit().toArray(new ItemStack[0])).values()) {
            if (NxPerf.spawnAllowed("first-join-drop", at.getChunk())) p.getWorld().dropItemNaturally(at, extra);
        }
        p.showTitle(Title.title(text("title", "<gold>Welcome!", p), text("subtitle", "", p), Title.Times.times(Duration.ofMillis(500), Duration.ofSeconds(4), Duration.ofMillis(800))));
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        List<ItemStack> k = kit();
        sender.sendMessage(Component.text("First-join kit: " + k.size() + " items, " + unknown + " unknown.", NamedTextColor.AQUA));
        return true;
    }
}
EOF
