public class CustomItem extends JavaPlugin {
    private NamespacedKey tag;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        tag = new NamespacedKey(this, "custom_item");
        getCommand("giveitem").setExecutor(this);
    }

    /** Attribute by registry key; 1.21.1 still uses the generic. prefix. */
    static Attribute attribute(String name) {
        Attribute a = Registry.ATTRIBUTE.get(NamespacedKey.minecraft(name));
        return a != null ? a : Registry.ATTRIBUTE.get(NamespacedKey.minecraft("generic." + name));
