            if (spd != null) meta.addAttributeModifier(spd, new AttributeModifier(new NamespacedKey(this, "item_speed"), Math.max(0.05, speed) - 4.0, AttributeModifier.Operation.ADD_NUMBER, EquipmentSlotGroup.MAINHAND));
        });
        return it;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
