#!/usr/bin/env node
"use strict";
// Starter bank harness (Cyrus starter bank). Proves every bank entry the way a bank build is produced by the service: the entry
// is materialized with bank.js, the settings round (configs.js) writes config.yml from the schema, the pre-check + perf check
// must be clean, the perf watchdog is injected (perf.js), javac --release 21 -Xlint:deprecation,removal runs against the real
// Paper API classpath of each version, the warning rules and the strict bytecode + source scan must be clean, and a jar is
// packed. Writes <out>/compile.json and <out>/<version>/flight-spec.json (every jar + its entry.json RCON checks) for
//   npx tsx scripts/cyrus/golden-flight.ts fly <version> --remote-out <out>
// Runs on the build host (node-2):
//   scripts/devhost run --lock -- node services/modbuilder/golden/bank-harness.js [--versions 1.21.11,1.21.4] [--only homes,kits]
//        [--cp-dir /tank/nxeon-build/tmp/mc-coverage/cp] [--jdk /tank/nxeon-build/tmp/testflight/jdk/21] [--out /tank/nxeon-build/tmp/testflight/starter-bank]
//   --params '{"heal-feed":{"heal-cooldown-seconds":30}}' builds with request parameters (default: the schema defaults).
const fs = require("fs");
const os = require("os");
const path = require("path");
const crypto = require("crypto");
const { execFileSync, spawnSync } = require("child_process");

const ROOT = path.resolve(__dirname, "..");
const argv = process.argv.slice(2);
const opt = (n, d) => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] ? argv[i + 1] : d; };
const VERSIONS = opt("versions", "1.21.1,1.21.4,1.21.8,1.21.11").split(",");
const ONLY = opt("only", "") ? new Set(opt("only").split(",")) : null;
const CP_DIR = opt("cp-dir", "/tank/nxeon-build/tmp/mc-coverage/cp");
const JDK = opt("jdk", "/tank/nxeon-build/tmp/testflight/jdk/21");
const OUT = opt("out", "/tank/nxeon-build/tmp/testflight/starter-bank");
const PARAMS = JSON.parse(opt("params", "{}"));
process.env.PATH = `${JDK}/bin:${process.env.PATH}`; // scan.js runs `javap` from PATH
process.env.MB_CP_DIR = CP_DIR;

const BANK = require(path.join(ROOT, "bank.js"));
const CFG = require(path.join(ROOT, "configs.js"));
const PERF = require(path.join(ROOT, "perf.js"));
const { precheck, warningCheck } = require(path.join(ROOT, "precheck.js"));
const { scanBytecode, scanSource } = require(path.join(ROOT, "scan.js"));
const sha256 = (b) => crypto.createHash("sha256").update(b).digest("hex");
const javaOf = (ws) => BANK.walk(path.join(ws, "src/main/java")).filter((f) => f.rel.endsWith(".java")).map((f) => ({ rel: `src/main/java/${f.rel}`, abs: f.abs }));

/** The non-AI part of a bank build for one version, in the service's order. Exported for the unit test (no javac there). */
function prepare(id, v, params, ws) {
  BANK.materialize(id, params || {}, ws);
  const ymlPath = path.join(ws, "src/main/resources/plugin.yml");
  fs.writeFileSync(ymlPath, fs.readFileSync(ymlPath, "utf8").replace(/^api-version:.*$/m, `api-version: '${v}'`)); // as validate() pins it
  const rec = { id: `bank-${id}`, mcVersion: v, pluginName: BANK.entries().get(id).pluginName };
  const problem = CFG.configRound(ws, rec, { configRepairs: 1 }, false);
  const java = javaOf(ws);
  const pre = [...precheck(java, v), ...PERF.perfcheck(java), ...PERF.configCheck(ws)];
  return { rec, problem, config: rec.configResult, precheck: pre };
}

function buildOne(id, v) {
  const ws = fs.mkdtempSync(path.join(os.tmpdir(), `bank-${id}-`));
  const res = { compile: "fail", scan: "not_run", errors: "", warnings: [], warningRules: [], precheck: [], findings: [], config: null };
  try {
    const p = prepare(id, v, PARAMS[id], ws);
    res.precheck = p.precheck;
    res.config = p.config ? { source: p.config.source, warnings: p.config.warnings, read: p.config.verify ? p.config.verify.read : null } : null;
    if (p.problem) { res.errors = `settings: ${p.problem.text}`; return res; }
    PERF.inject(ws, p.rec);
    const cp = fs.readFileSync(path.join(CP_DIR, `${v}.txt`), "utf8").trim();
    const classes = path.join(ws, "build/classes");
    fs.mkdirSync(classes, { recursive: true });
    const java = javaOf(ws);
    const r = spawnSync(path.join(JDK, "bin/javac"), ["-J-Xmx768m", "--release", "21", "-encoding", "UTF-8", "-proc:none", "-Xmaxerrs", "40", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...java.map((f) => f.abs)], { encoding: "utf8", timeout: 180000 });
    const output = ((r.stderr || "") + (r.stdout || "")).split(ws + "/").join("");
    res.warnings = (output.match(/warning: \[(deprecation|removal)\][^\n]*/g) || []).slice(0, 20);
    res.warningRules = warningCheck(res.warnings, v);
    if (r.status !== 0) { res.errors = output.slice(0, 6000); return res; }
    res.compile = res.warnings.length || res.precheck.length || (res.config && res.config.source !== "declared") ? "warn" : "pass";
    res.findings = [...scanBytecode(classes), ...scanSource(java)];
    res.scan = res.findings.some((f) => f.severity === "block") ? "fail" : res.findings.length ? "warn" : "pass";
    for (const f of BANK.walk(path.join(ws, "src/main/resources"))) { fs.mkdirSync(path.dirname(path.join(classes, f.rel)), { recursive: true }); fs.copyFileSync(f.abs, path.join(classes, f.rel)); }
    const entries = BANK.walk(classes).map((f) => f.rel).sort();
    const jarOut = path.join(OUT, v, `${id}.jar`);
    fs.mkdirSync(path.dirname(jarOut), { recursive: true });
    const args = ["--create", "--file", jarOut, "--date", "2026-01-01T00:00:00Z"];
    for (const e of entries) args.push("-C", classes, e);
    execFileSync(path.join(JDK, "bin/jar"), args, { timeout: 60000 });
    res.jar = jarOut;
    res.jarSha256 = sha256(fs.readFileSync(jarOut));
    return res;
  } finally {
    fs.rmSync(ws, { recursive: true, force: true });
  }
}

function main() {
  const ids = [...BANK.entries().keys()].filter((id) => !ONLY || ONLY.has(id)).sort();
  if (BANK.loadEntries().problems.length) process.stderr.write(`bank problems: ${BANK.loadEntries().problems.join("; ")}\n`);
  const results = { schema: 1, bank: BANK.bankVersion(), versions: VERSIONS, jdk: JDK, cpDir: CP_DIR, entries: {} };
  for (const id of ids) {
    const e = BANK.entries().get(id);
    results.entries[id] = { version: e.version, sha256: e.sha256, pluginName: e.pluginName, versions: {} };
    for (const v of VERSIONS) {
      if (Array.isArray(e.mcVersions) && !e.mcVersions.includes(v)) { results.entries[id].versions[v] = { compile: "n/a" }; continue; }
      const r = buildOne(id, v);
      results.entries[id].versions[v] = r;
      const bad = [r.errors && "COMPILE/SETTINGS", r.warnings.length && `${r.warnings.length} warn`, r.precheck.length && `precheck ${r.precheck.map((x) => x.rule).join("+")}`, r.findings.length && `scan ${r.scan}`, r.config && r.config.source !== "declared" && `settings ${r.config.source}`].filter(Boolean);
      process.stderr.write(`${id} ${v}: ${r.compile}/${r.scan}${bad.length ? " " + bad.join(", ") : ""}\n`);
      if (r.errors) process.stderr.write(r.errors.slice(0, 1500) + "\n");
    }
  }
  fs.mkdirSync(OUT, { recursive: true });
  fs.writeFileSync(path.join(OUT, "compile.json"), JSON.stringify(results, null, 1));
  for (const v of VERSIONS) {
    const plugins = [], rcon = [];
    for (const id of ids) {
      const r = results.entries[id].versions[v];
      if (!r || !r.jar || r.scan === "fail") continue;
      plugins.push({ remotePath: r.jar, sha256: r.jarSha256 });
      for (const [i, c] of ((BANK.entries().get(id).flight || {}).rcon || []).entries()) rcon.push({ id: `${id}#${i}`, command: c.command, expect: c.expect || [], expectNot: [...(c.expectNot || []), "An internal error occurred", "Unknown or incomplete command", "Exception"] });
    }
    if (plugins.length) fs.writeFileSync(path.join(OUT, v, "flight-spec.json"), JSON.stringify({ version: v, plugins, rcon }, null, 1));
  }
  // golden-flight.ts reads plugin names from compile.json "plugins"
  fs.writeFileSync(path.join(OUT, "compile.json"), JSON.stringify({ ...results, plugins: Object.fromEntries(Object.entries(results.entries).map(([id, x]) => [id, { versions: Object.fromEntries(Object.entries(x.versions).map(([v, r]) => [v, { pluginName: x.pluginName, jar: r.jar }])) }])) }, null, 1));
  process.stdout.write(JSON.stringify({ ok: true, out: path.join(OUT, "compile.json"), entries: ids.length }) + "\n");
}

if (require.main === module) main();
module.exports = { prepare };

