      const roundFixes = [...(v.fixes || [])];
      let fixesRecorded = false;
      // A round whose auto-fixes ended in a clean compile is a model repair that was not needed.
      const recordFixes = (compiledOk) => {
        if (fixesRecorded || !roundFixes.length) return;
        fixesRecorded = true;
        rec.autofixes = [...(rec.autofixes || []), ...roundFixes.map((f) => ({ ...f, attempt: rec.attempts }))].slice(-40);
