// Cyrus starter bank (MB_STARTER_BANK=1): a prebuilt, Nxeon-authored entry is copied in (bank.js), its settings schema gets
// the request's parameters as defaults, then every non-AI check of a normal build runs: validate, settings round, pre-check +
// perf check, javac with the perf watchdog, warning rules, bytecode + source scan. NO model call, ever. Anything that does not
// pass fails the build honestly (bank_unavailable, free on the portal side) instead of silently starting a paid AI build.
async function runBank(rec, ctl, ws) {
  const t0 = Date.now();
  try {
    rec.route = { class: "bank", method: "starter-bank", models: { generate: null, repairCheap: null, escalate: null } };
    rec.model = null;
    setStage(rec, "compiling", "Preparing the ready-made mod (no AI needed)");
    copyDir(TEMPLATE, ws);
    BANK.materialize(rec.bank.id, rec.bank.params, ws);
    rec.attempts = 1;
    const v = validate(ws, rec);
    if (v.problems.length) throw fail("bank_unavailable", "The ready-made version of this mod did not pass today's checks, so nothing was built. Build it with the AI instead.", v.problems.join("\n").slice(0, 2000));
    const cr = CFG.configRound(ws, rec, { configRepairs: 1 }, false);
    if (cr || !rec.configResult || rec.configResult.source !== "declared") throw fail("bank_unavailable", "The ready-made version of this mod did not pass the settings check, so nothing was built. Build it with the AI instead.", cr ? cr.text : JSON.stringify(rec.configResult || {}).slice(0, 2000));
    const java = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java"));
    const pre = [...precheck(java, rec.mcVersion), ...PERF.perfcheck(java), ...PERF.configCheck(ws)];
    if (pre.length) throw fail("bank_unavailable", "The ready-made version of this mod did not pass today's checks, so nothing was built. Build it with the AI instead.", pre.map((h) => `${h.rule} ${h.where}`).join("\n"));
    event(rec, "compiling", "Compiling the ready-made mod");
    const c = await compile(ws, rec, ctl);
    if (!c.ok || warningCheck(c.warnings, rec.mcVersion).length || c.warnings.length) throw fail("bank_unavailable", "The ready-made version of this mod did not compile for this version, so nothing was built. Build it with the AI instead.", (c.errors || c.warnings.join("\n") || "").slice(0, 4000));
    setStage(rec, "scanning", "Running the safety check");
    const findings = [...scanBytecode(c.classes), ...scanSource(listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")))];
    if (findings.some((f) => f.severity === "block")) throw fail("bank_unavailable", "The ready-made version of this mod did not pass the safety check, so nothing was built.", findings.map((f) => f.rule).join(","));
    rec.safety = { verdict: findings.some((f) => f.severity === "warn") ? "warn" : "pass", findings };
    event(rec, "scanning", "Safety check passed");
    await finish(rec, ws, c, v.yml);
    rec.summary.limitations = [...rec.summary.limitations, "This is a ready-made Cyrus starter mod (built without AI). Change its settings in the Config Studio, or ask Cyrus for a change to build on it."].slice(0, 12);
  } finally { U.addTime(rec, "bank", Date.now() - t0); }
}

