    await finish(rec, ws, c, v.yml);
    rec.summary.limitations = [...rec.summary.limitations, "This is a ready-made Cyrus starter mod (built without AI). Change its settings in the Config Studio, or ask Cyrus for a change to build on it."].slice(0, 12);
