package dev.nxeon.golden.combattag;


/**
 * Golden combat tag: a player who deals or takes damage from another player (or a mob, with pve on) is "in combat" for N
 * seconds. Attribution uses the damage source's CAUSING entity (the archer of an arrow, the thrower of a potion, the
 * player who lit the TNT), with the projectile shooter as a fallback, so ranged hits count. While tagged, the listed
 * commands are refused; logging out kills the player once (items drop as on any death); kicks never count. State is
 * one entry per online player and is cleared on quit, death and disable: nothing grows.
 */
public class CombatTag extends JavaPlugin implements Listener {
    private final Map<UUID, Long> until = new HashMap<>();
    private final Map<UUID, String> with = new HashMap<>();
    private final Set<UUID> kicked = new HashSet<>();
    private BukkitTask timer;
    private long seconds;
    private boolean pve;
    private boolean punish;
    private Set<String> blocked = Set.of();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        load();
        getCommand("combattag").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        timer = getServer().getScheduler().runTaskTimer(this, this::tick, 20L, 20L);
    }

    @Override
    public void onDisable() {
        if (timer != null) timer.cancel();
        until.clear();
        with.clear();
        kicked.clear();
    }

    private void load() {
        reloadConfig();
        seconds = Math.max(3, Math.min(120, getConfig().getLong("seconds", 15)));
        pve = getConfig().getBoolean("pve", false);
        punish = getConfig().getBoolean("punish-logout", true);
        Set<String> b = new HashSet<>();
        for (String s : getConfig().getStringList("blocked-commands")) b.add(s.toLowerCase(Locale.ROOT).replace("/", ""));
        blocked = b;
    }

    private long now() { return getServer().getCurrentTick(); }

    private boolean tagged(Player p) { Long u = until.get(p.getUniqueId()); return u != null && u > now(); }

    private long left(Player p) { Long u = until.get(p.getUniqueId()); return u == null ? 0 : Math.max(0, (u - now() + 19) / 20); }

    private static String nameOf(Entity e) {
        if (e instanceof Player p) return p.getName();
        String k = e.getType().getKey().getKey().replace('_', ' ');
        return k.isEmpty() ? k : Character.toUpperCase(k.charAt(0)) + k.substring(1);
    }

    private void tag(Player p, String other) {
        if (p.hasPermission("goldencombattag.bypass")) return;
        boolean fresh = !tagged(p);
        until.put(p.getUniqueId(), now() + seconds * 20);
        with.put(p.getUniqueId(), other);
        if (fresh) p.sendMessage(Component.text("You are in combat with " + other + ": do not log out for " + seconds + " seconds.", NamedTextColor.RED));
    }

    /** Who is responsible for this damage: the causing entity of the damage source, else the projectile's shooter, else the damager. */
    private static Entity responsible(EntityDamageByEntityEvent e) {
        Entity cause = e.getDamageSource().getCausingEntity();
        if (cause != null) return cause;
        if (e.getDamager() instanceof Projectile pr && pr.getShooter() instanceof Entity shooter) return shooter;
        return e.getDamager();
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onDamage(EntityDamageByEntityEvent e) {
        if (!(e.getEntity() instanceof Player victim)) return;
        Entity by = responsible(e);
        if (by == null || by == victim) return;

