package dev.nxeon.starter.veinminer;

import dev.nxeon.starter.veinminer.nxperf.NxPerf;
import java.io.File;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Material;
import org.bukkit.block.Block;
import org.bukkit.block.BlockFace;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Cyrus starter bank: vein mining with BOUNDED work. The vein is found by a flood fill limited to max-blocks and to loaded
 * chunks; the extra blocks go into an NxPerf queue, which breaks at most perf.max-work-per-tick of them per tick with the
 * player's own pickaxe (breakNaturally(tool) applies Fortune and Silk Touch), so a huge vein never stalls the server.
 */
public class VeinMiner extends JavaPlugin implements Listener {
    private record Job(UUID player, Block block, Material type) { }
    private static final BlockFace[] FACES = {BlockFace.UP, BlockFace.DOWN, BlockFace.NORTH, BlockFace.SOUTH, BlockFace.EAST, BlockFace.WEST};
    private NxPerf.Queue<Job> queue;
    private File file;
    private YamlConfiguration off;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "disabled-players.yml");
        off = YamlConfiguration.loadConfiguration(file);
        queue = NxPerf.queue("veinminer", this::breakOne);
        getCommand("veinminer").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    @Override
    public void onDisable() { save(); }

    private void save() {
        try { off.save(file); } catch (IOException e) { getLogger().warning("Could not save disabled-players.yml: " + e.getMessage()); }
    }

    private boolean isPickaxe(ItemStack it) { return it != null && it.getType().name().endsWith("_PICKAXE"); }

    private Set<Material> ores() {
        Set<Material> out = new HashSet<>();
        for (String s : getConfig().getStringList("ores")) { Material m = Material.matchMaterial(s); if (m != null && m.isBlock()) out.add(m); }
        return out;
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onBreak(BlockBreakEvent e) {
        Player p = e.getPlayer();
        if (!p.isSneaking() || !p.hasPermission("cyrusveinminer.use") || off.getBoolean(p.getUniqueId().toString(), false)) return;
        if (!isPickaxe(p.getInventory().getItemInMainHand())) return;
        Material type = e.getBlock().getType();
        if (!ores().contains(type)) return;
        int max = Math.max(1, getConfig().getInt("max-blocks", 64));
        Set<Block> seen = new HashSet<>();
        ArrayDeque<Block> todo = new ArrayDeque<>(List.of(e.getBlock()));
        seen.add(e.getBlock());
        int found = 0;
        while (!todo.isEmpty() && found < max) {
            Block b = todo.poll();
            for (BlockFace f : FACES) {
                Block n = b.getRelative(f);
                if (seen.contains(n) || n.getType() != type || !n.getWorld().isChunkLoaded(n.getX() >> 4, n.getZ() >> 4)) continue;
                seen.add(n);
                todo.add(n);
                if (!queue.offer(new Job(p.getUniqueId(), n, type))) return; // queue full: the rest of the vein stays
                if (++found >= max) break;
            }
        }
    }

    private void breakOne(Job j) {
        Player p = getServer().getPlayer(j.player());
        if (p == null || j.block().getType() != j.type()) return;
        ItemStack tool = p.getInventory().getItemInMainHand();
        if (!isPickaxe(tool)) return;
        j.block().breakNaturally(tool);
        int cost = Math.max(0, getConfig().getInt("extra-durability-per-block", 1));
        if (cost > 0) p.damageItemStack(EquipmentSlot.HAND, cost);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Vein miner: up to " + getConfig().getInt("max-blocks", 64) + " blocks, " + ores().size() + " ores.", NamedTextColor.AQUA)); return true; }
        boolean nowOff = !off.getBoolean(p.getUniqueId().toString(), false);
        off.set(p.getUniqueId().toString(), nowOff ? true : null);
        save();
        p.sendMessage(Component.text("Vein mining " + (nowOff ? "off" : "on") + ".", nowOff ? NamedTextColor.YELLOW : NamedTextColor.GREEN));
        return true;
    }
}
