        if (cost > 0) p.damageItemStack(EquipmentSlot.HAND, cost);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Vein miner: up to " + getConfig().getInt("max-blocks", 64) + " blocks, " + ores().size() + " ores.", NamedTextColor.AQUA)); return true; }
        boolean nowOff = !off.getBoolean(p.getUniqueId().toString(), false);
        off.set(p.getUniqueId().toString(), nowOff ? true : null);
        save();
        p.sendMessage(Component.text("Vein mining " + (nowOff ? "off" : "on") + ".", nowOff ? NamedTextColor.YELLOW : NamedTextColor.GREEN));
        return true;
    }
}
EOF
