content.content:
// Mod Builder service 0.5: the real server.js pipeline, offline. The Claude CLI, javac, jar and
// javap are replaced by tiny fake programs, so this spends nothing and needs no JDK. It checks
// (the service passes the CLI only PATH/HOME/auth env, so the fake logs to $HOME/claude.log)
// the orchestration around the model: usage metering, the lean tool set, the deterministic
// auto-fixes (no model repair for a wrong import + a final main class), exact-repeat reuse and
// the `fresh` opt-out. Cyrus R1: texture specs (allowed -> validated + returned; invalid -> one asset
// repair; still failing -> dropped with a warning; not allowed -> section absent and the file removed;
// a change without texture rights keeps the base's specs byte for byte).
import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn, type ChildProcess } from "node:child_process";
import { gunTemplate } from "../lib/cyrus/itemmodel/templates";

const ROOT = path.resolve(__dirname, "..");
const SVC = path.join(ROOT, "services/modbuilder");
const KEY = "test-key-0123456789abcdef";

const FAKE_CLAUDE = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
const a = process.argv.slice(2);
const prompt = a[a.indexOf("--") + 1] || "";
const sys = a[a.indexOf("--system-prompt") + 1] || "";
const ti = a.indexOf("--tools"); const tools = [];
for (let i = ti + 1; ti >= 0 && i < a.length && !a[i].startsWith("--"); i++) tools.push(a[i]);
fs.appendFileSync(path.join(process.env.HOME, "claude.log"), JSON.stringify({ tools, maxTurns: a[a.indexOf("--max-turns") + 1], effort: a.includes("--effort") ? a[a.indexOf("--effort") + 1] : null, textures: /CUSTOM TEXTURES/.test(sys), sounds: /CUSTOM SOUNDS/.test(sys), datapack: /DATA PACK \\(allowed/.test(sys), design: /ITEM DESIGNER \\(this build/.test(sys), gameplay: /MENUS AND QUESTS \\(this build/.test(sys), bosses: /BOSSES AND ENCOUNTERS \\(this build/.test(sys), worldgen: /WORLD GENERATION \\(allowed/.test(sys), itemmodel: /ITEM MODEL STATES \\(allowed/.test(sys), armor: /CUSTOM ARMOR \\(this build/.test(sys), blocks: /CUSTOM BLOCKS \\(this build/.test(sys), libraryInSys: /sound-library\\/catalog\\.txt in the working directory/.test(sys), catalog: (() => { try { const st = fs.statSync(path.join(process.cwd(), "sound-library/catalog.txt")); return { size: st.size, mode: (st.mode & 0o777).toString(8) }; } catch { return null; } })(), nsInPrompt: (prompt.match(/reserved namespace is (nx_[a-z0-9]{8})/) || [])[1] || null, kind: /Build this Paper/.test(prompt) ? "generate" : /change request/.test(prompt) ? "change" : /custom asset specs need fixing/.test(prompt) ? "repair-asset" : "repair" }) + "\\n");
const ws = process.cwd();
const w = (rel, t) => { fs.mkdirSync(path.dirname(path.join(ws, rel)), { recursive: true }); fs.writeFileSync(path.join(ws, rel), t); };
const GOOD = fs.readFileSync(path.join(process.env.HOME, "ruby_sword.json"), "utf8");
const UGLY = JSON.stringify({ name: "ruby_sword", size: 16, palette: { a: "#777777" }, ops: [{ op: "fill", c: "a" }] });
const SPEC = "assets/textures/ruby_sword.json";
const SND = "assets/sounds/banshee.json";
const GOODSND = fs.readFileSync(path.join(process.env.HOME, "sound-example.json"), "utf8");
const NOSUB = GOODSND.replace('"subtitle":"Banshee shrieks",', "");
// a hard spec error the service cannot normalise (an unknown synth preset): the repair loop and the downgrade still apply
const NOPRESET = GOODSND.replace('"synth:impact"', '"synth:nope"');
const DPF = "assets/datapack/ruby_loot.json";
const GOODDP = fs.readFileSync(path.join(process.env.HOME, "datapack-example.json"), "utf8");
const WGF = "assets/datapack/glow_realm.json";
const GOODWG = fs.readFileSync(path.join(process.env.HOME, "worldgen-example.json"), "utf8");
const out = (o) => process.stdout.write(JSON.stringify(o) + "\\n");
out({ type: "system", subtype: "init", model: "claude-sonnet-5-5" });
const u1 = { input_tokens: 2, cache_creation_input_tokens: 900, cache_read_input_tokens: 14000, output_tokens: 3000 };
const u2 = { input_tokens: 2, cache_creation_input_tokens: 3100, cache_read_input_tokens: 14900, output_tokens: 40 };
const IMF = "assets/itemmodels/service_pistol.json";
if (/Build this Paper/.test(prompt) && /LANESBUILD/.test(prompt)) {
  // Cyrus armor + custom-block lanes: one spec each + a main class that uses the generated support classes
  w("src/main/resources/plugin.yml", "name: Ember\\nversion: 1.0.0\\nmain: dev.nxeon.plugins.ember.Ember\\napi-version: '1.21.11'\\ndescription: e\\nauthor: Nxeon Mod Builder\\n");
  w("src/main/java/dev/nxeon/plugins/ember/Ember.java", "package dev.nxeon.plugins.ember;\\n\\nimport org.bukkit.plugin.java.JavaPlugin;\\n\\npublic class Ember extends JavaPlugin {\\n  @Override public void onEnable() { getServer().getPluginManager().registerEvents(new ArmorSets(this), this); getServer().getPluginManager().registerEvents(new CustomBlocks(this), this); }\\n}\\n");
  w("src/main/java/dev/nxeon/plugins/ember/ArmorSets.java", "package dev.nxeon.plugins.ember;\\n// the model's own copy: must be replaced by the generated class\\nclass ArmorSets {}\\n");
  w("modbuilder.json", JSON.stringify({ name: "Ember", version: "1.0.0", tagline: "Ember armor", summary: "Adds armor and a block.", howToUse: ["Accept the resource pack"] }));
  w(SPEC, GOOD);
  const armor = { version: 1, sets: [{ id: "ember", displayName: "Ember", palette: { base: "#c2461e", light: "#f2a03c", dark: "#4a1608" }, style: "plate", armor: { helmet: 3, chestplate: 7, leggings: 6, boots: 3 } }] };
  const fixed = /assets\\/armor\\.json: /.test(prompt) || !/BADLANE/.test(prompt);
  w("assets/armor.json", JSON.stringify(fixed ? armor : { ...armor, version: 9 }));
  w("assets/blocks.json", JSON.stringify({ version: 1, blocks: [{ id: "ruby_block", displayName: "Ruby Block", texture: "ruby_sword" }] }));
} else if (/Build this Paper/.test(prompt) && /ITEMSTATES/.test(prompt)) {
  // Cyrus item model states: the gun template's three textures + its ItemModelSpec
  const g = JSON.parse(fs.readFileSync(path.join(process.env.HOME, "gun.json"), "utf8"));
  w("src/main/resources/plugin.yml", "name: Pistol\\nversion: 1.0.0\\nmain: dev.nxeon.plugins.pistol.Pistol\\napi-version: '1.21.11'\\ndescription: p\\nauthor: Nxeon Mod Builder\\n");
  w("src/main/java/dev/nxeon/plugins/pistol/Pistol.java", "package dev.nxeon.plugins.pistol;\\n\\nimport org.bukkit.plugin.java.JavaPlugin;\\n\\npublic class Pistol extends JavaPlugin {\\n}\\n");
  w("modbuilder.json", JSON.stringify({ name: "Pistol", version: "1.0.0", tagline: "A pistol", summary: "Adds a pistol.", howToUse: ["Accept the resource pack"] }));
  for (const t of g.textures) w("assets/textures/" + t.name + ".json", JSON.stringify(t));
  const bad = { ...g.spec, states: [...g.spec.states, { id: "ghost", texture: "service_pistol_ghost", when: { type: "selected" } }] };
  w(IMF, JSON.stringify(/BADSTATES|DEADSTATES/.test(prompt) ? (/DEADSTATES/.test(prompt) ? { ...bad, dead: true } : bad) : g.spec));
} else if (/Build this Paper/.test(prompt) && /TEXTURE/.test(prompt)) {
  const ns = (prompt.match(/reserved namespace is (nx_[a-z0-9]{8})/) || [])[1] || "nx_ab12cd34";
  w("src/main/resources/plugin.yml", "name: Ruby\\nversion: 1.0.0\\nmain: dev.nxeon.plugins.ruby.Ruby\\napi-version: '1.21.11'\\ndescription: ruby\\nauthor: Nxeon Mod Builder\\n");
  w("src/main/java/dev/nxeon/plugins/ruby/Ruby.java", "package dev.nxeon.plugins.ruby;\\n\\nimport org.bukkit.NamespacedKey;\\nimport org.bukkit.plugin.java.JavaPlugin;\\n\\npublic class Ruby extends JavaPlugin {\\n  static final NamespacedKey MODEL = new NamespacedKey(\\"" + ns + "\\", \\"ruby_sword\\");\\n}\\n");
  w("modbuilder.json", JSON.stringify({ name: "Ruby", version: "1.0.0", tagline: "A ruby sword", summary: "Adds a ruby sword.", howToUse: ["Accept the resource pack"] }));
  w(SPEC, /BADTEXTURE/.test(prompt) ? GOOD.replace('"c": "r1"', '"c": "nope"') : /UGLYTEXTURE/.test(prompt) ? UGLY : GOOD);
} else if (/Build this Paper/.test(prompt) && /SOUNDBUILD/.test(prompt)) {
  const ns = (prompt.match(/reserved namespace is (nx_[a-z0-9]{8})/) || [])[1] || "nx_ab12cd34";
  const keys = ["ambient", "hurt", "death"].map((e) => '"' + ns + ':banshee.' + e + '"').join(", ");
  w("src/main/resources/plugin.yml", "name: Banshee\\nversion: 1.0.0\\nmain: dev.nxeon.plugins.banshee.Banshee\\napi-version: '1.21.11'\\ndescription: b\\nauthor: Nxeon Mod Builder\\n");
  w("src/main/java/dev/nxeon/plugins/banshee/Banshee.java", "package dev.nxeon.plugins.banshee;\\n\\nimport org.bukkit.plugin.java.JavaPlugin;\\n\\npublic class Banshee extends JavaPlugin {\\n  static final String[] KEYS = { " + keys + " };\\n}\\n");
  w("modbuilder.json", JSON.stringify({ name: "Banshee", version: "1.0.0", tagline: "A banshee", summary: "Adds a banshee.", howToUse: ["Accept the resource pack"] }));
  w(SND, /BADSOUND/.test(prompt) ? NOPRESET : /HUGESOUND/.test(prompt) ? NOPRESET.replace('Banshee fades away', 'Banshee fades away HUGE') : GOODSND);
  if (/LIBSOUND/.test(prompt)) w("assets/sounds/lib_try.json", JSON.stringify({ version: 1, name: "lib_try", events: [{ event: "boom", role: "death", subtitle: "Something explodes", variants: [{ layers: [{ source: "lib:" + (fs.readFileSync(path.join(process.cwd(), "sound-library/catalog.txt"), "utf8").match(/^(explosion_[a-z0-9_]+) /m) || [])[1], pitch: -5 }] }] }] }));
} else if (/Build this Paper/.test(prompt) && /WORLDGENBUILD/.test(prompt)) {
  w("src/main/resources/plugin.yml", "name: GlowRealm\\nversion: 1.0.0\\nmain: dev.nxeon.plugins.glowrealm.GlowRealm\\napi-version: '1.21.11'\\ndescription: g\\nauthor: Nxeon Mod Builder\\n");
  w("src/main/java/dev/nxeon/plugins/glowrealm/GlowRealm.java", "package dev.nxeon.plugins.glowrealm;\\n\\nimport org.bukkit.plugin.java.JavaPlugin;\\n\\npublic class GlowRealm extends JavaPlugin {\\n}\\n");
  w("modbuilder.json", JSON.stringify({ name: "GlowRealm", version: "1.0.0", tagline: "A glowing dimension", summary: "Adds the Glow Realm.", howToUse: ["Nxeon installs the data pack and restarts the server once", "Use /glow to travel there"], limitations: ["Only new chunks", "Reached by command"] }));
  w(WGF, GOODWG);
} else if (/Build this Paper/.test(prompt) && /DATAPACKBUILD/.test(prompt)) {
  w("src/main/resources/plugin.yml", "name: RubyLoot\\nversion: 1.0.0\\nmain: dev.nxeon.plugins.rubyloot.RubyLoot\\napi-version: '1.21.11'\\ndescription: r\\nauthor: Nxeon Mod Builder\\n");
