// Cyrus STARTER BANK: the portal's view of the prebuilt, Nxeon-authored mods in services/modbuilder/bank (ids, what prompts
// they answer, which numbers in the prompt become which settings). Client-safe data, no I/O. test/cyrus-bank.test.ts keeps it in
// line with the service's entry.json + schema.json files (ids, versions, param keys and crash-safe bounds).
//
// Content rule (D-60 / D-61): every entry is ours (written from our golden plugins). Nothing here is, or is derived from, a
// user's build: this is NOT the cross-user MB_DEDUPE reuse (which stays off).

export type BankParam = { key: string; int?: boolean; hardMin?: number; hardMax?: number };
/** One number of a canonical prompt: the settings it fills, or null when the number is fixed (it must stay the same). */
export type NumberSlot = readonly string[] | null;

export type BankEntry = {
  id: string;
  version: number;
  title: string;
  /** Plain words for the plan screen. */
  summary: string;
  /** Coach archetype ids (lib/cyrus/coach/archetypes.ts) this entry answers. */
  archetypes: readonly string[];
  /** House starter templates (lib/cyrus/templates.ts) whose prompt this entry implements completely. */
  templateIds: readonly string[];
  /** Other canonical prompts it implements completely (e.g. a "Need an idea?" example). */
  prompts: readonly string[];
  /** Per number in each canonical prompt (in order): the settings it sets, or null = fixed. One array per prompt; templates first. */
  numbers?: readonly (readonly NumberSlot[])[];
  /** Whole-prompt patterns (anchored) that ask for exactly this mod and nothing else; groups -> `strictParams`. */
  strict?: readonly RegExp[];
  strictParams?: (m: RegExpMatchArray) => Record<string, number | string | boolean> | null;
  /** The settings a request may set, with their crash-safe bounds (mirrors schema.json). */
  params: readonly BankParam[];
  /** Offered (opt-in, never automatic) for a short prompt of the same archetype. */
  offer?: boolean;
  mcVersions: readonly string[];
};

const V = ["1.21.1", "1.21.4", "1.21.8", "1.21.11"] as const;
const int = (key: string, hardMin: number, hardMax: number): BankParam => ({ key, int: true, hardMin, hardMax });
const numP = (key: string, hardMin: number, hardMax: number): BankParam => ({ key, hardMin, hardMax });
const text = (key: string): BankParam => ({ key });

export const BANK_ENTRIES: readonly BankEntry[] = [
  { id: "heal-feed", version: 1, title: "Heal & feed", summary: "/heal and /feed with a per-player cooldown in the action bar; operators target other players.",
    archetypes: ["utility_commands"], templateIds: ["heal"], prompts: [], numbers: [[["heal-cooldown-seconds", "feed-cooldown-seconds"]]],
    strict: [/^(?:an? |the )?\/heal and \/feed(?: commands?)?(?: with (?:an? )?(?:per[- ]player )?cool ?downs?)?$/i],
    params: [int("heal-cooldown-seconds", 0, 2_000_000), int("feed-cooldown-seconds", 0, 2_000_000)], offer: true, mcVersions: V },
  { id: "welcome-titles", version: 1, title: "Welcome titles", summary: "Custom join and leave messages; first-time players get a big welcome title.",
    archetypes: ["join_leave"], templateIds: ["join"], prompts: [], params: [], mcVersions: V },
  { id: "lucky-drops", version: 1, title: "Lucky mob drops", summary: "Zombies sometimes drop emeralds, skeletons extra arrows, creepers TNT; all tunable.",
    archetypes: ["loot"], templateIds: ["drops"], prompts: [], numbers: [[["drops.zombie.chance"]]], params: [numP("drops.zombie.chance", 0, 100)], mcVersions: V },
  { id: "spawn-home", version: 1, title: "Spawn & homes", summary: "/spawn, one saved home per player, and /discord /rules /website messages.",
    archetypes: ["tpa_spawn"], templateIds: ["spawn"], prompts: [], params: [], mcVersions: V },
  { id: "tpa", version: 1, title: "Teleport requests", summary: "/tpa, /tpaccept, /tpdeny, /tpcancel with expiry, a movement-cancel countdown and a cooldown.",
    archetypes: ["tpa_spawn"], templateIds: ["tpa"], prompts: [], numbers: [[["request-expire-seconds"], ["countdown-seconds"], ["cooldown-seconds"]]],
    strict: [/^(?:an? )?\/?tpa(?: system| plugin| mod)?(?: with \/tpaccept(?:,? and \/tpdeny)?)?$/i, /^(?:player )?teleport requests?(?: with \/tpa)?$/i],
    params: [int("request-expire-seconds", 1, 86400), int("countdown-seconds", 0, 600), int("cooldown-seconds", 0, 86400)], mcVersions: V },
  { id: "rules-accept", version: 1, title: "Rules on first join", summary: "New players get a rules book and cannot walk until they type /accept.",
    archetypes: ["books_guides", "login_gate"], templateIds: ["rules-book"], prompts: [], params: [], mcVersions: V },
  { id: "announcer", version: 1, title: "Announcements & restart warnings", summary: "Rotating broadcasts plus a /restartin countdown that stops the server.",
    archetypes: ["announcer"], templateIds: ["announcer"], prompts: [], numbers: [[null, null, null, null]], params: [], mcVersions: V },
  { id: "vein-miner", version: 1, title: "Vein miner", summary: "Sneak-mine an ore to break the whole connected vein (bounded, a few blocks per tick); /veinminer toggles it.",
    archetypes: ["vein_miner"], templateIds: ["vein-miner"], prompts: [],
    strict: [/^(?:an? )?vein ?miner(?: plugin| mod)?$/i], params: [], mcVersions: V },
  { id: "homes", version: 1, title: "Homes", summary: "Several named homes per player (3, more with VIP/MVP permissions), saved between restarts.",
    archetypes: ["homes"], templateIds: [],
    prompts: ["Homes: /sethome <name>, /home <name>, /delhome <name> and /homes. Every player can have 3 homes, more with permissions. Homes are saved between restarts."],
    numbers: [[["default-limit"]]],
    strict: [/^(?:an? )?(?:multiple |several |named )?homes?(?: system| plugin| mod)?(?: with \/sethome(?:,? and|,) \/home(?:,? and \/delhome)?)?$/i, /^\/sethome and \/home(?: commands?)?$/i],
    params: [int("default-limit", 0, 100000)], offer: true, mcVersions: V },
  { id: "warps", version: 1, title: "Warps", summary: "Operators create warps with /setwarp; players list and use them with /warp. Saved.",
    archetypes: ["warps"], templateIds: [], prompts: ["A /warp system: operators create warps with /setwarp <name>, players list and use them with /warp. Warps are saved."],
    strict: [/^(?:an? )?\/?warps?(?: system| plugin| mod)?(?: with \/setwarp and \/warp)?$/i], params: [], offer: true, mcVersions: V },
  { id: "kits", version: 1, title: "Kits", summary: "/kit starter (stone tools, bread, torches) once every 24 hours per player; /kits lists them.",
    archetypes: ["kits"], templateIds: [], prompts: ["A /kit starter command that gives stone tools, 16 bread and 16 torches once every 24 hours per player, and /kits to list the kits."],
    numbers: [[null, null, ["kits.starter.cooldown-hours"]]],
    strict: [/^(?:an? )?(?:starter )?kits?(?: system| plugin| mod)?$/i], params: [numP("kits.starter.cooldown-hours", 0, 100000)], offer: true, mcVersions: V },
  { id: "chat-format", version: 1, title: "Chat format", summary: "Prefix, name, arrow, message; staff and VIP prefixes by permission.",
    archetypes: ["chat_format"], templateIds: [], prompts: ["A chat format with rank prefixes: players with a VIP permission get a gold [VIP] prefix and staff get a red [Staff] prefix. The format is set in config.yml."],
    strict: [/^(?:an? )?(?:nicer |custom )?chat (?:format|formatting)(?: plugin| mod)?(?: with (?:rank )?prefixes)?$/i], params: [], offer: true, mcVersions: V },
  { id: "afk", version: 1, title: "AFK detection", summary: "Marks idle players AFK after 5 minutes and tells the server; /afk toggles; optional kick.",
    archetypes: ["afk"], templateIds: [], prompts: ["Mark players as AFK after 5 minutes without moving and tell the server. /afk toggles it."], numbers: [[["afk-after-minutes"]]],
    strict: [/^(?:an? )?afk (?:system|detection|plugin|mod|command)$/i, /^\/afk(?: command)?$/i], params: [int("afk-after-minutes", 1, 100000)], offer: true, mcVersions: V },
  { id: "keep-inventory", version: 1, title: "Keep inventory", summary: "Players keep their items and XP when they die (per permission, optional world list).",
    archetypes: ["graves"], templateIds: [], prompts: ["Players keep their inventory and XP when they die."],
    strict: [/^(?:(?:an? )?(?:plugin|mod)(?: that| to|:)? )?(?:make )?(?:players?|everyone) keeps? (?:their |all (?:their )?)?(?:items|inventory|inventories|stuff)(?: and (?:their )?(?:xp|exp|experience|levels))? (?:on death|when (?:they|players) die|after (?:death|dying))$/i, /^keep ?inventory(?: on death)?(?: for everyone)?$/i],
    params: [], mcVersions: V },
  { id: "first-join-kit", version: 1, title: "First-join kit", summary: "A stone sword, 8 bread and a welcome title on the first join, never again.",
    archetypes: ["join_leave", "kits"], templateIds: [], prompts: ["When a player first joins, give them a stone sword, 8 bread and a welcome title. Not again on later joins."], numbers: [[null]],
    params: [], mcVersions: V },
  { id: "custom-item", version: 1, title: "Custom weapon with stats", summary: "One named weapon with its own attack damage and speed, given with /giveitem.",
    archetypes: ["custom_weapons"], templateIds: [], prompts: [],
    strict: [/^(?:make |add |create )?(?:an? |one )?custom (sword|axe) (?:called|named) ['"]?([A-Za-z][A-Za-z0-9 '-]{0,30}?)['"]?,? (?:that |which )?(?:deals|does|with|hits for) (\d{1,3}(?:\.\d+)?) (?:attack )?damage$/i],
    strictParams: (m) => ({ "item.material": m[1].toLowerCase() === "axe" ? "DIAMOND_AXE" : "DIAMOND_SWORD", "item.name": m[2].trim(), "stats.attack-damage": Number(m[3]) }),
    params: [text("item.material"), text("item.name"), numP("stats.attack-damage", 0, 2048)], mcVersions: V },
];

export const BANK_BY_ID: Readonly<Record<string, BankEntry>> = Object.fromEntries(BANK_ENTRIES.map((e) => [e.id, e]));

