// Cyrus STARTER BANK matcher: deterministic, no model, client-safe. Decides whether a request is answered EXACTLY by a
// prebuilt bank entry (mode "instant": the plan screen offers the ready-made mod first, zero model tokens) or merely looks like
// one (mode "offer": the plan screen shows it as an opt-in alternative; never chosen for the user).
//
// "instant" needs one of:
//   1. the prompt IS a house starter template / canonical prompt of the entry, with only its numbers changed (each changed
//      number must map to a setting and stay inside the setting's crash-safe bounds; a fixed number must stay the same), or
//   2. the whole prompt matches one of the entry's anchored `strict` patterns (e.g. "keep inventory on death").
// Both are cross-checked with the coach archetype (lib/cyrus/coach/archetypes.ts) when the coach recognises anything: an
// archetype that is not one of the entry's is a veto. Anything unsafe-looking is never matched (unsafe eval set: 0 hits).
// A wrong instant answer is worse than none, so everything else falls back to the normal AI build.
import { matchArchetype } from "../coach/archetypes";
import { CYRUS_TEMPLATES } from "../templates";
import { BANK_ENTRIES, type BankEntry } from "./catalogue";

export type BankMatch = {
  id: string;
  version: number;
  title: string;
  summary: string;
  mode: "instant" | "offer";
  /** How it matched: template:<id> | prompt | strict | archetype:<id>. */
  via: string;
  /** Settings taken from the request (the rest keep the entry's defaults). */
  params: Record<string, number | string | boolean>;
};

/** Words that never belong in a ready-made answer (networking, code loading, data harvesting, hiding). */
export const BANK_DENY = /\b(https?:|www\.|webhook|discord\.com|ip ?address|\bips?\b|shell|command line|process ?builder|runtime\.exec|reflection|setaccessible|class ?loader|download|upload|backdoor|token|password|credential|obfuscat|hidden|secretly|quietly|without telling|crash|lag (?:the|machine)|exploit|\bop\b|deop|console command|nms|packets?)\b/i;
const OFFER_MAX_CHARS = 160;

export const normalizePrompt = (s: string): string => s.normalize("NFKC").replace(/[\u2018\u2019]/g, "'").replace(/[\u201c\u201d]/g, '"').replace(/\s+/g, " ").trim().replace(/[.!\s]+$/, "");

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const NUM = /\d+(?:\.\d+)?/g;

/** A canonical prompt as a pattern: same words (case and spacing free), every number a capture group. */
function promptPattern(canonical: string): { re: RegExp; numbers: number[] } {
  const c = normalizePrompt(canonical);
  const numbers = (c.match(NUM) ?? []).map(Number);
  const parts = c.split(NUM).map((p) => esc(p).replace(/ /g, "\\s+"));
  return { re: new RegExp(`^${parts.join("(\\d+(?:\\.\\d+)?)")}[.!]?$`, "i"), numbers };
}

function canonicalPrompts(e: BankEntry): { text: string; via: string }[] {
  const tpl = e.templateIds.map((id) => CYRUS_TEMPLATES.find((t) => t.id === id)).filter((t): t is NonNullable<typeof t> => !!t).map((t) => ({ text: t.prompt, via: `template:${t.id}` }));
  return [...tpl, ...e.prompts.map((p) => ({ text: p, via: "prompt" }))];
}

function paramsFromNumbers(e: BankEntry, idx: number, canonical: number[], got: number[]): Record<string, number> | null {
  const slots = e.numbers?.[idx] ?? canonical.map(() => null);
  const out: Record<string, number> = {};
  for (let i = 0; i < canonical.length; i++) {
    const keys = slots[i] ?? null;
    if (!keys) { if (got[i] !== canonical[i]) return null; continue; }
    for (const k of keys) {
      const p = e.params.find((x) => x.key === k);
      if (!p) return null;
      if (p.int && !Number.isInteger(got[i])) return null;
      if ((p.hardMin !== undefined && got[i] < p.hardMin) || (p.hardMax !== undefined && got[i] > p.hardMax)) return null;
      if (got[i] !== canonical[i]) out[k] = got[i];
    }
  }
  return out;
}

function paramsOk(e: BankEntry, params: Record<string, number | string | boolean>): boolean {
  for (const [k, v] of Object.entries(params)) {
    const p = e.params.find((x) => x.key === k);
    if (!p) return false;
    if (typeof v === "number" && ((p.hardMin !== undefined && v < p.hardMin) || (p.hardMax !== undefined && v > p.hardMax) || (p.int && !Number.isInteger(v)))) return false;
    if (typeof v === "string" && (v.length > 64 || /[<>{}\\]/.test(v))) return false;
  }
  return true;
}

/**
 * The bank answer for a FRESH request on a version, or null. `change` builds, unsafe-looking text and versions an entry is
 * not verified for never match.
 */
export function matchBank(text: string, opts: { mcVersion?: string; change?: boolean } = {}): BankMatch | null {
  if (opts.change) return null;
  const t = normalizePrompt(String(text ?? ""));
  if (t.length < 4 || t.length > 1200 || BANK_DENY.test(t)) return null;
  const arch = matchArchetype(t)?.id ?? null;
  const okVersion = (e: BankEntry) => !opts.mcVersion || e.mcVersions.includes(opts.mcVersion);
  const vetoed = (e: BankEntry) => !!arch && !e.archetypes.includes(arch);
  const hit = (e: BankEntry, via: string, params: Record<string, number | string | boolean>, mode: BankMatch["mode"]): BankMatch => ({ id: e.id, version: e.version, title: e.title, summary: e.summary, mode, via, params });
  // 1. canonical prompts (house templates first) with only their numbers changed
  for (const e of BANK_ENTRIES) {
    if (!okVersion(e)) continue;
    const list = canonicalPrompts(e);
    for (let i = 0; i < list.length; i++) {
      const { re, numbers } = promptPattern(list[i].text);
      const m = t.match(re);
      if (!m) continue;
      const params = paramsFromNumbers(e, i, numbers, m.slice(1).map(Number));
      if (params && !vetoed(e)) return hit(e, list[i].via, params, "instant");
    }
  }
  // 2. whole-prompt strict patterns
  for (const e of BANK_ENTRIES) {
    if (!okVersion(e) || !e.strict) continue;
    for (const re of e.strict) {
      const m = t.match(re);
      if (!m) continue;
      const params = e.strictParams ? e.strictParams(m) : {};
      if (params && paramsOk(e, params) && !vetoed(e)) return hit(e, "strict", params, "instant");
    }
  }
  // 3. an opt-in offer: a short request whose archetype has exactly one offerable entry
  if (arch && t.length <= OFFER_MAX_CHARS) {
    const cands = BANK_ENTRIES.filter((e) => e.offer && okVersion(e) && e.archetypes.includes(arch));
    if (cands.length === 1) return hit(cands[0], `archetype:${arch}`, {}, "offer");
  }
  return null;
}

