export const CYRUS_NOTES_MAX = 4000;
export const CYRUS_TITLE_MAX = 60;

/** Read whatever is in the column into a clean CyrusMeta (never throws). */
export function readCyrusMeta(raw: unknown): CyrusMeta {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  const r = raw as Record<string, unknown>;
  const out: CyrusMeta = {};
  if (isCyrusModel(r.model)) out.model = r.model;
  if (r.designer && typeof r.designer === "object" && !Array.isArray(r.designer)) {
    const d = r.designer as Record<string, unknown>;
    if (typeof d.revisionId === "string" && /^[A-Za-z0-9_-]{1,64}$/.test(d.revisionId) && Number.isInteger(d.seq)) out.designer = { revisionId: d.revisionId, seq: d.seq as number, configOnly: d.configOnly === true };
  }
  if (Array.isArray(r.attachments)) {
    out.attachments = r.attachments
      .filter((a): a is Record<string, unknown> => !!a && typeof a === "object")
      .map((a) => ({ n: Number(a.n) || 0, name: String(a.name ?? "image").slice(0, 120), type: String(a.type ?? ""), size: Number(a.size) || 0 }))
      .filter((a) => a.n > 0 && /^image\/(png|jpeg|webp|gif)$/.test(a.type))
      .slice(0, 8);
  }
  if (typeof r.title === "string" && r.title.trim()) out.title = r.title.trim().slice(0, CYRUS_TITLE_MAX);
  if (r.favourite === true) out.favourite = true;
  if (typeof r.notes === "string" && r.notes) out.notes = r.notes.slice(0, CYRUS_NOTES_MAX);
  if (typeof r.headBuildId === "string" && /^[A-Za-z0-9_-]{1,64}$/.test(r.headBuildId)) out.headBuildId = r.headBuildId;
  const cat = normalizeCategory(r.category);
  if (cat) {
    out.category = cat;
    const sec = cleanSecondary(r.secondaryCategories, cat);
    if (sec.length) out.secondaryCategories = sec;
    out.categorySource = r.categorySource === "owner" ? "owner" : "auto";
  }
  if (typeof r.description === "string" && r.description.trim()) out.description = cleanDescription(r.description).slice(0, LISTING_DESCRIPTION_MAX);
  if (isIconRef(r.icon)) out.icon = r.icon;
  if (typeof r.iconData === "string" && r.iconData.length <= LISTING_ICON_INLINE_MAX && ICON_DATA_RE.test(r.iconData)) out.iconData = r.iconData;
  if (r.assets && typeof r.assets === "object" && !Array.isArray(r.assets)) {
    const a = r.assets as Record<string, unknown>;
    const kinds = (v: unknown) => (Array.isArray(v) ? v.filter(isBuildAssetKind) : []);
    out.assets = {
      requested: kinds(a.requested), allowed: kinds(a.allowed),
      notices: (Array.isArray(a.notices) ? a.notices : []).filter((n): n is string => typeof n === "string").map((n) => n.slice(0, 400)).slice(0, 8),
      ...(typeof a.projectId === "string" && /^cp[0-9a-f]{20}$/.test(a.projectId) ? { projectId: a.projectId } : {}),
      ...(typeof a.namespace === "string" && /^nx_[a-z0-9]{8}$/.test(a.namespace) ? { namespace: a.namespace } : {}),
      ...(a.datapack && typeof a.datapack === "object" && !Array.isArray(a.datapack) ? { datapack: {
        route: (a.datapack as Record<string, unknown>).route === true,
        matched: (Array.isArray((a.datapack as Record<string, unknown>).matched) ? ((a.datapack as Record<string, unknown>).matched as unknown[]) : []).filter((x): x is string => typeof x === "string" && /^[a-z_]{1,40}$/.test(x)).slice(0, 10),
        limits: (Array.isArray((a.datapack as Record<string, unknown>).limits) ? ((a.datapack as Record<string, unknown>).limits as unknown[]) : []).filter((x): x is string => typeof x === "string").map((x) => x.slice(0, 300)).slice(0, 8),
        ...((a.datapack as Record<string, unknown>).worldgen === true ? { worldgen: true as const } : {}),
      } } : {}),
      ...(a.designer && typeof a.designer === "object" && !Array.isArray(a.designer) ? { designer: {
        route: (a.designer as Record<string, unknown>).route === true,
        matched: (Array.isArray((a.designer as Record<string, unknown>).matched) ? ((a.designer as Record<string, unknown>).matched as unknown[]) : []).filter((x): x is string => typeof x === "string" && /^[a-z]{1,10}:[a-z -]{1,40}$/.test(x)).slice(0, 10),
        limits: (Array.isArray((a.designer as Record<string, unknown>).limits) ? ((a.designer as Record<string, unknown>).limits as unknown[]) : []).filter((x): x is string => typeof x === "string").map((x) => x.slice(0, 300)).slice(0, 8),
        ...(((g) => (g && typeof g === "object" && !Array.isArray(g) ? { gameplay: { menus: (g as Record<string, unknown>).menus === true, quests: (g as Record<string, unknown>).quests === true } } : {}))((a.designer as Record<string, unknown>).gameplay)),
        ...((a.designer as Record<string, unknown>).bosses === true ? { bosses: true as const } : {}),
        ...((a.designer as Record<string, unknown>).hud === true ? { hud: true as const } : {}),
        ...((a.designer as Record<string, unknown>).motion === true ? { motion: true as const } : {}),
      } } : {}),
      ...(a.itemStates && typeof a.itemStates === "object" && !Array.isArray(a.itemStates) ? { itemStates: {
        route: (a.itemStates as Record<string, unknown>).route === true,
        matched: (Array.isArray((a.itemStates as Record<string, unknown>).matched) ? ((a.itemStates as Record<string, unknown>).matched as unknown[]) : []).filter((x): x is string => typeof x === "string" && /^state:[a-z -]{1,40}$/.test(x)).slice(0, 4),
      } } : {}),
      ...(a.planned && typeof a.planned === "object" && !Array.isArray(a.planned) ? { planned: {
        lanes: (Array.isArray((a.planned as Record<string, unknown>).lanes) ? ((a.planned as Record<string, unknown>).lanes as unknown[]) : []).filter((x): x is string => typeof x === "string" && /^[a-zA-Z0-9]{2,20}$/.test(x)).slice(0, 20),
        ...(((a.planned as Record<string, unknown>).source === "planner" || (a.planned as Record<string, unknown>).source === "rules") ? { source: (a.planned as Record<string, unknown>).source as "planner" | "rules" } : {}),
      } } : {}),
    };
  }
  // Cyrus R5: opaque server-written records, passed through unchanged (bounded) so round trips keep them.
  for (const k of ["engineRelease", "testFlight"] as const) {
    const v = r[k];
    if (v && typeof v === "object" && !Array.isArray(v) && JSON.stringify(v).length <= 64 * 1024) out[k] = v as JsonObject;
  }
  return out;
}

