// Cyrus STARTER BANK on the plan screen (pure, client-safe): what to show next to the AI estimate. "Ready-made (instant)" is only
// offered when the build service can serve the entry for this version; its price is the flat bank charge (a PLACEHOLDER setting,
// cyrus_tok_bank_charge) and it makes no model call. An "offer" is a look-alike: shown as an opt-in alternative, never pre-selected.
import { matchBank, type BankMatch } from "./match";

export type BankPlan = Pick<BankMatch, "id" | "version" | "title" | "summary" | "mode" | "via" | "params"> & {
  /** Tokens a ready-made build costs (null = tokens not active for this account). */
  tokens: number | null;
  /** Wall time: no model, only checks + compile (measured 5-25 s on the build host); Test Flight runs after, as for any build. */
  minutes: [number, number];
  /** Pre-select the ready-made option (instant matches only). */
  preselect: boolean;
  note: string;
};

export function bankOffer(text: string, mcVersion: string, o: { served: ReadonlyMap<string, readonly string[]>; tokens: number | null }): BankPlan | null {
  const m = matchBank(text, { mcVersion });
  if (!m) return null;
  const v = o.served.get(m.id);
  if (!v || (v.length && !v.includes(mcVersion))) return null;
  return {
    id: m.id, version: m.version, title: m.title, summary: m.summary, mode: m.mode, via: m.via, params: m.params,
    tokens: o.tokens, minutes: [0, 1], preselect: m.mode === "instant",
    note: m.mode === "instant"
      ? "Ready-made by Nxeon and already tested: built instantly with no AI. Change its settings in the Config Studio afterwards, or ask Cyrus for changes on top of it."
      : "A ready-made mod that looks close to what you asked. It may not do everything you described: read what it does before you pick it.",
  };
}
EOF
