// Cyrus STARTER BANK: the portal catalogue matches the service entries, the deterministic matcher is precise (no false "instant"
// on the eval sets, nothing at all on the unsafe set), every entry materializes into a workspace that passes the service's own
// settings check + pre-check + perf check (javac and Test Flight run on node-2: services/modbuilder/golden/bank-harness.js), and
// the request / token plumbing behaves.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { BANK_ENTRIES, BANK_BY_ID } from "../lib/cyrus/bank/catalogue";
import { matchBank, normalizePrompt } from "../lib/cyrus/bank/match";
import { bankOffer } from "../lib/cyrus/bank/plan";
import { bankOn } from "../lib/cyrus/bank/flag";
import { CYRUS_TEMPLATES, NEW_MOD_EXAMPLES } from "../lib/cyrus/templates";
import { parseTokenConfig, TOKEN_PLACEHOLDER_KEYS } from "../lib/cyrus/tokens/config-pure";
import { readCyrusMeta } from "../lib/cyrus/meta";

const ROOT = path.resolve(__dirname, "..");
const SVC = path.join(ROOT, "services/modbuilder");
// eslint-disable-next-line @typescript-eslint/no-require-imports
const BANK = require(path.join(SVC, "bank.js"));
// eslint-disable-next-line @typescript-eslint/no-require-imports
const { prepare } = require(path.join(SVC, "golden/bank-harness.js"));
const readJsonl = (f: string) => fs.readFileSync(f, "utf8").split("\n").filter((l) => l.trim()).map((l) => JSON.parse(l) as { key: string; prompt: string; must_refuse?: boolean; category?: string });
const EVAL = path.join(SVC, "eval");
const evalPrompts = () => [...readJsonl(path.join(EVAL, "prompts.jsonl")), ...fs.readdirSync(path.join(EVAL, "sets")).filter((f) => f.endsWith(".jsonl")).flatMap((f) => readJsonl(path.join(EVAL, "sets", f)))];

describe("starter bank: portal catalogue == service entries", () => {
  const svc = BANK.entries() as Map<string, { id: string; version: number; mcVersions: string[]; templateIds: string[]; dir: string }>;
  it("the service bank loads every entry without problems", () => {
    assert.deepEqual(BANK.loadEntries().problems, []);
    assert.ok(svc.size >= 15);
  });
  it("same ids, versions, versions verified and template ids", () => {
    assert.deepEqual([...svc.keys()].sort(), BANK_ENTRIES.map((e) => e.id).sort());
    for (const e of BANK_ENTRIES) {
      const s = svc.get(e.id)!;
      assert.equal(s.version, e.version, e.id);
      assert.deepEqual([...s.mcVersions], [...e.mcVersions], e.id);
      assert.deepEqual([...s.templateIds].sort(), [...e.templateIds].sort(), e.id);
      for (const t of e.templateIds) assert.ok(CYRUS_TEMPLATES.some((x) => x.id === t), `${e.id}: unknown template ${t}`);
    }
  });
  it("every portal param exists in the schema with the same crash-safe bounds", () => {
    for (const e of BANK_ENTRIES) {
