    assert.match(BANK.parseBankRequest({ id: "nope" }, "1.21.11").error, /no starter bank entry/);
    assert.match(BANK.parseBankRequest({ id: "homes" }, "26.1").error, /not verified/);
    assert.match(BANK.parseBankRequest({ id: "homes", params: { "x": 1 } }, "1.21.11").error, /no setting/);
    assert.match(BANK.parseBankRequest({ id: "homes", params: { "default-limit": 1.5 } }, "1.21.11").error, /whole number/);
    assert.match(BANK.parseBankRequest({ id: "homes", params: { "default-limit": 1e9 } }, "1.21.11").error, /safe bounds/);
