          assert.deepEqual(r.precheck.map((h: { rule: string; where: string }) => `${h.rule} ${h.where}`), [], `${id} ${v}`);
          assert.match(fs.readFileSync(path.join(ws, "src/main/resources/plugin.yml"), "utf8"), new RegExp(`api-version: '${v.replace(/\./g, "\\.")}'`));
          assert.ok(fs.existsSync(path.join(ws, "src/main/resources/config.yml")), "config.yml written from the schema");
        } finally { fs.rmSync(ws, { recursive: true, force: true }); }
      }
    }
  });
