    for (const id of BANK.entries().keys()) {
      for (const v of ["1.21.1", "1.21.11"]) {
        const ws = fs.mkdtempSync(path.join(os.tmpdir(), "bank-t-"));
        try {
          const r = prepare(id, v, {}, ws);
          assert.equal(r.problem, null, `${id} ${v}: ${JSON.stringify(r.problem)}`);
          assert.equal(r.config?.source, "declared", `${id} ${v} settings: ${JSON.stringify(r.config)}`);
          assert.deepEqual(r.precheck.map((h: { rule: string; where: string }) => `${h.rule} ${h.where}`), [], `${id} ${v}`);
