        } finally { fs.rmSync(ws, { recursive: true, force: true }); }
      }
    }
  });
  it("request params become the config.yml defaults (and the Config Studio schema)", () => {
    const ws = fs.mkdtempSync(path.join(os.tmpdir(), "bank-p-"));
    try {
      const r = prepare("heal-feed", "1.21.11", { "heal-cooldown-seconds": 45 }, ws);
      assert.equal(r.config.spec.params.find((p: { key: string }) => p.key === "heal-cooldown-seconds").default, 45);
      assert.match(fs.readFileSync(path.join(ws, "src/main/resources/config.yml"), "utf8"), /heal-cooldown-seconds: 45/);
    } finally { fs.rmSync(ws, { recursive: true, force: true }); }
  });
  it("the bank fingerprint changes with any entry file", () => {
    assert.match(BANK.bankVersion(), /^bank-[0-9a-f]{12}$/);
    assert.ok(BANK_BY_ID["vein-miner"]);
  });
});

