// Build service (offline, fake CLI + javac): the STARTER BANK serves a prebuilt entry with ZERO model calls through the real
// server.js checks, and RECIPE MEMORY injects a verified pattern into the first user turn only (the system prompt stays
// byte-identical, so the cached prefix is shared), records the pick, and honours the A/B holdback. Spends nothing.
import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { spawn, type ChildProcess } from "node:child_process";

const ROOT = path.resolve(__dirname, "..");
const SVC = path.join(ROOT, "services/modbuilder");
const KEY = "test-key-bank-0123456789";
// eslint-disable-next-line @typescript-eslint/no-require-imports
const RCP = require(path.join(SVC, "recipes.js"));
// eslint-disable-next-line @typescript-eslint/no-require-imports
const R = require(path.join(SVC, "route.js"));
// eslint-disable-next-line @typescript-eslint/no-require-imports
const P = require(path.join(SVC, "prompts.js"));

const FAKE_CLAUDE = `#!/usr/bin/env node
const fs = require("fs"), path = require("path"), crypto = require("crypto");
const a = process.argv.slice(2);
const prompt = a[a.indexOf("--") + 1] || "";
const sys = a[a.indexOf("--system-prompt") + 1] || "";
fs.appendFileSync(path.join(process.env.HOME, "claude.log"), JSON.stringify({ sys: crypto.createHash("sha256").update(sys).digest("hex"), recipe: /TESTED PATTERN/.test(prompt), titles: (prompt.match(/TESTED PATTERN[^:]*: ([^\\n]+)/g) || []) }) + "\\n");
const ws = process.cwd();
const w = (rel, t) => { fs.mkdirSync(path.dirname(path.join(ws, rel)), { recursive: true }); fs.writeFileSync(path.join(ws, rel), t); };
w("src/main/resources/plugin.yml", "name: Hello\\nversion: 1.0.0\\nmain: dev.nxeon.plugins.hello.Hello\\napi-version: '1.21.11'\\ndescription: h\\nauthor: Nxeon Mod Builder\\n");
w("src/main/java/dev/nxeon/plugins/hello/Hello.java", "package dev.nxeon.plugins.hello;\\n\\nimport org.bukkit.plugin.java.JavaPlugin;\\n\\npublic class Hello extends JavaPlugin {\\n}\\n");
w("modbuilder.json", JSON.stringify({ name: "Hello", version: "1.0.0", tagline: "hi", summary: "hi", howToUse: ["x"] }));
const out = (o) => process.stdout.write(JSON.stringify(o) + "\\n");
out({ type: "system", subtype: "init", model: "claude-sonnet-5-5" });
out({ type: "result", subtype: "success", is_error: false, num_turns: 2, total_cost_usd: 0.03, duration_ms: 900, duration_api_ms: 800, result: "Done.", usage: { input_tokens: 4, cache_creation_input_tokens: 100, cache_read_input_tokens: 100, output_tokens: 100 } });
`;
// one .class per source (the scan reads class files with javap, which prints nothing here)
const FAKE_JAVAC = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
const a = process.argv.slice(2);
const d = a[a.indexOf("-d") + 1];
fs.appendFileSync(path.join(process.env.HOME, "tools.log"), "javac\\n");
for (const f of a.filter((x) => x.endsWith(".java"))) { const m = f.match(/src\\/main\\/java\\/(.+)\\.java$/); if (!m) continue; fs.mkdirSync(path.join(d, path.dirname(m[1])), { recursive: true }); fs.writeFileSync(path.join(d, m[1] + ".class"), "x"); }
`;
const FAKE_JAR = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
const a = process.argv.slice(2); const file = a[a.indexOf("--file") + 1];
const out = {};
const add = (root, rel) => { const abs = path.join(root, rel); if (fs.statSync(abs).isDirectory()) { for (const n of fs.readdirSync(abs)) add(root, rel === "." ? n : rel + "/" + n); } else out[rel] = fs.readFileSync(abs).toString("base64"); };
for (let i = 0; i < a.length; i++) if (a[i] === "-C") { add(a[i + 1], a[i + 2]); i += 2; }
fs.writeFileSync(file, JSON.stringify(out));
`;
// nested-map YAML stand-in (the service's yaml dependency lives in its image): enough for plugin.yml round trips
const YAML_STUB = `const q = (v) => (typeof v === "string" && (/^[\\d.]+$/.test(v) || /[:#'"{}\\[\\],&*!|>%@\\\`]/.test(v) || v === "" || /^(true|false|null)$/i.test(v)) ? "'" + v.replace(/'/g, "''") + "'" : String(v));
module.exports = {
  parse(t) {
    const root = {}; const stack = [{ ind: -1, obj: root }];
    for (const l of String(t).split("\\n")) {
      if (!l.trim() || /^\\s*#/.test(l)) continue;
      const m = l.match(/^(\\s*)([\\w.-]+):\\s*(.*)$/); if (!m) continue;
      while (stack.length > 1 && stack[stack.length - 1].ind >= m[1].length) stack.pop();
      const parent = stack[stack.length - 1].obj;
      if (m[3] === "") { const o = {}; parent[m[2]] = o; stack.push({ ind: m[1].length, obj: o }); }
      else { const v = m[3].replace(/^'(.*)'$/, "$1").replace(/^"(.*)"$/, "$1"); parent[m[2]] = v === "true" ? true : v === "false" ? false : v; }
    }
    return root;
  },
  stringify(o) { const out = []; const go = (x, ind) => { for (const [k, v] of Object.entries(x)) { if (v && typeof v === "object") { out.push(" ".repeat(ind) + k + ":"); go(v, ind + 2); } else out.push(" ".repeat(ind) + k + ": " + q(v)); } }; go(o, 0); return out.join("\\n") + "\\n"; },
};
`;

let dir = "", proc: ChildProcess | null = null, port = 0, svcErr = "";
const log = () => fs.readFileSync(path.join(dir, "claude.log"), "utf8").trim().split("\n").filter(Boolean).map((l) => JSON.parse(l));
async function api(method: string, p: string, body?: unknown) {
  const r = await fetch(`http://127.0.0.1:${port}${p}`, { method, headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" }, body: body ? JSON.stringify(body) : undefined });
  return { status: r.status, json: await r.json() };
}
async function waitDone(id: string) {
  for (let i = 0; i < 300; i++) {
    const r = (await api("GET", `/builds/${id}`)).json;
    if (r.status === "succeeded" || r.status === "failed") return r;
    await new Promise((res) => setTimeout(res, 100));
  }
  throw new Error("build did not finish");
}
/** A build id that lands in (or out of) the holdback for a given percentage. */
const idFor = (pct: number, hold: boolean, prefix: string) => { for (let i = 0; i < 5000; i++) { const id = `${prefix}-${i}`; if (RCP.isHoldback(id, pct) === hold) return id; } throw new Error("no id"); };

describe("build service: starter bank + recipe memory (offline)", () => {
  before(async () => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), "mb-bank-"));
    const bin = path.join(dir, "bin");
    fs.mkdirSync(bin);
    for (const [n, t] of [["claude", FAKE_CLAUDE], ["javac", FAKE_JAVAC], ["jar", FAKE_JAR], ["javap", "#!/usr/bin/env node\n"]]) fs.writeFileSync(path.join(bin, n), t, { mode: 0o755 });
    const cp = path.join(dir, "cp");
    fs.mkdirSync(cp);
    fs.writeFileSync(path.join(cp, "1.21.11.txt"), "/nonexistent.jar\n");
    fs.writeFileSync(path.join(cp, "1.21.11.classes.txt"), "org/bukkit/plugin/java/JavaPlugin.class\n");
    fs.writeFileSync(path.join(dir, "claude.log"), "");
    const nodePath = path.join(dir, "node_modules");
    let yamlOk = true;
    try { require.resolve("yaml", { paths: [SVC] }); } catch { yamlOk = false; }
    if (!yamlOk) { fs.mkdirSync(path.join(nodePath, "yaml"), { recursive: true }); fs.writeFileSync(path.join(nodePath, "yaml", "index.js"), YAML_STUB); }
    port = 39000 + Math.floor(Math.random() * 2000);
    const child = spawn(process.execPath, [path.join(SVC, "server.js")], {
      env: {
        PATH: `${bin}:${process.env.PATH}`, HOME: dir, PORT: String(port), MB_DATA: path.join(dir, "data"), MB_WORK: path.join(dir, "work"),
        MB_TEMPLATE: path.join(SVC, "template"), MB_CP_DIR: cp, MODBUILDER_API_KEY: KEY, MB_VERSIONS: "1.21.11", MB_GUARD: "off", NODE_PATH: nodePath,
        MB_STARTER_BANK: "1", MB_RECIPES: "1", MB_RECIPES_HOLDBACK_PCT: "50",
      } as unknown as NodeJS.ProcessEnv,
      stdio: ["ignore", "ignore", "pipe"],
    });
    proc = child;
    child.stderr?.on("data", (d) => { svcErr += d; });
    for (let i = 0; i < 100; i++) {
      try { const h = await (await fetch(`http://127.0.0.1:${port}/health`)).json(); if (h.ok) return; } catch { /* starting */ }
      await new Promise((res) => setTimeout(res, 100));
    }
    throw new Error(`service did not start: ${svcErr.slice(-2000)}`);
  });
  after(() => { if (proc) proc.kill("SIGKILL"); fs.rmSync(dir, { recursive: true, force: true }); });

  it("/health lists the starter bank entries and the recipe memory", async () => {
    const h = await (await fetch(`http://127.0.0.1:${port}/health`)).json();
    assert.ok(h.features.starterBank.entries.some((e: { id: string }) => e.id === "heal-feed"));
    assert.match(h.features.starterBank.version, /^bank-/);
    assert.equal(h.features.recipes.holdbackPct, 50);
    assert.match(h.knowledge, /\+rcp-[0-9a-f]{12}$/, "the recipe version joins the knowledge version while on");
  });

  it("a bank build makes ZERO model calls and still runs validate, settings, javac and the scan", async () => {
    const before = log().length;
    const r0 = await api("POST", "/builds", { id: "bank-heal-01", prompt: "A /heal command ... (template)", mcVersion: "1.21.11", bank: { id: "heal-feed", params: { "heal-cooldown-seconds": 45 } } });
    assert.equal(r0.status, 202, JSON.stringify(r0.json));
    const r = await waitDone("bank-heal-01");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events) + svcErr.slice(-2000) + (r.errorDetail || ""));
    assert.equal(r.aiCalls.length, 0);
    assert.equal(log().length, before, "the CLI never ran");
    assert.equal(r.costUsd, 0);
    assert.equal(r.route.class, "bank");
    assert.equal(r.bank.id, "heal-feed");
    assert.equal(r.pluginName, "CyrusHealFeed");
    assert.equal(r.safety.verdict, "pass");
    assert.equal(r.assetResult.config.source, "declared");
    assert.equal(r.assetResult.config.spec.params.find((p: { key: string }) => p.key === "heal-cooldown-seconds").default, 45);
    assert.ok(r.usage.stages.bank, "bank stage timed");
    assert.ok(r.summary.limitations.some((l: string) => /ready-made Cyrus starter mod/.test(l)));
    const yml = await (await fetch(`http://127.0.0.1:${port}/builds/bank-heal-01/source?path=src/main/resources/config.yml`, { headers: { Authorization: `Bearer ${KEY}` } })).text();
    assert.match(yml, /heal-cooldown-seconds: 45/);
    assert.match(yml, /^perf:/m, "the perf watchdog settings were injected like any build");
  });

  it("bad bank requests are refused before anything runs", async () => {
    assert.equal((await api("POST", "/builds", { id: "bank-bad-01", prompt: "something long enough", mcVersion: "1.21.11", bank: { id: "nope" } })).status, 400);
    assert.equal((await api("POST", "/builds", { id: "bank-bad-02", prompt: "something long enough", mcVersion: "1.21.11", bank: { id: "homes", params: { "default-limit": -1 } } })).status, 400);
    assert.equal((await api("POST", "/builds", { id: "bank-bad-03", prompt: "something long enough", mcVersion: "1.21.11", bank: { id: "homes" }, assets: { texture: true, namespace: "nx_ab12cd34" } })).status, 400);
  });

  it("a matching fresh build gets the tested pattern in the USER turn; the system prompt is identical to a no-recipe build", async () => {
    const plain = idFor(50, false, "rcp-none");
    await api("POST", "/builds", { id: plain, prompt: "Say hello to every player who joins", mcVersion: "1.21.11" });
    const a = await waitDone(plain);
    assert.equal(a.status, "succeeded", JSON.stringify(a.events));
    assert.deepEqual(a.recipes.ids, []);
    const id = idFor(50, false, "rcp-in");
    await api("POST", "/builds", { id, prompt: "Homes: /sethome and /home teleport you back, cancelled if you move during a 3 second warmup. Homes are saved between restarts.", mcVersion: "1.21.11" });
    const b = await waitDone(id);
    assert.equal(b.status, "succeeded", JSON.stringify(b.events));
    assert.ok(b.recipes.ids.includes("safe-teleport"), JSON.stringify(b.recipes));
    assert.equal(b.recipes.injected, true);
    assert.equal(b.recipes.holdback, false);
    const calls = log();
    const [ca, cb] = [calls[calls.length - 2], calls[calls.length - 1]];
    assert.equal(ca.recipe, false);
    assert.equal(cb.recipe, true);
    assert.equal(ca.sys, cb.sys, "system prompt byte-identical: the cached prefix is shared");
    assert.ok(b.events.some((e: { message: string }) => /tested pattern/.test(e.message)));
  });

  it("the holdback build matches the same recipes but gets no injection (recorded for the A/B)", async () => {
    const id = idFor(50, true, "rcp-hold");
    await api("POST", "/builds", { id, prompt: "Homes: /sethome and /home teleport you back, cancelled if you move during a 3 second warmup. Homes are saved between restarts.", mcVersion: "1.21.11" });
    const r = await waitDone(id);
    assert.equal(r.status, "succeeded");
    assert.ok(r.recipes.ids.includes("safe-teleport"));
    assert.equal(r.recipes.holdback, true);
    assert.equal(r.recipes.injected, false);
    assert.equal(log()[log().length - 1].recipe, false);
  });
});

describe("recipe memory: selection, block, off = byte-identical", () => {
  const read = (id: string) => JSON.parse(fs.readFileSync(path.join(SVC, "recipes", `${id}.json`), "utf8"));
  it("every recipe file is well-formed, Nxeon-authored, and a verified one has a passing proof", () => {
    const results = JSON.parse(fs.readFileSync(path.join(SVC, "golden/results.json"), "utf8")) as { rows: { id: string; compile: Record<string, string>; scan: Record<string, string>; boot: Record<string, string> }[] };
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const BANK = require(path.join(SVC, "bank.js"));
    const rules = new Set((JSON.parse(fs.readFileSync(path.join(SVC, "rules/failure-rules.json"), "utf8")).rules as { id: string }[]).map((r) => r.id));
    const perfRules = new Set(["perf-unbounded-fanout", "perf-block-loop", "perf-spawn-in-loop", "perf-raw-timer"]);
    const list = RCP.loadRecipes();
    assert.ok(list.length >= 8);
    for (const r of list) {
      assert.match(r.id, /^[a-z][a-z0-9-]+$/);
      assert.equal(r.provenance.author, "nxeon");
      assert.equal(r.provenance.noUserCode, true);
      assert.ok(r.pattern.length <= 2400, `${r.id}: pattern over budget (${r.pattern.length})`);
      for (const p of r.pitfalls) assert.ok(rules.has(p.ruleId) || perfRules.has(p.ruleId), `${r.id}: unknown rule ${p.ruleId}`);
      for (const s of [...r.match, ...r.strong, ...r.not]) new RegExp(s, "i");
      if (r.status !== "verified") continue;
      assert.ok(r.proof.golden || r.proof.bank, `${r.id}: a verified recipe needs a golden or bank proof`);
      if (r.proof.golden) {
        const row = results.rows.find((x) => x.id === r.proof.golden);
        assert.ok(row, `${r.id}: golden ${r.proof.golden} has no results row`);
        for (const v of r.mcVersions) for (const st of ["compile", "scan", "boot"] as const) assert.equal(row![st][v], "pass", `${r.id}: ${r.proof.golden} ${st} ${v}`);
      }
      if (r.proof.bank) assert.ok(BANK.entries().has(r.proof.bank), `${r.id}: bank proof ${r.proof.bank}`);
    }
    assert.equal(read("mob-capture").status, "draft", "no flown proof yet: never injected");
  });
  it("selection: two rules or a strong rule; a guard archetype lifts a single weak hit; designer / change builds get none", () => {
    const sel = (t: string, o = {}) => RCP.selectRecipes(t, { mcVersion: "1.21.11", ...o }).ids;
    assert.ok(sel("A vein miner: sneak and mine an ore to break the connected blocks").includes("bounded-block-work"));
    assert.ok(sel("Combat tag: players who log out during pvp are killed").includes("combat-tag"));
    assert.deepEqual(sel("Say hello to every player who joins"), []);
    assert.deepEqual(sel("teleport"), [], "one weak word is not enough");
    assert.ok(sel("teleport", { guardArchetypes: ["tpa_spawn"] }).includes("safe-teleport"), "the guard's archetype confirms it");
    assert.deepEqual(sel("A vein miner that breaks connected blocks", { change: true }), []);
    assert.deepEqual(sel("A vein miner that breaks connected blocks", { assets: { design: true } }), []);
    assert.deepEqual(sel("A glowing custom sword called Ember with a texture"), [], "item-model-states needs the texture lane");
    assert.ok(sel("A custom sword called Ember with its own texture that glows", { assets: { texture: true } }).includes("item-model-states"));
    assert.deepEqual(sel("A custom sword called Ember with its own texture that glows", { assets: { texture: true }, mcVersion: "1.21.1" }).filter((x: string) => x === "item-model-states"), [], "1.21.1 has no item models");
    assert.ok(RCP.selectRecipes("x".repeat(10), {}).ids.length <= RCP.MAX_RECIPES);
  });
  it("selection precision over the eval set: no recipe for any refused prompt, at most two per prompt", () => {
    const sets = fs.readdirSync(path.join(SVC, "eval/sets")).flatMap((f) => fs.readFileSync(path.join(SVC, "eval/sets", f), "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l)));
    for (const p of sets) {
      const ids = RCP.selectRecipes(p.prompt, { mcVersion: "1.21.11" }).ids;
      assert.ok(ids.length <= 2);
      if (p.key === "cov-vein-miner") assert.ok(ids.includes("bounded-block-work"), "the vein miner coverage prompt gets the bounded-work recipe");
    }
  });
  it("holdback is deterministic per build id and follows the percentage", () => {
    const ids = Array.from({ length: 2000 }, (_, i) => `b${i}`);
    const share = ids.filter((id) => RCP.isHoldback(id, 20)).length / ids.length;
    assert.ok(share > 0.15 && share < 0.25, `holdback share ${share}`);
    assert.equal(RCP.isHoldback("abc", 20), RCP.isHoldback("abc", 20));
    assert.equal(RCP.isHoldback("abc", 0), false);
    assert.equal(RCP.isHoldback("abc", 100), true);
    assert.equal(RCP.holdbackPct({}), 20);
    assert.equal(RCP.holdbackPct({ MB_RECIPES_HOLDBACK_PCT: "250" }), 100);
  });
  it("the block is small and names the recipe, settings and pitfalls", () => {
    const b = RCP.recipeBlock(["safe-teleport"]);
    assert.match(b, /TESTED PATTERN for this kind of mod/);
    assert.match(b, /teleportAsync/);
    assert.match(b, /Known pitfalls/);
    assert.ok(b.length < RCP.MAX_BLOCK_CHARS + 10);
    assert.equal(RCP.recipeBlock([]), "");
  });
  it("off (default): nothing recorded, the user turn and the guard prompt are byte-identical", () => {
    const rec = { id: "x1", prompt: "Homes with /sethome and /home teleport, saved between restarts", mcVersion: "1.21.11", assets: null };
    assert.equal(RCP.forBuild(rec, {}, {}), null);
    assert.equal(P.initialPrompt({ ...rec, recipeText: "" }, "/ws", []), P.initialPrompt(rec, "/ws", []));
    assert.equal(R.guardPromptWithArchetypes([]), R.GUARD_PROMPT);
    assert.equal(createHash("sha256").update(R.GUARD_PROMPT).digest("hex").length, 64);
    assert.doesNotMatch(R.GUARD_PROMPT, /ARCHETYPES/);
  });
  it("guard archetypes: closed list only, at most two", () => {
    const p = R.guardPromptWithArchetypes(RCP.guardArchetypes());
    assert.match(p, /Line 2 \(only after ALLOW\): ARCHETYPES/);
    assert.deepEqual(R.parseGuardArchetypes("ALLOW standard\nARCHETYPES: homes, made_up, warps, kits", ["homes", "warps", "kits"]), ["homes", "warps"]);
    assert.deepEqual(R.parseGuardArchetypes("ALLOW simple", ["homes"]), []);
    assert.deepEqual(R.parseGuard("ALLOW standard\nARCHETYPES: homes"), { verdict: "allow", class: "standard" });
  });
});

