// Nothing here reads file contents or user text: see types.ts for the privacy line.
import { diffSurface, surfaceOfResult } from "./surface";
import type { BuildRow, BuildSignals, CallKind, CallSummary, LearningOptions, ModelFamily, Outcome, Surface } from "./types";

export const REWORK_MINUTES = 30;
/** D-03: 1 Cyrus token = $0.002 of real cost. */
export const USD_PER_TOKEN = 0.002;

const rec = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
const arr = (v: unknown): unknown[] => (Array.isArray(v) ? v : []);
const num = (v: unknown): number => (typeof v === "number" && Number.isFinite(v) ? v : 0);
const str = (v: unknown): string | null => (typeof v === "string" && v ? v : null);
const ms = (v: Date | string | number | null | undefined): number | null => {
  if (v == null) return null;
  const t = v instanceof Date ? v.getTime() : typeof v === "number" ? v : Date.parse(v);
  return Number.isFinite(t) ? t : null;
};

export function familyOf(model: string | null | undefined): ModelFamily | null {
  const m = String(model || "").toLowerCase();
  if (!m) return null;
  return m.includes("haiku") ? "haiku" : m.includes("sonnet") ? "sonnet" : m.includes("opus") ? "opus" : "other";
}

const KINDS: CallKind[] = ["guard", "generate", "change", "repair", "repair-asset"];
  for (const c of calls) {
    const t = rec(rec(c).tokens);
    if (!Object.keys(t).length) continue;
    any = true;
    u.input += num(t.uncached ?? t.input); u.cacheWrite += num(t.cacheWrite); u.cacheRead += num(t.cacheRead); u.output += num(t.output);
    u.toolCalls += Object.values(rec(rec(c).toolCalls)).reduce<number>((a, b) => a + num(b), 0);
  }
  return any ? u : null;
}

function promptBucket(row: BuildRow): BuildSignals["promptBucket"] {
  const n = String(row.changeRequest || row.prompt || "").length;
  return n === 0 ? "none" : n < 80 ? "short" : n < 300 ? "medium" : "long";
}

function eventsOf(result: Record<string, unknown>): BuildSignals["events"] {
  const ev = arr(result.events).map(rec);
  const out: BuildSignals["events"] = { reads: 0, writes: 0, edits: 0, seqWrites: 0, autofixes: 0, apiLookups: 0, stageMs: {} };
  ev.forEach((e, i) => {
    const m = String(e.message ?? "");
    if (/^Reading /.test(m) && !/^Reading your existing/.test(m)) out.reads++;
    else if (/^(Wrote|Edited) /.test(m)) {
      if (m.startsWith("Wrote")) out.writes++; else out.edits++;
      const prev = i > 0 ? ms(ev[i - 1].at as string) : null, cur = ms(e.at as string);
      if (prev != null && cur != null && cur - prev >= 2000) out.seqWrites++;
    }
    else if (/Fixing it automatically/.test(m)) out.autofixes++;
    else if (/^API lookup/.test(m)) out.apiLookups++;
    const t0 = ms(e.at as string), t1 = i + 1 < ev.length ? ms(ev[i + 1].at as string) : null;
    if (t0 != null && t1 != null && t1 >= t0) { const st = String(e.stage ?? "other"); out.stageMs[st] = (out.stageMs[st] ?? 0) + (t1 - t0); }
  });
  return out;
}

type Pre = { row: BuildRow; sig: BuildSignals; surface: Surface };

function pre(row: BuildRow, opts: LearningOptions): Pre {
  const result = rec(row.result);
  const cyrus = rec(row.cyrus);
  const calls = arr(rec(result.ai).calls);
  const callsByKind: Partial<Record<CallKind, CallSummary>> = {};
  const callsByFamilyKind: Record<string, CallSummary> = {};
  let turns = 0;
  for (const c of calls) {
    const k = kindOf(rec(c).kind);
    const s = (callsByKind[k] ??= { n: 0, turns: 0, costUsd: 0, durationMs: 0 });
    s.n++; s.turns += num(rec(c).turns); s.costUsd += num(rec(c).costUsd); s.durationMs += num(rec(c).durationMs);
    const fk = `${familyOf(str(rec(c).resolvedModel) ?? str(rec(c).model)) ?? "unknown"}/${k}`;
    const f = (callsByFamilyKind[fk] ??= { n: 0, turns: 0, costUsd: 0, durationMs: 0 });
    f.n++; f.turns += num(rec(c).turns); f.costUsd += num(rec(c).costUsd); f.durationMs += num(rec(c).durationMs);
    if (k !== "guard") turns += num(rec(c).turns);
  }
  const main = calls.find((c) => ["generate", "change"].includes(String(rec(c).kind))) ?? calls.find((c) => rec(c).kind !== "guard");
  const tier = str(cyrus.model) ?? str(rec(main).route) ?? str(rec(result.ai).route);
  const planned = rec(rec(cyrus.assets).planned);
  const lanes = arr(planned.lanes).map(String).sort();
  const created = ms(row.createdAt) ?? 0;
  const dur = num(row.durationMs);
  const ended = ms(row.finishedAt) ?? (created + dur);
  const costUsd = num(row.costUsd);
  const code = str(row.errorCode);
  const outcome = outcomeOf(row.status, code);
  const refused = outcome === "refused";
  const surface = opts.surfaces?.[row.id] ?? surfaceOfResult(row.result);
  const sig: BuildSignals = {
    id: row.id,
    rootId: row.rootBuildId || row.id,
    baseId: row.baseBuildId || null,
    createdAtMs: created,
    endedAtMs: ended,
    kind: row.baseBuildId ? "change" : "fresh",
    status: row.status,
    outcome,
    tier,
    family: familyOf(str(rec(main).resolvedModel) ?? str(rec(main).model)),
    route: str(rec(result.ai).route),
    routeMethod: str(rec(result.ai).routeMethod),
    lanes,
    laneKey: lanes.length ? lanes.join("+") : "plain",
    promptBucket: promptBucket(row),
    mcVersion: row.mcVersion ?? null,
    attempts: num(row.attempts),
    repairs: num(result.repairs),
    costUsd,
    durationMs: dur,
    turns,
    tokensEst: Math.round(costUsd / USD_PER_TOKEN),
    callsByKind,
    callsByFamilyKind,
    usage: usageOf(calls),
    events: eventsOf(result),
    guardRefusal: refused,
    guardReason: refused ? (/guard:([a-z_-]+)/i.exec(String(rec(result).errorDetail ?? ""))?.[1] ?? null) : null,
    interrupted: outcome === "interrupted",
    unavailable: outcome === "unavailable",
    testFlight: testFlightOf(cyrus),
    install: installOf(row),
    rework: { reworked: false, byId: null, gapMin: null, via: null, wastedUsd: 0 },
    retry: { retried: false, byId: null, gapMin: null },
    regression: null,
    goodBaseId: null,
    regressionVsGood: null,
    kept: false,
  };
  return { row, sig, surface };
}

