// Cyrus LEARNING LOOP: PATH MEMORY (design: agent-notes BL-recipe-memory-design.md section 5). Which prompt SHAPE (coach archetype
// + lanes + fresh/change + complexity bucket) went down which PATH (tier, model family, effort, recipe / starter bank) and how
// cheaply it succeeded. Built from anonymized outcome signals only (ids, buckets, counts, cost; D-60 / D-61): no request text,
// names or code. Pure.
//
// It changes nothing by itself: `recommendations` are SUGGESTIONS (plan-screen estimate, default tier / effort hint, recipe A/B
// bookkeeping) and `pathCandidates` turn them into review-queue items (mining.ts kinds routing-hint / recipe-gap / recipe-pitfall
// / bank-gap). Accepting one means a person ships it as a normal, eval-gated engine release.
import type { BuildSignals } from "./types";
import { candidateId, type Candidate } from "./mining";

export const PATH_MIN_N = 8;
export const PATH_MIN_OPTION = 5;

export type Quantiles = { p25: number; p50: number; p90: number };
export type PathStats = { n: number; succeeded: number; kept: number; successRate: number; keptRate: number; costUsd: Quantiles; costPerKept: number | null; turnsP50: number; repairsP50: number; reworkedLast5: number };
export type ShapeKey = { archetype: string; laneKey: string; kind: "fresh" | "change"; complexity: string };
export type PathKey = { tier: string; family: string; effort: string; path: "bank" | "recipe" | "holdback" | "plain" };
export type PathCell = { shape: ShapeKey; path: PathKey; stats: PathStats };
export type RecipeEffect = { recipeId: string; with: PathStats | null; without: PathStats | null; ratio: number | null; n: number };
export type Recommendation = {
  shape: ShapeKey;
  n: number;
  /** Shown / used only with n >= PATH_MIN_N for the shape. */
  usable: boolean;
  best: PathKey | null;
  bestStats: PathStats | null;
  /** The current most common path, to compare against. */
  current: PathKey | null;
  currentStats: PathStats | null;
  /** best vs current, cost per kept success (lower is better). */
  savingPct: number | null;
  estimate: { typicalUsd: number; upToUsd: number } | null;
};

const q = (xs: number[], p: number) => { if (!xs.length) return 0; const s = [...xs].sort((a, b) => a - b); const i = Math.min(s.length - 1, Math.max(0, Math.ceil(p * s.length) - 1)); return s[i]; };
const r3 = (n: number) => Math.round(n * 1000) / 1000;
const shapeKeyOf = (s: BuildSignals): ShapeKey => ({ archetype: s.archetype ?? "unknown", laneKey: s.laneKey, kind: s.kind, complexity: s.complexity ?? "unknown" });
export const pathOf = (s: BuildSignals): PathKey => ({
  tier: s.tier ?? "unknown", family: s.family ?? "none", effort: s.effort ?? "default",
  path: s.bankId ? "bank" : s.recipes?.injected ? "recipe" : s.recipes?.holdback ? "holdback" : "plain",
});
const k = (o: object) => JSON.stringify(o);

/** Stats of a group of builds in time order (the last five decide the rework demotion). */
export function statsOf(list: BuildSignals[]): PathStats {
