  const ordered = [...done].sort((a, b) => a.createdAtMs - b.createdAtMs);
  const succeeded = done.filter((s) => s.outcome === "success").length;
  const kept = done.filter((s) => s.kept).length;
  const cost = done.map((s) => s.costUsd);
  const total = cost.reduce((a, b) => a + b, 0);
  return {
    n: done.length, succeeded, kept,
    successRate: done.length ? r3(succeeded / done.length) : 0,
    keptRate: done.length ? r3(kept / done.length) : 0,
    costUsd: { p25: r3(q(cost, 0.25)), p50: r3(q(cost, 0.5)), p90: r3(q(cost, 0.9)) },
    costPerKept: kept ? r3(total / kept) : null,
