export function buildPathMemory(sigs: BuildSignals[]): { cells: PathCell[]; recommendations: Recommendation[]; recipeEffects: RecipeEffect[] } {
  const byShape = new Map<string, { shape: ShapeKey; list: BuildSignals[] }>();
  for (const s of sigs) {
    const shape = shapeKeyOf(s);
    const g = byShape.get(k(shape)) ?? byShape.set(k(shape), { shape, list: [] }).get(k(shape))!;
    g.list.push(s);
  }
  const cells: PathCell[] = [];
  const recommendations: Recommendation[] = [];
  for (const { shape, list } of byShape.values()) {
    const byPath = new Map<string, { path: PathKey; list: BuildSignals[] }>();
    for (const s of list) { const p = pathOf(s); (byPath.get(k(p)) ?? byPath.set(k(p), { path: p, list: [] }).get(k(p))!).list.push(s); }
    const opts = [...byPath.values()].map((x) => ({ path: x.path, stats: statsOf(x.list) }));
