    const eligible = opts.filter((o) => o.stats.n >= PATH_MIN_OPTION && o.stats.reworkedLast5 === 0);
    eligible.sort((a, b) => b.stats.keptRate - a.stats.keptRate || a.stats.costUsd.p50 - b.stats.costUsd.p50);
    const current = [...opts].sort((a, b) => b.stats.n - a.stats.n)[0] ?? null;
    const best = eligible[0] ?? null;
    const saving = best && current && best.stats.costPerKept !== null && current.stats.costPerKept ? r3(1 - best.stats.costPerKept / current.stats.costPerKept) : null;
    const usable = all.n >= PATH_MIN_N;
