  const ids = [...new Set(sigs.flatMap((s) => s.recipes?.ids ?? []))].sort();
  const recipeEffects: RecipeEffect[] = ids.map((id) => {
    const w = sigs.filter((s) => s.recipes?.ids.includes(id) && s.recipes.injected);
    const wo = sigs.filter((s) => s.recipes?.ids.includes(id) && s.recipes.holdback);
    const a = w.length ? statsOf(w) : null, b = wo.length ? statsOf(wo) : null;
    return { recipeId: id, with: a, without: b, n: w.length + wo.length, ratio: a?.costPerKept != null && b?.costPerKept ? r3(a.costPerKept / b.costPerKept) : null };
  });
  recommendations.sort((a, b) => b.n - a.n || k(a.shape).localeCompare(k(b.shape)));
