    if (!r.usable || !r.best || !r.current || k(r.best) === k(r.current) || r.savingPct === null || r.savingPct < 0.15) continue;
    if ((r.bestStats?.keptRate ?? 0) < (r.currentStats?.keptRate ?? 0)) continue;
    out.push(make("routing-hint", `Default path for ${shapeText(r.shape)}: ${pathText(r.best)}`, evidenceFor(r.shape, r.best),
      JSON.stringify({ shape: r.shape, from: r.current, to: r.best, keptRate: [r.currentStats?.keptRate, r.bestStats?.keptRate], costPerKept: [r.currentStats?.costPerKept, r.bestStats?.costPerKept] }),
      0.3 + Math.min(0.4, r.n / 50) + Math.min(0.2, r.savingPct), `${r.n} builds of this shape; the ${pathText(r.best)} path kept ${r.bestStats?.keptRate} at $${r.bestStats?.costPerKept} per kept success against ${r.currentStats?.keptRate} at $${r.currentStats?.costPerKept} on the usual path (${Math.round(r.savingPct * 100)}% cheaper per kept success).`, "path-memory"));
  }
