    const st = statsOf(list);
    if (st.n < 3) continue;
    if (!recipeArch.has(arch) && (st.costUsd.p50 > allFresh.costUsd.p50 || st.repairsP50 >= 1)) out.push(make("recipe-gap", `Write a recipe for ${arch}`, list.map((s) => s.id),
      `Author a verified recipe (services/modbuilder/recipes/<id>.json) for archetype ${arch} from our own golden plugin, with proof (golden compile + scan + flight rows) before status verified.`,
      0.25 + Math.min(0.4, st.n / 20) + (st.repairsP50 >= 1 ? 0.15 : 0), `${st.n} fresh builds: p50 $${st.costUsd.p50} (all fresh $${allFresh.costUsd.p50}), p50 repairs ${st.repairsP50}, kept ${st.keptRate}.`, "path-memory"));
