      `Add a Nxeon-authored bank entry (services/modbuilder/bank/<id>) for the common simple ${arch} request, verified by golden/bank-harness.js on every version + Test Flight, and its strict pattern in lib/cyrus/bank/catalogue.ts.`,
      0.2 + Math.min(0.5, simple.length / 20), `${simple.length} simple plain ${arch} builds cost $${statsOf(simple).costUsd.p50} each at p50.`, "path-memory"));
  }
  // recipe pitfalls: injected builds of a recipe that still needed repairs (the error text is not stored: a person reads the logs)
  for (const e of pm.recipeEffects) {
    const w = sigs.filter((s) => s.recipes?.injected && s.recipes.ids.includes(e.recipeId));
    const rep = w.filter((s) => s.repairs >= 1);
    if (rep.length >= 3) out.push(make("recipe-pitfall", `Recipe ${e.recipeId}: builds still need repairs`, rep.map((s) => s.id),
      `Read the repair events of these builds; when one failure shape recurs, add it to the recipe's pitfalls (and a failure rule) in a reviewed branch.`,
      0.25 + Math.min(0.4, rep.length / 10), `${rep.length} of ${w.length} builds with the recipe injected needed at least one repair${e.ratio !== null ? `; cost per kept success with/without the recipe: ratio ${e.ratio}` : ""}.`, "recipe-ab"));
  }
  return out.sort((a, b) => b.confidence - a.confidence || a.id.localeCompare(b.id));
}

