import fs from "node:fs";
import path from "node:path";
import type { Candidate } from "./mining";

export const REVIEW_DECISIONS = ["accepted", "rejected", "reopened"] as const;
export type ReviewDecision = (typeof REVIEW_DECISIONS)[number];
export type Review = { candidateId: string; decision: ReviewDecision; by: string; at: string; note: string };
export type ReviewState = { status: "candidate" | "accepted" | "rejected"; last: Review | null; history: Review[] };

export const REVIEWS_FILE = "reviews.jsonl";
const ID_RE = /^[0-9a-f]{12}$/;

/** Validate one decision from a form (null + reason when it is not acceptable). */
export function parseReview(i: { candidateId: unknown; decision: unknown; by: unknown; note?: unknown }, now = new Date()): { ok: true; review: Review } | { ok: false; error: string } {
  const id = String(i.candidateId ?? "");
  if (!ID_RE.test(id)) return { ok: false, error: "Not a candidate id." };
  const decision = String(i.decision ?? "") as ReviewDecision;
  if (!(REVIEW_DECISIONS as readonly string[]).includes(decision)) return { ok: false, error: "Pick accept, reject or reopen." };
  const by = String(i.by ?? "").slice(0, 64);
  if (!by) return { ok: false, error: "No reviewer." };
  const note = String(i.note ?? "").replace(/[\u0000-\u001f]/g, " ").trim().slice(0, 300);
  if (decision === "rejected" && note.length < 3) return { ok: false, error: "Say in a few words why it is rejected (it helps the next review)." };
  return { ok: true, review: { candidateId: id, decision, by, at: now.toISOString(), note } };
}

/** Fold the append-only log into the current state per candidate (the last decision wins; "reopened" = back to candidate). */
export function foldReviews(reviews: Review[]): Map<string, ReviewState> {
  const out = new Map<string, ReviewState>();
  for (const r of [...reviews].sort((a, b) => a.at.localeCompare(b.at))) {
