  try { return parseReviewsJsonl(fs.readFileSync(path.join(dir, REVIEWS_FILE), "utf8")); } catch { return []; }
}
export function appendReview(dir: string, r: Review): void {
  fs.mkdirSync(dir, { recursive: true });
