// Cyrus EVAL GATE runner (lib/cyrus/eval/gate.ts): 20 fixed prompts, compared with the accepted baseline and the last accepted
// gate run, verdict per lane. Run from a repo checkout (never /opt/nxeon).
//
//   npx tsx scripts/cyrus/eval-gate.ts --dry-run                                     the plan + cost estimate, submits nothing
//   npx tsx scripts/cyrus/eval-gate.ts --journal /root/cyrus-eval/first1 --tag rec1  re-score a RECORDED journal (no spend)
//   npx tsx scripts/cyrus/eval-gate.ts --tag gate-0-12 --budget 8 --testflight       a real, budgeted run (PAID; owner only)
// Options: --baseline FILE (default services/modbuilder/eval/baseline.json), --accepted FILE (default
// services/modbuilder/eval/gate-accepted.json), --out DIR (default /root/cyrus-eval), --image modbuilder:X.Y (whose verdict it is),
// --record-release (write the verdict onto that image's engine release in services/modbuilder/eval/engine-releases.json),
// --accept (make this run the new "last accepted gate run"; an owner decision), --json.
// Writes <out>/<tag>/gate.json + gate.md. Exit code: 0 pass / no-reference, 1 warn, 3 fail, 2 usage error.
// deploy-modbuilder.sh (REQUIRE_EVAL_GATE=yes) refuses an image whose recorded verdict is not "pass"; the weekly job
// (scripts/cyrus/eval-gate-weekly.sh) re-runs the gate on the live image.
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { GATE_JOBS, GATE_KEYS, GATE_VERSIONS, gateVerdict, rowsFromJournal, rowsFromReference, verdictMarkdown, type GateRow, type GateVerdict } from "../../lib/cyrus/eval/gate";
import { createManifest, recordImageVerdict, type ManifestComponents, type ReleaseManifest } from "../../lib/cyrus/learning/release-manifest";

const ROOT = path.resolve(__dirname, "../..");
const SVC = path.join(ROOT, "services/modbuilder");
const argv = process.argv.slice(2);
const flag = (n: string) => argv.includes(`--${n}`);
const opt = (n: string, d = "") => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : d; };
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const readJson = (f: string): unknown => { try { return JSON.parse(fs.readFileSync(f, "utf8")); } catch { return null; } };

/** The engine components of this tree (what an image built from it would contain). */
export function treeComponents(image: string, svc = SVC): ManifestComponents {
  const prompts = fs.readFileSync(path.join(svc, "prompts.js"), "utf8");
  const base = /const PROMPT_VERSION = "([^"]+)"/.exec(prompts)?.[1] ?? "unknown";
  const sheets = fs.readdirSync(path.join(svc, "sheets")).filter((f) => f.endsWith(".md")).sort().map((name) => ({ name, sha256: sha(fs.readFileSync(path.join(svc, "sheets", name))) }));
  const rulesBuf = fs.readFileSync(path.join(svc, "rules/failure-rules.json"));
  const sections: Record<string, string> = {};
  try { sections.recipes = require(path.join(svc, "recipes.js")).recipesVersion(); } catch { /* no recipe memory in this tree */ }
  try { sections.bank = require(path.join(svc, "bank.js")).bankVersion(); } catch { /* no starter bank in this tree */ }
  const [name, tag] = image.includes(":") ? image.split(":") : ["modbuilder", image];
  return {
    prompts: { base, sections }, sheets,
    rules: { version: String((JSON.parse(rulesBuf.toString("utf8")) as { version?: unknown }).version ?? "unknown"), sha256: sha(rulesBuf) },
    scanner: { profile: "strict", sha256: sha(fs.readFileSync(path.join(svc, "scan.js"))) },
    image: { name, tag: `${name}:${tag}` },
  };
}

function refs(): { against: "baseline" | "accepted"; name: string; rows: GateRow[] }[] {
  const out: { against: "baseline" | "accepted"; name: string; rows: GateRow[] }[] = [];
  const b = opt("baseline", path.join(SVC, "eval/baseline.json"));
  const bj = readJson(b);
  if (bj) out.push({ against: "baseline", name: path.relative(ROOT, b) || b, rows: rowsFromReference(bj) });
  const a = opt("accepted", path.join(SVC, "eval/gate-accepted.json"));
  const aj = readJson(a);
  if (aj) out.push({ against: "accepted", name: `${(aj as { tag?: string }).tag ?? "?"} (${path.relative(ROOT, a) || a})`, rows: rowsFromReference(aj) });
  return out;
}

async function realRows(tag: string): Promise<GateRow[]> {
  const budget = parseFloat(opt("budget", "0"));
  if (!(budget > 0)) throw new Error("--budget USD is required for a real run (it spends money: owner only)");
  const { loadEvalSet, loadMatrix } = await import("../../lib/cyrus/eval/set");
  const { planRun, runPlan } = await import("../../lib/cyrus/eval/run");
  const { evalFlight } = await import("../../lib/cyrus/eval/flight");
  const { modBuilderConfig } = await import("../../lib/modbuilder/client");
  const plan = planRun(loadEvalSet(), loadMatrix(), { versions: [...GATE_VERSIONS], keys: [...GATE_KEYS] }, { tag, model: "saka" });
  const cfg = modBuilderConfig();
  if (!cfg) throw new Error("no build service configured");
  const call = async (method: string, p: string, body?: unknown) => {
    const r = await fetch(cfg.url + p, { method, headers: { Authorization: `Bearer ${cfg.key}`, "Content-Type": "application/json" }, body: body === undefined ? undefined : JSON.stringify(body) });
    if (r.status === 404) return null;
    if (!r.ok) throw new Error(`${method} ${p}: HTTP ${r.status}`);
    return r;
  };
  const out = path.resolve(opt("out", "/root/cyrus-eval"));
  const run = flag("testflight") ? (await import("../../lib/cyrus/testflight/client")).runTestFlight : null;
  const s = await runPlan(plan, {
    submit: async (b) => (await (await call("POST", "/builds", b))!.json()) as { status?: string },
    get: async (id) => { const r = await call("GET", `/builds/${id}`); return r ? await r.json() : null; },
    flight: run ? (job, rec) => evalFlight(job.version, rec, { jarDir: path.join(out, tag, "jars"), run: (x) => run(x), artifact: async (id) => Buffer.from(await (await call("GET", `/builds/${id}/artifact`))!.arrayBuffer()) }) : undefined,
    log: (l) => console.log(l),
  }, { out, budgetUsd: budget, maxInFlight: 1 });
  return s.done.map((r) => ({ job: r.job, lane: r.lane, pass: r.pass, firstAttempt: r.firstAttempt, full: r.full, costUsd: r.costUsd, repairs: r.repairs, ...(r.infra ? { infra: true } : {}) }));
}

async function main() {
  const dry = flag("dry-run");
  const journal = opt("journal");
  const tag = opt("tag", dry ? "gate-dry" : journal ? "gate-recorded" : "");
  if (!tag || !/^[a-z0-9][a-z0-9-]{1,30}$/.test(tag)) throw new Error("--tag is required (2-31 chars [a-z0-9-])");
  const image = opt("image") || null;
  let rows: GateRow[] = [];
  let mode: GateVerdict["mode"] = "recorded";
  if (dry) {
    mode = "dry-run";
    const { loadEvalSet, loadMatrix } = await import("../../lib/cyrus/eval/set");
    const { planRun } = await import("../../lib/cyrus/eval/run");
    const plan = planRun(loadEvalSet(), loadMatrix(), { versions: [...GATE_VERSIONS], keys: [...GATE_KEYS] }, { tag: "gate-dry", model: "saka" });
    console.log(`DRY RUN eval gate: ${plan.jobs.length} builds (${GATE_JOBS.length} planned), estimate $${plan.estimate.low}-$${plan.estimate.high}. Nothing is submitted.`);
  } else if (journal) {
    const f = fs.existsSync(journal) && fs.statSync(journal).isDirectory() ? path.join(journal, "journal.jsonl") : journal;
    rows = rowsFromJournal(fs.readFileSync(f, "utf8"));
  } else {
    mode = "real";
    rows = await realRows(tag);
  }
  const v = gateVerdict({ tag, mode, image, rows, refs: refs() });
  const out = path.join(path.resolve(opt("out", "/root/cyrus-eval")), tag);
  fs.mkdirSync(out, { recursive: true });
  const body = JSON.stringify(v, null, 1) + "\n";
  fs.writeFileSync(path.join(out, "gate.json"), body);
  fs.writeFileSync(path.join(out, "gate.md"), verdictMarkdown(v));
  if (flag("accept")) {
    if (v.mode !== "real" && !flag("accept-recorded")) throw new Error("--accept takes a real run (add --accept-recorded to accept a re-scored journal on purpose)");
    fs.writeFileSync(path.join(SVC, "eval/gate-accepted.json"), body);
    console.log("accepted: services/modbuilder/eval/gate-accepted.json is now this run (commit it in a reviewed branch)");
  }
  if (flag("record-release")) {
    if (!image) throw new Error("--record-release needs --image modbuilder:X.Y");
    const file = path.join(SVC, "eval/engine-releases.json");
    const list = ((readJson(file) as { releases?: ReleaseManifest[] } | null)?.releases ?? []) as ReleaseManifest[];
    const fresh = createManifest({ components: treeComponents(image), status: "draft", notes: "recorded by eval-gate.ts" });
    const ref = { tag: v.tag, verdict: v.verdict, mode: v.mode, setVersion: v.setVersion, createdAt: v.createdAt, finalPassPct: v.totals.finalPassPct, passAt1Pct: v.totals.passAt1Pct, costPerPass: v.totals.costPerPass, regressions: Math.max(0, ...v.compare.map((c) => c.regressions.length)), file: path.join(out, "gate.json"), sha256: sha(body) };
    const next = recordImageVerdict(list, fresh.components.image.tag, ref, fresh);
    fs.writeFileSync(file, JSON.stringify({ schema: 1, releases: next }, null, 1) + "\n");
    console.log(`recorded the ${v.verdict} verdict on ${fresh.components.image.tag} in services/modbuilder/eval/engine-releases.json`);
  }
  if (flag("json")) console.log(body); else console.log(verdictMarkdown(v));
  console.log(`wrote ${out}/gate.json and gate.md`);
  process.exitCode = v.verdict === "fail" ? 3 : v.verdict === "warn" ? 1 : 0;
}

if (require.main === module) main().catch((e) => { console.error(`eval-gate: ${(e as Error).message}`); process.exit(2); });

