// Cyrus EVAL GATE: verdict maths (pass-rate deltas, cost ratio, regressions per lane, coverage), the recorded-journal mode on a
// fixture of the first measured run (eval first1: the 20 gate jobs), the engine release record per image, and the optional
// pre-promotion check in deploy-modbuilder.sh (failure path only: it must stop before touching the VM).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { execFileSync, spawnSync } from "node:child_process";
import { GATE_JOBS, GATE_KEYS, compareRuns, gateVerdict, metricsOf, rowsFromJournal, rowsFromReference, verdictMarkdown, type GateRow } from "../lib/cyrus/eval/gate";
import { loadEvalSet } from "../lib/cyrus/eval/set";
import { createManifest, imageGateStatus, recordImageVerdict, validateManifest } from "../lib/cyrus/learning/release-manifest";
import { treeComponents } from "../scripts/cyrus/eval-gate";

const FIX = path.join(__dirname, "fixtures/cyrus-eval-gate");
const journal = () => rowsFromJournal(fs.readFileSync(path.join(FIX, "journal.jsonl"), "utf8"));
const baseline = () => rowsFromReference(JSON.parse(fs.readFileSync(path.join(FIX, "baseline.json"), "utf8")));
const row = (job: string, lane: string, pass = true, firstAttempt = true, costUsd = 0.1, repairs = 0): GateRow => ({ job, lane, pass, firstAttempt, full: pass, costUsd, repairs });

describe("eval gate: the fixed subset", () => {
  it("20 prompts, every key in the eval set, every lane represented", () => {
    assert.equal(GATE_KEYS.length, 20);
    assert.equal(new Set(GATE_KEYS).size, 20);
    const set = new Map(loadEvalSet().map((p) => [p.key, p]));
    for (const k of GATE_KEYS) assert.ok(set.has(k), k);
    const lanes = new Set(journal().map((r) => r.lane));
    for (const l of ["plain", "texture", "sound", "designer"]) assert.ok(lanes.has(l), l);
  });
});

describe("eval gate: maths", () => {
  it("metrics: final pass, pass@1, cost per pass, repairs per build", () => {
    const m = metricsOf([row("a", "plain", true, true, 0.1), row("b", "plain", true, false, 0.3, 2), row("c", "plain", false, false, 0.2, 1), row("d", "plain", true, true, 0.2)]);
    assert.deepEqual([m.n, m.finalPassPct, m.passAt1Pct, m.costUsd, m.costPerPass, m.repairsPerBuild], [4, 75, 50, 0.8, 0.267, 0.75]);
    assert.equal(metricsOf([]).finalPassPct, null);
  });
  it("paired comparison: only common jobs, deltas in points, cost ratio, regressions per lane", () => {
    const ref = [row("a", "plain"), row("b", "plain"), row("c", "texture", true, false, 0.5, 1), row("x", "sound")];
    const now = [row("a", "plain", false, false, 0.2, 2), row("b", "plain", true, true, 0.05), row("c", "texture", true, true, 0.25), row("y", "sound")];
    const c = compareRuns(now, ref, "baseline", "ref");
    assert.equal(c.common, 3);
    assert.deepEqual(c.regressions, ["a"]);
    assert.deepEqual(c.byLane.plain.regressions, ["a"]);
    assert.equal(c.delta.finalPass, -33.3);
    assert.equal(c.delta.passAt1, 0);
    assert.equal(c.costRatio, 0.71, "0.5 / 2 passes now vs 0.7 / 3 passes before");
    assert.deepEqual(c.firstTryLost, []);
  });
  it("verdicts: pass, warn on one regression, fail on two or on a cost blow-up, fail on low coverage, no-reference without refs", () => {
    const jobs = GATE_JOBS.slice(0, 10);
    const ref = jobs.map((j) => row(j, "plain"));
    const planned = jobs;
    assert.equal(gateVerdict({ tag: "t", mode: "recorded", rows: ref, refs: [{ against: "baseline", name: "b", rows: ref }], planned }).verdict, "pass");
    const one = ref.map((r, i) => (i === 0 ? { ...r, pass: false, firstAttempt: false } : r));
    const v1 = gateVerdict({ tag: "t", mode: "recorded", rows: one, refs: [{ against: "baseline", name: "b", rows: ref }], planned });
    assert.equal(v1.verdict, "warn");
    assert.match(v1.reasons.join(" "), /1 job\(s\) that passed in the accepted baseline fail now/);
    const two = ref.map((r, i) => (i < 2 ? { ...r, pass: false } : r));
    assert.equal(gateVerdict({ tag: "t", mode: "recorded", rows: two, refs: [{ against: "baseline", name: "b", rows: ref }], planned }).verdict, "fail");
    const dear = ref.map((r) => ({ ...r, costUsd: 0.2 }));
    const vc = gateVerdict({ tag: "t", mode: "recorded", rows: dear, refs: [{ against: "accepted", name: "g", rows: ref }], planned });
    assert.equal(vc.verdict, "fail");
    assert.match(vc.reasons.join(" "), /cost per pass is 2x the last accepted gate run/);
    const few = gateVerdict({ tag: "t", mode: "recorded", rows: ref.slice(0, 5), refs: [{ against: "baseline", name: "b", rows: ref }], planned });
    assert.equal(few.verdict, "fail");
    assert.equal(few.coverage.missing.length, 5);
    const infra = gateVerdict({ tag: "t", mode: "recorded", rows: ref.map((r, i) => (i < 3 ? { ...r, infra: true } : r)), refs: [{ against: "baseline", name: "b", rows: ref }], planned });
    assert.equal(infra.verdict, "fail", "infrastructure failures do not count as scored");
    assert.deepEqual(infra.coverage.infra.length, 3);
    assert.equal(gateVerdict({ tag: "t", mode: "recorded", rows: ref, refs: [], planned }).verdict, "no-reference");
    assert.equal(gateVerdict({ tag: "t", mode: "dry-run", rows: [], refs: [], planned }).verdict, "fail", "a dry run never passes");
  });
  it("pass@1 drop thresholds: 10 points warn, 25 fail", () => {
    const jobs = GATE_JOBS.slice(0, 20);
    const ref = jobs.map((j) => row(j, "plain"));
    const lost = (n: number) => ref.map((r, i) => (i < n ? { ...r, firstAttempt: false, repairs: 1 } : r));
    assert.equal(gateVerdict({ tag: "t", mode: "recorded", rows: lost(2), refs: [{ against: "baseline", name: "b", rows: ref }], planned: jobs }).verdict, "warn");
    assert.equal(gateVerdict({ tag: "t", mode: "recorded", rows: lost(5), refs: [{ against: "baseline", name: "b", rows: ref }], planned: jobs }).verdict, "fail");
  });
});

describe("eval gate: recorded journal (eval first1 fixture)", () => {
  it("re-scoring the first measured run against its own baseline is a pass with the measured numbers", () => {
    const rows = journal();
    assert.equal(rows.length, 20);
    const v = gateVerdict({ tag: "rec-first1", mode: "recorded", image: "modbuilder:0.11", rows, refs: [{ against: "baseline", name: "first1", rows: baseline() }] });
    assert.equal(v.verdict, "pass", v.reasons.join("; "));
    assert.equal(v.coverage.scored, 20);
    assert.equal(v.totals.finalPassPct, 100);
    assert.equal(v.totals.passAt1Pct, 45);
    assert.ok(v.byLane.sound.passAt1Pct! < v.byLane.plain.passAt1Pct!, "sound repairs more than plain (as measured)");
    assert.equal(v.compare[0].common, 20);
    assert.deepEqual(v.compare[0].regressions, []);
    assert.match(verdictMarkdown(v), /Eval gate rec-first1: PASS/);
  });
  it("the same journal with two jobs turned into failures fails, with the lanes named", () => {
    const rows = journal().map((r) => (r.job.startsWith("m01-homes") || r.job.startsWith("s01-heal") ? { ...r, pass: false, firstAttempt: false, full: false } : r));
    const v = gateVerdict({ tag: "rec-bad", mode: "recorded", rows, refs: [{ against: "baseline", name: "first1", rows: baseline() }] });
    assert.equal(v.verdict, "fail");
    assert.deepEqual(v.compare[0].byLane.plain.regressions.sort(), ["m01-homes@1.21.11", "s01-heal@1.21.11"]);
  });
});

describe("eval gate: engine release record + deploy check", () => {
  const comps = () => treeComponents("modbuilder:0.12");
  it("the tree's components make a valid draft manifest with the recipe + bank versions as sections", () => {
    const c = comps();
    assert.equal(c.image.tag, "modbuilder:0.12");
    assert.match(c.prompts.sections.recipes, /^rcp-/);
    assert.match(c.prompts.sections.bank, /^bank-/);
    assert.deepEqual(validateManifest(createManifest({ components: c })), []);
  });
  it("a verdict is recorded on the image's release; only a real pass (or an allowed warn) may be promoted", () => {
    const fresh = createManifest({ components: comps(), now: new Date("2026-10-13T00:00:00Z") });
    const ref = (verdict: "pass" | "warn" | "fail", mode: "real" | "recorded" | "dry-run" = "real") => ({ tag: "g1", verdict, mode, setVersion: 1, createdAt: "2026-10-13T01:00:00Z", finalPassPct: 100, passAt1Pct: 50, costPerPass: 0.3, regressions: 0, file: "/x/gate.json", sha256: "0".repeat(64) });
    assert.equal(imageGateStatus([], "modbuilder:0.12").ok, false);
    let list = recordImageVerdict([], "modbuilder:0.12", ref("fail"), fresh);
    assert.equal(list.length, 1);
    assert.equal(list[0].id, fresh.id, "the verdict is not a component: the id stays");
    assert.equal(imageGateStatus(list, "modbuilder:0.12").ok, false);
    list = recordImageVerdict(list, "modbuilder:0.12", ref("warn"));
    assert.equal(list.length, 1, "updated in place");
    assert.equal(imageGateStatus(list, "modbuilder:0.12").ok, false);
    assert.equal(imageGateStatus(list, "modbuilder:0.12", { allowWarn: true }).ok, true);
    list = recordImageVerdict(list, "modbuilder:0.12", ref("pass", "dry-run"));
    assert.equal(imageGateStatus(list, "modbuilder:0.12").ok, false, "a dry run never promotes");
    list = recordImageVerdict(list, "modbuilder:0.12", ref("pass"));
    assert.equal(imageGateStatus(list, "modbuilder:0.12").ok, true);
    assert.throws(() => recordImageVerdict([], "modbuilder:0.13", ref("pass")), /no release manifest/);
  });
  it("deploy-modbuilder.sh with REQUIRE_EVAL_GATE=yes stops before contacting the VM when the image has no verdict", () => {
    const script = path.join(__dirname, "..", "scripts", "cyrus", "deploy-modbuilder.sh");
    const r = spawnSync("bash", [script], { encoding: "utf8", env: { PATH: process.env.PATH ?? "/usr/bin:/bin", REQUIRE_EVAL_GATE: "yes", TAG: "modbuilder:test-never-deployed", JUMP: "invalid.invalid", V: "invalid.invalid" } as unknown as NodeJS.ProcessEnv, timeout: 30000 });
    assert.equal(r.status, 1, r.stdout + r.stderr);
    assert.match(r.stdout, /Eval gate not passed for modbuilder:test-never-deployed: nothing was deployed/);
    assert.doesNotMatch(r.stdout, /1\/7 service must be idle/);
  });
  it("the runner script parses (dry-run / journal / real modes are wired)", () => {
    const src = fs.readFileSync(path.join(__dirname, "../scripts/cyrus/eval-gate.ts"), "utf8");
    for (const s of ["--dry-run", "--journal", "--budget", "--record-release", "--accept", "rowsFromJournal", "gateVerdict"]) assert.ok(src.includes(s), s);
    assert.ok(execFileSync("bash", ["-n", path.join(__dirname, "../scripts/cyrus/eval-gate-weekly.sh")]).length === 0);
  });
});

