// Cyrus learning loop: PATH MEMORY (prompt shape -> path -> cost, from anonymized signals) and the REVIEW QUEUE (accept / reject
// decisions, append-only, never applied). Pure, offline; signals come from synthetic ModBuild rows through deriveSignals.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { deriveSignals } from "../lib/cyrus/learning/signals";
import { toExportRecord } from "../lib/cyrus/learning/export";
import { PATH_MIN_N, buildPathMemory, pathCandidates, pathOf, statsOf } from "../lib/cyrus/learning/pathmemory";
import { CANDIDATE_KINDS, type Candidate } from "../lib/cyrus/learning/mining";
import { appendReview, foldReviews, parseReview, readReviews, reviewQueue } from "../lib/cyrus/learning/review";
import type { BuildRow } from "../lib/cyrus/learning/types";

const T0 = Date.parse("2026-10-13T00:00:00Z");
let n = 0;
/** One finished fresh build, an hour apart from the previous one (no rework window overlap). */
function row(o: { prompt: string; tier: string; cost: number; ok?: boolean; repairs?: number; effort?: string; recipes?: { ids: string[]; injected: boolean; holdback: boolean }; bank?: string; lanes?: string[] }): BuildRow {
  n++;
  const id = `mbpath${String(n).padStart(4, "0")}`;
  const at = T0 + n * 3_600_000;
  return {
    id, status: o.ok === false ? "failed" : "succeeded", errorCode: o.ok === false ? "compile" : null, prompt: o.prompt, rootBuildId: id, mcVersion: "1.21.11",
    costUsd: o.cost, attempts: 1 + (o.repairs ?? 0), durationMs: 60_000, createdAt: new Date(at), finishedAt: new Date(at + 60_000),
    cyrus: { model: o.tier, ...(o.lanes ? { assets: { requested: [], allowed: [], notices: [], planned: { lanes: o.lanes } } } : {}), ...(o.bank ? { bank: { id: o.bank, version: 1, via: "strict" } } : {}) },
    result: { repairs: o.repairs ?? 0, events: [], ai: { route: o.tier, calls: o.bank ? [] : [{ kind: "generate", model: o.tier === "katara" ? "claude-haiku-4-5" : "claude-sonnet-5", costUsd: o.cost, turns: 5, ...(o.effort ? { effort: o.effort } : {}) }], ...(o.recipes ? { recipes: { version: "rcp-x", ...o.recipes } } : {}) } },
  };
}
const HOMES = "Homes with /sethome and /home, saved between restarts.";

describe("path memory", () => {
  it("signals carry the prompt SHAPE as ids and buckets only, and the export has no text", () => {
    const [s] = deriveSignals([row({ prompt: HOMES, tier: "saka", cost: 0.2, recipes: { ids: ["safe-teleport"], injected: true, holdback: false }, effort: "medium" })]);
    assert.equal(s.archetype, "homes");
    assert.equal(s.complexity, "simple");
    assert.deepEqual(s.recipes, { ids: ["safe-teleport"], injected: true, holdback: false });
    assert.equal(s.effort, "medium");
    const exp = JSON.stringify(toExportRecord(s));
    assert.ok(!exp.includes("sethome") && !exp.includes(HOMES), "no request text in the anonymized export");
  });
  it("a bank build is its own path", () => {
    const [s] = deriveSignals([row({ prompt: "Keep inventory on death", tier: "katara", cost: 0, bank: "keep-inventory" })]);
    assert.equal(s.bankId, "keep-inventory");
    assert.equal(pathOf(s).path, "bank");
  });
  it("stats: kept rate, cost quantiles, cost per kept, rework demotion count", () => {
    const sigs = deriveSignals([row({ prompt: HOMES, tier: "saka", cost: 0.1 }), row({ prompt: HOMES, tier: "saka", cost: 0.3 }), row({ prompt: HOMES, tier: "saka", cost: 0.2, ok: false })]);
    const st = statsOf(sigs);
    assert.deepEqual([st.n, st.succeeded, st.kept, st.successRate, st.costUsd.p50, st.costPerKept], [3, 2, 2, 0.667, 0.2, 0.3]);
  });
  it("recommends the cheaper path that keeps as well, only with enough builds; the candidate is a review item", () => {
    const rows: BuildRow[] = [];
    for (let i = 0; i < 6; i++) rows.push(row({ prompt: HOMES, tier: "saka", cost: 0.4, effort: "high" }));
    for (let i = 0; i < 5; i++) rows.push(row({ prompt: HOMES, tier: "katara", cost: 0.1 }));
    const sigs = deriveSignals(rows);
    const pm = buildPathMemory(sigs);
    const r = pm.recommendations.find((x) => x.shape.archetype === "homes")!;
    assert.ok(r.n >= PATH_MIN_N && r.usable);
    assert.equal(r.current?.tier, "saka");
    assert.equal(r.best?.tier, "katara");
    assert.equal(r.savingPct, 0.75);
    assert.deepEqual(r.estimate, { typicalUsd: 0.4, upToUsd: 0.4 });
    const c = pathCandidates(sigs).find((x) => x.kind === "routing-hint")!;
    assert.ok(c, "a routing hint");
    assert.equal(c.status, "candidate");
    assert.match(c.title, /homes/);
    assert.equal(c.evidence.length, 5);
    const few = buildPathMemory(sigs.slice(0, 7)).recommendations.find((x) => x.shape.archetype === "homes")!;
    assert.equal(few.usable, false);
    assert.equal(few.best, null, "fewer than PATH_MIN_N builds: nothing is recommended");
  });
  it("a path with a rework in its last five is never 'best'", () => {
    const rows: BuildRow[] = [];
    for (let i = 0; i < 6; i++) rows.push(row({ prompt: HOMES, tier: "saka", cost: 0.4 }));
    for (let i = 0; i < 5; i++) rows.push(row({ prompt: HOMES, tier: "katara", cost: 0.1 }));
    // a change of the last katara build 5 minutes after it ended = rework
    const last = rows[rows.length - 1];
    rows.push({ ...row({ prompt: HOMES, tier: "katara", cost: 0.05 }), baseBuildId: last.id, rootBuildId: last.id, changeRequest: "also add /delhome", createdAt: new Date((last.finishedAt as Date).getTime() + 300_000), finishedAt: new Date((last.finishedAt as Date).getTime() + 400_000) });
    const r = buildPathMemory(deriveSignals(rows)).recommendations.find((x) => x.shape.archetype === "homes" && x.shape.kind === "fresh")!;
    assert.notEqual(r.best?.tier, "katara");
  });
  it("recipe A/B: injected vs holdback cost per kept success; recipe-gap, bank-gap and recipe-pitfall candidates", () => {
    const rows: BuildRow[] = [];
    for (let i = 0; i < 4; i++) rows.push(row({ prompt: HOMES, tier: "saka", cost: 0.2, repairs: 1, recipes: { ids: ["safe-teleport"], injected: true, holdback: false } }));
    for (let i = 0; i < 2; i++) rows.push(row({ prompt: HOMES, tier: "saka", cost: 0.4, recipes: { ids: ["safe-teleport"], injected: false, holdback: true } }));
    for (let i = 0; i < 6; i++) rows.push(row({ prompt: "An AFK system that marks idle players.", tier: "saka", cost: 0.5, repairs: 1 }));
    const sigs = deriveSignals(rows);
    const e = buildPathMemory(sigs).recipeEffects.find((x) => x.recipeId === "safe-teleport")!;
    assert.equal(e.n, 6);
    assert.equal(e.ratio, 0.5);
    const cands = pathCandidates(sigs, { recipeArchetypes: ["homes"], bankArchetypes: [] });
    const kinds = new Set(cands.map((c) => c.kind));
    assert.ok(cands.some((c) => c.kind === "recipe-gap" && /afk/.test(c.title)), "afk has no recipe and is repair-heavy");
    assert.ok(!cands.some((c) => c.kind === "recipe-gap" && /homes/.test(c.title)), "homes is covered");
    assert.ok(cands.some((c) => c.kind === "bank-gap" && /afk/.test(c.title)));
    assert.ok(kinds.has("recipe-pitfall"));
    for (const c of cands) assert.ok((CANDIDATE_KINDS as readonly string[]).includes(c.kind) && c.status === "candidate");
    assert.ok(!pathCandidates(sigs, { recipeArchetypes: ["homes"], bankArchetypes: ["afk"] }).some((c) => c.kind === "bank-gap"), "an existing bank entry closes the gap");
  });
});

describe("review queue", () => {
  const cand = (id: string, confidence: number): Candidate => ({ id, kind: "routing-hint", title: id, evidence: [], proposedText: "", confidence, rationale: "", status: "candidate", signal: "path-memory" });
  it("validates a decision: id, decision, reviewer; a rejection needs a reason", () => {
    assert.equal(parseReview({ candidateId: "nope", decision: "accepted", by: "u1" }).ok, false);
    assert.equal(parseReview({ candidateId: "0123456789ab", decision: "applied", by: "u1" }).ok, false);
    assert.equal(parseReview({ candidateId: "0123456789ab", decision: "rejected", by: "u1" }).ok, false);
    const r = parseReview({ candidateId: "0123456789ab", decision: "rejected", by: "u1", note: "  sample too small\u0007 " }, new Date("2026-10-13T10:00:00Z"));
    assert.ok(r.ok);
    if (r.ok) assert.deepEqual(r.review, { candidateId: "0123456789ab", decision: "rejected", by: "u1", at: "2026-10-13T10:00:00.000Z", note: "sample too small" });
  });
  it("the last decision wins, reopen returns it to the queue, open items come first", () => {
    const rv = (id: string, decision: "accepted" | "rejected" | "reopened", at: string) => ({ candidateId: id, decision, by: "u1", at, note: "x y z" });
    const reviews = [rv("aaaaaaaaaaaa", "accepted", "2026-10-13T01:00:00Z"), rv("bbbbbbbbbbbb", "rejected", "2026-10-13T01:00:00Z"), rv("bbbbbbbbbbbb", "reopened", "2026-10-13T02:00:00Z")];
    const st = foldReviews(reviews);
    assert.equal(st.get("aaaaaaaaaaaa")!.status, "accepted");
    assert.equal(st.get("bbbbbbbbbbbb")!.status, "candidate");
    assert.equal(st.get("bbbbbbbbbbbb")!.history.length, 2);
    const q = reviewQueue([cand("aaaaaaaaaaaa", 0.9), cand("bbbbbbbbbbbb", 0.2), cand("cccccccccccc", 0.5)], reviews);
    assert.deepEqual(q.map((c) => c.id), ["cccccccccccc", "bbbbbbbbbbbb", "aaaaaaaaaaaa"]);
  });
  it("the file store is append-only and survives a damaged line", () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "rv-"));
    try {
      const r = parseReview({ candidateId: "0123456789ab", decision: "accepted", by: "u1" });
      assert.ok(r.ok);
      if (r.ok) { appendReview(dir, r.review); appendReview(dir, { ...r.review, decision: "reopened", at: new Date(Date.now() + 1000).toISOString() }); }
      fs.appendFileSync(path.join(dir, "reviews.jsonl"), "{broken\n");
      const all = readReviews(dir);
      assert.equal(all.length, 2);
      assert.equal(foldReviews(all).get("0123456789ab")!.status, "candidate");
      assert.deepEqual(readReviews(path.join(dir, "missing")), []);
    } finally { fs.rmSync(dir, { recursive: true, force: true }); }
  });
});

